{"command":"mkdir -p /workspace && cd /workspace && cat > value.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strings"
)

// Value is one of: nil (null), bool, float64, *LitNum, string, []Value, *Object
type Value = any

type Object struct {
	keys []string
	vals []Value
	idx  map[string]int
}

const objIdxThreshold = 8

func NewObject() *Object { return &Object{} }

func (o *Object) Len() int { return len(o.keys) }

func (o *Object) find(k string) int {
	if o.idx != nil {
		if i, ok := o.idx[k]; ok {
			return i
		}
		return -1
	}
	for i, kk := range o.keys {
		if kk == k {
			return i
		}
	}
	return -1
}

func (o *Object) Get(k string) (Value, bool) {
	i := o.find(k)
	if i < 0 {
		return nil, false
	}
	return o.vals[i], true
}

func (o *Object) Has(k string) bool { return o.find(k) >= 0 }

func (o *Object) buildIdx() {
	if len(o.keys) > objIdxThreshold {
		o.idx = make(map[string]int, len(o.keys)*2)
		for i, k := range o.keys {
			o.idx[k] = i
		}
	} else {
		o.idx = nil
	}
}

// Copy returns a shallow copy of the object.
func (o *Object) Copy() *Object {
	n := &Object{
		keys: make([]string, len(o.keys), len(o.keys)+1),
		vals: make([]Value, len(o.vals), len(o.vals)+1),
	}
	copy(n.keys, o.keys)
	copy(n.vals, o.vals)
	if o.idx != nil {
		n.idx = make(map[string]int, len(o.idx)*2)
		for k, v := range o.idx {
			n.idx[k] = v
		}
	}
	return n
}

// SetInPlace mutates the object. Only use on freshly created/copied objects.
func (o *Object) SetInPlace(k string, v Value) {
	i := o.find(k)
	if i >= 0 {
		o.vals[i] = v
		return
	}
	o.keys = append(o.keys, k)
	o.vals = append(o.vals, v)
	if o.idx != nil {
		o.idx[k] = len(o.keys) - 1
	} else if len(o.keys) > objIdxThreshold {
		o.buildIdx()
	}
}

// Set returns a new object with the key set.
func (o *Object) Set(k string, v Value) *Object {
	n := o.Copy()
	n.SetInPlace(k, v)
	return n
}

// Delete returns a new object without key k.
func (o *Object) Delete(k string) *Object {
	i := o.find(k)
	if i < 0 {
		return o
	}
	n := &Object{
		keys: make([]string, 0, len(o.keys)),
		vals: make([]Value, 0, len(o.vals)),
	}
	n.keys = append(n.keys, o.keys[:i]...)
	n.keys = append(n.keys, o.keys[i+1:]...)
	n.vals = append(n.vals, o.vals[:i]...)
	n.vals = append(n.vals, o.vals[i+1:]...)
	n.buildIdx()
	return n
}

func (o *Object) Keys() []string { return o.keys }

func (o *Object) SortedKeys() []string {
	ks := make([]string, len(o.keys))
	copy(ks, o.keys)
	sort.Strings(ks)
	return ks
}

// ---- kinds ----

type Kind int

const (
	KindInvalid Kind = iota
	KindNull
	KindFalse
	KindTrue
	KindNumber
	KindString
	KindArray
	KindObject
)

func kindOf(v Value) Kind {
	switch x := v.(type) {
	case nil:
		return KindNull
	case bool:
		if x {
			return KindTrue
		}
		return KindFalse
	case float64, *LitNum:
		return KindNumber
	case string:
		return KindString
	case []Value:
		return KindArray
	case *Object:
		return KindObject
	}
	return KindInvalid
}

func kindName(k Kind) string {
	switch k {
	case KindNull:
		return "null"
	case KindFalse, KindTrue:
		return "boolean"
	case KindNumber:
		return "number"
	case KindString:
		return "string"
	case KindArray:
		return "array"
	case KindObject:
		return "object"
	}
	return "<unknown>"
}

func typeName(v Value) string { return kindName(kindOf(v)) }

func isNumber(v Value) bool {
	switch v.(type) {
	case float64, *LitNum:
		return true
	}
	return false
}

func numVal(v Value) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case *LitNum:
		return x.F
	}
	return 0
}

func truthy(v Value) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	}
	return true
}

// ---- comparison ----

func kindOrder(k Kind) int {
	// null < false < true < numbers < strings < arrays < objects
	return int(k)
}

func compareValues(a, b Value) int {
	ka, kb := kindOf(a), kindOf(b)
	if ka != kb {
		if kindOrder(ka) < kindOrder(kb) {
			return -1
		}
		return 1
	}
	switch ka {
	case KindNull, KindFalse, KindTrue:
		return 0
	case KindNumber:
		return compareNumbers(a, b)
	case KindString:
		return strings.Compare(a.(string), b.(string))
	case KindArray:
		aa, bb := a.([]Value), b.([]Value)
		for i := 0; i < len(aa) && i < len(bb); i++ {
			if c := compareValues(aa[i], bb[i]); c != 0 {
				return c
			}
		}
		if len(aa) < len(bb) {
			return -1
		} else if len(aa) > len(bb) {
			return 1
		}
		return 0
	case KindObject:
		oa, ob := a.(*Object), b.(*Object)
		ka := oa.SortedKeys()
		kb := ob.SortedKeys()
		// compare key sets first
		if c := compareValues(stringsToValues(ka), stringsToValues(kb)); c != 0 {
			return c
		}
		for _, k := range ka {
			va, _ := oa.Get(k)
			vb, _ := ob.Get(k)
			if c := compareValues(va, vb); c != 0 {
				return c
			}
		}
		return 0
	}
	return 0
}

func stringsToValues(ss []string) []Value {
	r := make([]Value, len(ss))
	for i, s := range ss {
		r[i] = s
	}
	return r
}

func compareNumbers(a, b Value) int {
	la, aok := a.(*LitNum)
	lb, bok := b.(*LitNum)
	if aok && bok {
		return la.Cmp(lb)
	}
	da, db := numVal(a), numVal(b)
	if math.IsNaN(da) {
		// nan compares as null vs number: less
		return -1
	}
	if math.IsNaN(db) {
		return 1
	}
	if da < db {
		return -1
	} else if da == db {
		return 0
	}
	return 1
}

func valuesEqual(a, b Value) bool {
	ka, kb := kindOf(a), kindOf(b)
	if ka != kb {
		return false
	}
	switch ka {
	case KindNull, KindFalse, KindTrue:
		return true
	case KindNumber:
		return compareNumbers(a, b) == 0
	case KindString:
		return a.(string) == b.(string)
	case KindArray:
		aa, bb := a.([]Value), b.([]Value)
		if len(aa) != len(bb) {
			return false
		}
		for i := range aa {
			if !valuesEqual(aa[i], bb[i]) {
				return false
			}
		}
		return true
	case KindObject:
		oa, ob := a.(*Object), b.(*Object)
		if oa.Len() != ob.Len() {
			return false
		}
		for i, k := range oa.keys {
			vb, ok := ob.Get(k)
			if !ok || !valuesEqual(oa.vals[i], vb) {
				return false
			}
		}
		return true
	}
	return false
}

// identical mimics jv_identical loosely: pointer identity for containers,
// value identity for scalars.
func identical(a, b Value) bool {
	switch x := a.(type) {
	case nil:
		return b == nil
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case float64:
		y, ok := b.(float64)
		return ok && (x == y || (math.IsNaN(x) && math.IsNaN(y)))
	case *LitNum:
		y, ok := b.(*LitNum)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case []Value:
		y, ok := b.([]Value)
		if !ok || len(x) != len(y) {
			return false
		}
		if len(x) == 0 {
			return true
		}
		return &x[0] == &y[0]
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	}
	return false
}

func sortValues(vs []Value) {
	sort.SliceStable(vs, func(i, j int) bool {
		return compareValues(vs[i], vs[j]) < 0
	})
}
EOF
echo done"}

