package main

import (
	"math"
	"strconv"
	"strings"
)

// LitNum is a number that retains its original decimal literal (like jq's decNumber support).
type LitNum struct {
	F    float64
	Neg  bool
	Coef string // decimal digits, no leading zeros ("0" for zero)
	Exp  int    // value = Coef * 10^Exp
}

const (
	decEmax  = 999999999
	decEtiny = -1147483646
)

// parseDecimalLiteral parses a numeric literal the way jq's number parser does.
// It accepts an optional sign, digits with optional fraction, optional exponent,
// and also the special values NaN/Infinity (case-insensitive).
// Returns a Value (either *LitNum or float64) and ok.
func parseDecimalLiteral(s string) (Value, bool) {
	if s == "" {
		return nil, false
	}
	i := 0
	neg := false
	if s[i] == '+' || s[i] == '-' {
		neg = s[i] == '-'
		i++
	}
	rest := s[i:]
	if rest == "" {
		return nil, false
	}
	// special values
	if !(rest[0] >= '0' && rest[0] <= '9') && rest[0] != '.' {
		lr := strings.ToLower(rest)
		switch lr {
		case "nan", "snan":
			return math.NaN(), true
		case "inf", "infinity":
			if neg {
				return math.Inf(-1), true
			}
			return math.Inf(1), true
		}
		return nil, false
	}
	var digits []byte
	fracDigits := 0
	seenDot := false
	seenDigit := false
	j := 0
	for j < len(rest) {
		c := rest[j]
		if c >= '0' && c <= '9' {
			digits = append(digits, c)
			seenDigit = true
			if seenDot {
				fracDigits++
			}
			j++
		} else if c == '.' && !seenDot {
			seenDot = true
			j++
		} else {
			break
		}
	}
	if !seenDigit {
		return nil, false
	}
	exp := 0
	if j < len(rest) {
		c := rest[j]
		if c != 'e' && c != 'E' {
			return nil, false
		}
		j++
		if j >= len(rest) {
			return nil, false
		}
		eneg := false
		if rest[j] == '+' || rest[j] == '-' {
			eneg = rest[j] == '-'
			j++
		}
		if j >= len(rest) {
			return nil, false
		}
		var ev int64
		overflow := false
		for ; j < len(rest); j++ {
			c := rest[j]
			if c < '0' || c > '9' {
				return nil, false
			}
			if !overflow {
				ev = ev*10 + int64(c-'0')
				if ev > 1<<40 {
					overflow = true
				}
			}
		}
		if overflow {
			ev = 1 << 40
		}
		if eneg {
			ev = -ev
		}
		exp = int(ev)
	}
	exp -= fracDigits
	// strip leading zeros
	k := 0
	for k < len(digits)-1 && digits[k] == '0' {
		k++
	}
	coef := string(digits[k:])
	return makeLitNum(neg, coef, exp), true
}

// makeLitNum builds a literal number, applying decNumber-like exponent clamping.
func makeLitNum(neg bool, coef string, exp int) Value {
	if coef == "0" {
		if exp > decEmax {
