	// fast path
	if utf8.ValidString(s) {
		// Go's ValidString rejects surrogates and > 0x10FFFF, overlongs, so this matches
		return s
	}
	var sb strings.Builder
	sb.Grow(len(s) + 8)
	i := 0
	n := len(s)
	for i < n {
		first := s[i]
		if first < 0x80 {
			sb.WriteByte(first)
			i++
			continue
		}
		length := utf8CodingLength(first)
		cp := -1
		if length <= 0 {
			length = 1
		} else if i+length > n {
			length = n - i
		} else {
			cp = int(first) & (0xFF >> (length + 1))
			for j := 1; j < length; j++ {
				ch := s[i+j]
				if utf8CodingLength(ch) != -1 {
					cp = -1
					length = j
					break
				}
				cp = (cp << 6) | int(ch&0x3f)
			}
			if cp >= 0 {
				if cp < utf8FirstCodepoint[length] {
					cp = -1
				} else if cp >= 0xD800 && cp <= 0xDFFF {
					cp = -1
				} else if cp > 0x10FFFF {
					cp = -1
				}
			}
		}
		if cp < 0 {
			sb.WriteString("\uFFFD")
		} else {
			sb.WriteString(s[i : i+length])
		}
		i += length
	}
	return sb.String()
}

// ---- JSON parser ----

type parserState int

const (
	psNormal parserState = iota
	psString
	psStringEscape
	psWaitingForRS
)

type lastSeen int

const (
	lsNone lastSeen = iota
	lsOpenArray
	lsOpenObject
	lsColon
	lsComma
	lsValue
)

type JSONParser struct {
	streaming    bool
	seq          bool
	streamErrors bool

	st           parserState
	stack        []Value
	next         Value
	hasNext      bool
	token        []byte
	line, column int
	lastChWasWS  bool

	// streaming mode
	path      []Value
	stacklen  int
	last      lastSeen
	output    Value
	hasOutput bool
	outputTail bool // whether output is a "3-element" (needs closing event)

	buf        []byte
	bufPos     int
	bufPartial bool
	eof        bool
	bomPos     int
}

var errOK = fmt.Errorf("ok")

func NewJSONParser(streaming, seq, streamErrors bool) *JSONParser {
	p := &JSONParser{streaming: streaming, seq: seq, streamErrors: streamErrors}
	p.reset()
	p.line = 1
	p.column = 0
	if seq {
		p.st = psWaitingForRS
	}
	return p
}

func (p *JSONParser) reset() {
	p.st = psNormal
	p.stack = p.stack[:0]
	p.next = nil
	p.hasNext = false
	p.token = p.token[:0]
	p.path = p.path[:0]
	p.stacklen = 0
	p.last = lsNone
	p.output = nil
	p.hasOutput = false
	p.outputTail = false
}

// SetBuf provides the next chunk of input. partial indicates more data may follow.
func (p *JSONParser) SetBuf(b []byte, partial bool) {
	p.buf = b
	p.bufPos = 0
	p.bufPartial = partial
}

func (p *JSONParser) RemainingBuffer() bool {
	return p.buf != nil && p.bufPos < len(p.buf)
}

// ParseError is a JSON syntax error with jq's message format.
type ParseError struct {
	Msg string
}

func (e *ParseError) Error() string { return e.Msg }

func (p *JSONParser) makeError(format string, args ...any) (Value, error) {
	msg := fmt.Sprintf(format, args...)
	if p.streamErrors {
		path := make([]Value, len(p.path))
		copy(path, p.path)
		return []Value{msg, path}, nil
	}
	return nil, &ParseError{Msg: msg}
}

func (p *JSONParser) setValue(val Value) string {
	if p.streaming {
		if p.hasNext || p.last == lsValue {
			return "Expected separator between values"
		}
		if p.stacklen > 0 {
			p.last = lsValue
		} else {
			p.last = lsNone
		}
	} else {
		if p.hasNext {
			return "Expected separator between values"
		}
	}
	p.next = val
	p.hasNext = true
	return ""
}

func (p *JSONParser) checkLiteral() string {
	if len(p.token) == 0 {
		return ""
	}
	var pattern string
	var v Value
	switch p.token[0] {
	case 't':
		pattern, v = "true", true
	case 'f':
		pattern, v = "false", false
	case '\'':
		return "Invalid string literal; expected \", but got '"
	case 'n':
		if len(p.token) > 1 && p.token[1] == 'u' {
			pattern, v = "null", nil
		}
	}
	if pattern != "" {
		if string(p.token) != pattern {
			return "Invalid literal"
		}
		if msg := p.setValue(v); msg != "" {
			return msg
		}
	} else {
		num, ok := parseDecimalLiteral(string(p.token))
		if !ok {
			return "Invalid numeric literal"
		}
		if msg := p.setValue(num); msg != "" {
			return msg
		}
	}
	p.token = p.token[:0]
	return ""
}

const maxParseDepth = 10000

func (p *JSONParser) tokenChar(ch byte) string {
	switch ch {
	case '[':
		if len(p.stack) >= maxParseDepth {
			return "Exceeds depth limit for parsing"
		}
		if p.hasNext {
			return "Expected separator between values"
		}
		p.stack = append(p.stack, []Value{})
	case '{':
		if len(p.stack) >= maxParseDepth {
			return "Exceeds depth limit for parsing"
		}
		if p.hasNext {
			return "Expected separator between values"
		}
		p.stack = append(p.stack, NewObject())
	case ':':
		if len(p.stack) == 0 || !p.hasNext {
			return "Expected string key before ':'"
		}
		if _, ok := p.stack[len(p.stack)-1].(*Object); !ok {
			return "':' not as part of an object"
		}
		if _, ok := p.next.(string); !ok {
			return "Object keys must be strings"
		}
		p.stack = append(p.stack, p.next)
		p.next = nil
		p.hasNext = false
	case ',':
		if !p.hasNext {
			return "Expected value before ','"
		}
		if len(p.stack) == 0 {
			return "',' not as part of an object or array"
		}
		top := p.stack[len(p.stack)-1]
		switch t := top.(type) {
		case []Value:
			p.stack[len(p.stack)-1] = append(t, p.next)
			p.next = nil
			p.hasNext = false
		case string:
			obj := p.stack[len(p.stack)-2].(*Object)
			obj.SetInPlace(t, p.next)
			p.stack = p.stack[:len(p.stack)-1]
			p.next = nil
			p.hasNext = false
		default:
			return "Objects must consist of key:value pairs"
		}
	case ']':
		if len(p.stack) == 0 {
			return "Unmatched ']'"
		}
		arr, ok := p.stack[len(p.stack)-1].([]Value)
		if !ok {
			return "Unmatched ']'"
		}
		if p.hasNext {
			arr = append(arr, p.next)
			p.next = nil
			p.hasNext = false
		} else if len(arr) != 0 {
			return "Expected another array element"
		}
		p.stack = p.stack[:len(p.stack)-1]
		p.next = arr
		p.hasNext = true
	case '}':
		if len(p.stack) == 0 {
			return "Unmatched '}'"
		}
		top := p.stack[len(p.stack)-1]
		if p.hasNext {
			key, ok := top.(string)
			if !ok {
				return "Objects must consist of key:value pairs"
			}
			obj := p.stack[len(p.stack)-2].(*Object)
			obj.SetInPlace(key, p.next)
			p.stack = p.stack[:len(p.stack)-1]
			p.next = nil
			p.hasNext = false
		} else {
			obj, ok := top.(*Object)
			if !ok {
				return "Unmatched '}'"
			}
			if obj.Len() != 0 {
				return "Expected another key-value pair"
			}
		}
		obj := p.stack[len(p.stack)-1]
		p.stack = p.stack[:len(p.stack)-1]
		p.next = obj
		p.hasNext = true
	}
	return ""
}

func (p *JSONParser) streamTokenChar(ch byte) string {
	switch ch {
	case '[':
		if p.hasNext {
			return "Expected a separator between values"
		}
		p.path = append(p.path, float64(0))
		p.last = lsOpenArray
		p.stacklen++
	case '{':
		if p.last == lsValue {
			return "Expected a separator between values"
		}
		p.path = append(p.path, nil)
		p.last = lsOpenObject
		p.stacklen++
	case ':':
		if p.stacklen == 0 {
			return "':' not as part of an object"
		}
		if _, isNum := p.path[p.stacklen-1].(float64); isNum {
			return "':' not as part of an object"
		}
		if !p.hasNext || p.last == lsNone {
			return "Expected string key before ':'"
		}
		if _, ok := p.next.(string); !ok {
			return "Object keys must be strings"
		}
		if p.last != lsValue {
			return "':' should follow a key"
		}
		p.last = lsColon
		p.path[p.stacklen-1] = p.next
		p.next = nil
		p.hasNext = false
	case ',':
		if p.last != lsValue {
			return "Expected value before ','"
		}
		if p.stacklen == 0 {
			return "',' not as part of an object or array"
		}
		last := p.path[p.stacklen-1]
		switch l := last.(type) {
		case float64:
			if p.hasNext {
				p.output = []Value{copyPath(p.path), p.next}
				p.hasOutput = true
				p.outputTail = false
				p.next = nil
				p.hasNext = false
			}
			p.path[p.stacklen-1] = l + 1
			p.last = lsComma
		case string:
			if p.hasNext {
				p.output = []Value{copyPath(p.path), p.next}
				p.hasOutput = true
				p.outputTail = false
				p.next = nil
				p.hasNext = false
			}
			p.path[p.stacklen-1] = true
			p.last = lsComma
		default:
			return "Objects must consist of key:value pairs"
		}
	case ']':
		if p.stacklen == 0 {
			return "Unmatched ']' at the top-level"
		}
		if p.last == lsComma {
			return "Expected another array element"
		}
		last := p.path[p.stacklen-1]
		if _, isNum := last.(float64); !isNum {
			return "Unmatched ']' in the middle of an object"
		}
		if p.hasNext {
			p.output = []Value{copyPath(p.path), p.next}
			p.hasOutput = true
			p.outputTail = true
			p.next = nil
			p.hasNext = false
		} else if p.last != lsOpenArray {
			p.output = []Value{copyPath(p.path)}
			p.hasOutput = true
			p.outputTail = false
		}
		p.stacklen--
		p.path = p.path[:p.stacklen]
		p.next = nil
		p.hasNext = false
		if p.last == lsOpenArray {
			p.output = []Value{copyPath(p.path), []Value{}}
			p.hasOutput = true
			p.outputTail = false
		}
		if p.stacklen == 0 {
			p.last = lsNone
		} else {
			p.last = lsValue
		}
	case '}':
		if p.stacklen == 0 {
			return "Unmatched '}' at the top-level"
		}
		if p.last == lsComma {
			return "Expected another key:value pair"
		}
		last := p.path[p.stacklen-1]
		if _, isNum := last.(float64); isNum {
			return "Unmatched '}' in the middle of an array"
		}
		if p.hasNext {
			if _, ok := last.(string); !ok {
				return "Objects must consist of key:value pairs"
			}
			p.output = []Value{copyPath(p.path), p.next}
			p.hasOutput = true
			p.outputTail = true
			p.next = nil
			p.hasNext = false
		} else {
			if p.last == lsColon {
				return "Missing value in key:value pair"
			}
			if p.last == lsComma {
				return "Expected another key-value pair"
			}
			if p.last == lsOpenArray {
				return "Unmatched '}' in the middle of an array"
			}
			if p.last != lsValue && p.last != lsOpenObject {
				return "Unmatched '}'"
			}
			if p.last != lsOpenObject {
				p.output = []Value{copyPath(p.path)}
				p.hasOutput = true
				p.outputTail = false
			}
		}
		p.stacklen--
		p.path = p.path[:p.stacklen]
		p.next = nil
		p.hasNext = false
		if p.last == lsOpenObject {
			p.output = []Value{copyPath(p.path), NewObject()}
			p.hasOutput = true
			p.outputTail = false
		}
		if p.stacklen == 0 {
			p.last = lsNone
		} else {
			p.last = lsValue
		}
	}
	return ""
}

func copyPath(p []Value) []Value {
	r := make([]Value, len(p))
	copy(r, p)
	return r
}

// checkDone returns a completed value if available.
func (p *JSONParser) checkDone() (Value, bool) {
	if p.streaming {
		return p.streamCheckDone()
	}
	if len(p.stack) == 0 && p.hasNext {
		v := p.next
		p.next = nil
		p.hasNext = false
		return v, true
	}
	return nil, false
}

func (p *JSONParser) streamCheckDone() (Value, bool) {
	if p.stacklen == 0 && p.hasNext {
		v := []Value{copyPath(p.path), p.next}
		p.next = nil
		p.hasNext = false
		return v, true
	} else if p.hasOutput {
		out := p.output.([]Value)
		if p.outputTail {
			// emit [path, leaf], then keep [path] pending
			p.output = []Value{out[0]}
			p.outputTail = false
			return []Value{out[0], out[1]}, true
		}
		p.output = nil
		p.hasOutput = false
		return out, true
	}
	return nil, false
}

func (p *JSONParser) foundString() string {
	// unescape token
	tok := p.token
	var sb strings.Builder
	sb.Grow(len(tok))
	i := 0
	for i < len(tok) {
		c := tok[i]
		if c == '\\' {
			i++
			if i >= len(tok) {
				return "Expected escape character at end of string"
			}
			e := tok[i]
			i++
			switch e {
			case '\\', '"', '/':
				sb.WriteByte(e)
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 't':
				sb.WriteByte('\t')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 'u':
				if i+4 > len(tok) {
					return "Invalid \\uXXXX escape"
				}
				cp, ok := parseHex4(tok[i : i+4])
				if !ok {
					return "Invalid characters in \\uXXXX escape"
				}
				i += 4
				if cp >= 0xD800 && cp <= 0xDBFF {
					// high surrogate: need low surrogate
					if i+6 > len(tok) || tok[i] != '\\' || tok[i+1] != 'u' {
						return "Invalid \\uXXXX\\uXXXX surrogate pair escape"
					}
					lo, ok := parseHex4(tok[i+2 : i+6])
					if !ok || lo < 0xDC00 || lo > 0xDFFF {
						return "Invalid \\uXXXX\\uXXXX surrogate pair escape"
					}
					i += 6
					cp = 0x10000 + (((cp & 0x3FF) << 10) | (lo & 0x3FF))
				} else if cp >= 0xDC00 && cp <= 0xDFFF {
					cp = 0xFFFD
				}
				sb.WriteRune(rune(cp))
			default:
				return "Invalid escape"
			}
		} else {
			if c < 0x20 {
				return "Invalid string: control characters from U+0000 through U+001F must be escaped"
			}
			sb.WriteByte(c)
			i++
		}
	}
	s := sanitizeUTF8(sb.String())
	p.token = p.token[:0]
	return p.setValue(s)
}

func parseHex4(b []byte) (int, bool) {
	v := 0
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v |= int(c - '0')
		case c >= 'a' && c <= 'f':
			v |= int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v |= int(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

func (p *JSONParser) checkTruncation() bool {
	if !p.seq {
		return false
	}
	if p.lastChWasWS {
		return false
	}
	_, nextIsNum := p.next.(float64)
	if !nextIsNum {
		_, nextIsNum = p.next.(*LitNum)
	}
	return len(p.stack) > 0 || p.stacklen > 0 || len(p.token) > 0 || (p.hasNext && nextIsNum)
}

func (p *JSONParser) isTopNum() bool {
	if len(p.stack) > 0 || p.stacklen > 0 {
		return false
	}
	return p.hasNext && isNumber(p.next)
}

// scan processes one char. Returns (value, done, errmsg).
func (p *JSONParser) scan(ch byte) (Value, bool, string) {
	p.column++
	if ch == '\n' {
		p.line++
		p.column = 0
	}
	if ch == 0x1e && p.seq {
		if p.checkTruncation() {
			if p.checkLiteral() == "" && p.isTopNum() {
				return nil, false, "Potentially truncated top-level numeric value"
			}
			return nil, false, "Truncated value"
		}
		if msg := p.checkLiteral(); msg != "" {
			return nil, false, msg
		}
		if p.st == psNormal {
			if v, ok := p.checkDone(); ok {
				return v, true, ""
			}
		}
		p.reset()
		return nil, false, ""
	}
	var out Value
	done := false
	p.lastChWasWS = false
	if p.st == psNormal {
		isWS := ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n'
		isStructure := ch == '[' || ch == ',' || ch == ']' || ch == '{' || ch == ':' || ch == '}'
		isQuote := ch == '"'
		if isWS {
			p.lastChWasWS = true
		}
		if isWS || isStructure || isQuote {
			if msg := p.checkLiteral(); msg != "" {
				return nil, false, msg
			}
			if v, ok := p.checkDone(); ok {
				out, done = v, true
			}
		}
		switch {
		case isWS:
		case isQuote:
			p.st = psString
		case isStructure:
			var msg string
			if p.streaming {
				msg = p.streamTokenChar(ch)
			} else {
				msg = p.tokenChar(ch)
			}
			if msg != "" {
				return out, done, msg
			}
		default:
			p.token = append(p.token, ch)
		}
		if !done {
			if v, ok := p.checkDone(); ok {
				out, done = v, true
			}
		}
	} else {
		if ch == '"' && p.st == psString {
			if msg := p.foundString(); msg != "" {
				return nil, false, msg
			}
			p.st = psNormal
			if v, ok := p.checkDone(); ok {
				out, done = v, true
			}
		} else {
			p.token = append(p.token, ch)
			if ch == '\\' && p.st == psString {
				p.st = psStringEscape
			} else {
				p.st = psString
			}
		}
	}
	return out, done, ""
}

// Next returns the next parsed value. Returns (value, true, nil) when a value
// is available, (nil, false, nil) when more input is needed or EOF reached with
// nothing more, or (nil, false, err) on error.
func (p *JSONParser) Next() (Value, bool, error) {
	if p.eof {
		return nil, false, nil
	}
	if p.buf == nil {
		return nil, false, nil
	}
	if p.streaming {
		if v, ok := p.streamCheckDone(); ok {
			return v, true, nil
		}
	}
	var ch byte
	for p.bufPos < len(p.buf) {
		ch = p.buf[p.bufPos]
		p.bufPos++
		if p.st == psWaitingForRS {
			if ch == '\n' {
				p.line++
				p.column = 0
			} else {
				p.column++
			}
			if ch == 0x1e {
				p.st = psNormal
			}
			continue
		}
		v, done, msg := p.scan(ch)
		if msg != "" {
			if ch != 0x1e && p.seq {
				p.st = psWaitingForRS
				ev, err := p.makeError("%s at line %d, column %d (need RS to resync)", msg, p.line, p.column)
				p.resetKeepSt(psWaitingForRS)
				if err == nil {
					return ev, true, nil
				}
				return nil, false, err
			}
			ev, err := p.makeError("%s at line %d, column %d", msg, p.line, p.column)
			p.reset()
			if !p.seq {
				p.buf = nil
				p.bufPos = 0
			}
			if err == nil {
				return ev, true, nil
			}
			return nil, false, err
		}
		if done {
			return v, true, nil
		}
	}
	if p.bufPartial {
		return nil, false, nil
	}
	// EOF
	p.eof = true
	if p.st == psWaitingForRS {
		ev, err := p.makeError("Unfinished abandoned text at EOF at line %d, column %d", p.line, p.column)
		if err == nil {
			return ev, true, nil
		}
		return nil, false, err
	}
	if p.st != psNormal {
		ev, err := p.makeError("Unfinished string at EOF at line %d, column %d", p.line, p.column)
		p.reset()
		p.st = psWaitingForRS
		if err == nil {
			return ev, true, nil
		}
		return nil, false, err
	}
	if msg := p.checkLiteral(); msg != "" {
		ev, err := p.makeError("%s at EOF at line %d, column %d", msg, p.line, p.column)
		p.reset()
		p.st = psWaitingForRS
		if err == nil {
			return ev, true, nil
		}
		return nil, false, err
	}
	if (p.streaming && p.stacklen != 0) || (!p.streaming && len(p.stack) != 0) {
		ev, err := p.makeError("Unfinished JSON term at EOF at line %d, column %d", p.line, p.column)
		p.reset()
		p.st = psWaitingForRS
		if err == nil {
			return ev, true, nil
		}
		return nil, false, err
	}
	var value Value
	has := false
	if p.streaming && p.hasNext {
		value = []Value{copyPath(p.path), p.next}
		has = true
	} else if p.hasNext {
		value = p.next
		has = true
	}
	p.next = nil
	p.hasNext = false
	if has && p.seq && !p.lastChWasWS && isNumber(value) {
		ev, err := p.makeError("Potentially truncated top-level numeric value at EOF at line %d, column %d", p.line, p.column)
		if err == nil {
			return ev, true, nil
		}
		return nil, false, err
	}
	if has {
		return value, true, nil
	}
	return nil, false, nil
}

func (p *JSONParser) resetKeepSt(st parserState) {
	p.reset()
	p.st = st
}

// parseJSONAll parses a complete text and returns all values (used by --slurpfile etc).
func parseJSONAll(text string) ([]Value, error) {
	p := NewJSONParser(false, false, false)
	p.SetBuf([]byte(text), false)
	var vals []Value
	for {
		v, ok, err := p.Next()
		if err != nil {
			return nil, err
		}
		if !ok {
			break
		}
		vals = append(vals, v)
	}
	return vals, nil
}

// parseJSONOne implements jv_parse_sized semantics (fromjson, --argjson).
func parseJSONOne(text string) (Value, error) {
	p := NewJSONParser(false, false, false)
	p.SetBuf([]byte(text), false)
	v, ok, err := p.Next()
	var result Value
	var rerr error
	if err != nil {
		rerr = err
	} else if !ok {
		rerr = &ParseError{Msg: "Expected JSON value"}
	} else {
		result = v
		v2, ok2, err2 := p.Next()
		if err2 != nil {
			rerr = err2
		} else if ok2 {
			_ = v2
			rerr = &ParseError{Msg: "Unexpected extra JSON values"}
		}
	}
	if rerr != nil {
		return nil, &ParseError{Msg: fmt.Sprintf("%s (while parsing '%s')", rerr.Error(), text)}
	}
	return result, nil
}

