func parseColors(spec string) (ColorSet, bool) {
	cs := defaultColors
	fields := []*string{&cs.Null, &cs.False, &cs.True, &cs.Number, &cs.String, &cs.Array, &cs.Object, &cs.Field}
	i := 0
	for i < len(fields) && spec != "" {
		var f string
		if k := strings.IndexByte(spec, ':'); k >= 0 {
			f = spec[:k]
			spec = spec[k+1:]
		} else {
			f = spec
			spec = ""
		}
		if len(f) > 12 {
			return defaultColors, false
		}
		for _, c := range []byte(f) {
			if !(c >= '0' && c <= '9') && c != ';' {
				return defaultColors, false
			}
		}
		*fields[i] = "\x1b[" + f + "m"
		i++
	}
	return cs, true
}

