}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// lexAll tokenizes the whole program, handling string interpolation nesting.
func lexAll(src string) ([]Token, error) {
	lx := &Lexer{src: src}
	if err := lx.lexUntil(0, -1); err != nil {
		return nil, err
	}
	lx.tokens = append(lx.tokens, Token{Kind: TEOF, Pos: len(src), End: len(src)})
	return lx.tokens, nil
}

func (lx *Lexer) emit(k TokKind, start, end int) {
	lx.tokens = append(lx.tokens, Token{Kind: k, Text: lx.src[start:end], Pos: start, End: end})
}

// lexUntil lexes tokens; depth tracks paren nesting inside a string interpolation.
// If inInterp is >= 0, lexing stops when the matching ')' is found (at depth 0).
func (lx *Lexer) lexUntil(depth int, inInterp int) error {
	src := lx.src
	parenDepth := 0
	for lx.pos < len(src) {
		c := src[lx.pos]
		start := lx.pos
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			lx.pos++
		case c == '#':
			// comment: ends at newline, backslash escapes next char (including newline)
			lx.pos++
			for lx.pos < len(src) {
				if src[lx.pos] == '\\' {
					lx.pos += 2
					continue
				}
				if src[lx.pos] == '\n' {
					break
				}
				lx.pos++
			}
			if lx.pos > len(src) {
				lx.pos = len(src)
			}
		case c == '"':
			lx.pos++
			lx.emit(TQQStart, start, lx.pos)
			if err := lx.lexString(); err != nil {
				return err
			}
		case c == '.':
			if lx.pos+1 < len(src) && src[lx.pos+1] == '.' {
				lx.pos += 2
				lx.emit(TPunct, start, lx.pos)
			} else if lx.pos+1 < len(src) && isIdentStart(src[lx.pos+1]) {
				lx.pos++
				for lx.pos < len(src) && isIdentChar(src[lx.pos]) {
					lx.pos++
				}
				lx.emit(TField, start, lx.pos)
			} else if lx.pos+1 < len(src) && isDigit(src[lx.pos+1]) {
				lx.lexNumber()
			} else {
				lx.pos++
				lx.emit(TPunct, start, lx.pos)
			}
		case isDigit(c):
			lx.lexNumber()
		case c == '$':
			// $__loc__ or binding
			p := lx.pos + 1
			if strings.HasPrefix(src[p:], "__loc__") && (p+7 >= len(src) || !isIdentChar(src[p+7])) {
				lx.pos = p + 7
				lx.emit(TLoc, start, lx.pos)
			} else if p < len(src) && isIdentStart(src[p]) {
				lx.pos = p
				lx.lexIdentBody()
				lx.emit(TBinding, start, lx.pos)
			} else {
				lx.pos++
				lx.emit(TPunct, start, lx.pos)
			}
		case c == '@':
			p := lx.pos + 1
			for p < len(src) && isIdentChar(src[p]) {
				p++
			}
			if p == lx.pos+1 {
				lx.pos++
				lx.emit(TInvalid, start, lx.pos)
			} else {
				lx.pos = p
				lx.emit(TFormat, start, lx.pos)
			}
		case isIdentStart(c):
			lx.lexIdentBody()
			text := src[start:lx.pos]
			if keywords[text] {
				lx.emit(TKeyword, start, lx.pos)
			} else {
				lx.emit(TIdent, start, lx.pos)
			}
		case c == '(':
			parenDepth++
			lx.pos++
			lx.emit(TPunct, start, lx.pos)
		case c == ')':
			if inInterp >= 0 && parenDepth == 0 {
				lx.pos++
				lx.emit(TQQInterpEnd, start, lx.pos)
				return nil
			}
			parenDepth--
			lx.pos++
			lx.emit(TPunct, start, lx.pos)
		default:
			// multi-char punctuation
			for _, op := range []string{"?//", "!=", "==", "//=", "//", "|=", "+=", "-=", "*=", "/=", "%=", "<=", ">="} {
				if strings.HasPrefix(src[lx.pos:], op) {
					lx.pos += len(op)
					lx.emit(TPunct, start, lx.pos)
					goto next
				}
