// lexString lexes the inside of a string literal after the opening quote.
func (lx *Lexer) lexString() error {
	src := lx.src
	for lx.pos < len(src) {
		start := lx.pos
		if src[lx.pos] == '"' {
			lx.pos++
			lx.emit(TQQEnd, start, lx.pos)
			return nil
		}
		if src[lx.pos] == '\\' && lx.pos+1 < len(src) && src[lx.pos+1] == '(' {
			lx.pos += 2
			lx.emit(TQQInterpStart, start, lx.pos)
			if err := lx.lexUntil(0, 1); err != nil {
				return err
			}
			continue
		}
		// text run
		for lx.pos < len(src) {
			ch := src[lx.pos]
			if ch == '"' {
				break
			}
			if ch == '\\' {
				if lx.pos+1 < len(src) && src[lx.pos+1] == '(' {
					break
				}
				if lx.pos+1 < len(src) && src[lx.pos+1] == 'u' {
					lx.pos += 2
					n := 0
					for n < 4 && lx.pos < len(src) && isHexOrAlnum(src[lx.pos]) {
						lx.pos++
						n++
					}
					continue
				}
				lx.pos += 2
				if lx.pos > len(src) {
					lx.pos = len(src)
				}
				continue
			}
			lx.pos++
		}
		if lx.pos > start {
			lx.emit(TQQText, start, lx.pos)
		}
	}
	return nil
}

func isHexOrAlnum(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func (t Token) String() string {
	switch t.Kind {
	case TEOF:
		return "end of file"
	case TIdent:
		return "IDENT"
	case TField:
		return "FIELD"
	case TBinding:
		return "BINDING"
	case TLoc:
		return "$__loc__"
	case TLiteral:
		return "LITERAL"
	case TFormat:
		return "FORMAT"
	case TKeyword:
		return t.Text
	case TPunct:
		if len(t.Text) == 1 {
			return fmt.Sprintf("'%s'", t.Text)
		}
		switch t.Text {
		case "!=":
			return "NEQ"
		case "==":
			return "EQ"
		case "//":
			return "\"//\""
		case "//=":
			return "SETDEFINEDOR"
		case "|=":
			return "SETPIPE"
		case "+=":
			return "SETPLUS"
		case "-=":
			return "SETMINUS"
		case "*=":
			return "SETMULT"
		case "/=":
			return "SETDIV"
		case "%=":
			return "SETMOD"
		case "<=":
			return "LESSEQ"
		case ">=":
			return "GREATEREQ"
		case "..":
			return "REC"
		case "?//":
			return "\"?//\""
		}
		return t.Text
	case TQQStart:
		return "QQSTRING_START"
	case TQQText:
		return "QQSTRING_TEXT"
	case TQQInterpStart:
		return "QQSTRING_INTERP_START"
	case TQQInterpEnd:
		return "QQSTRING_INTERP_END"
	case TQQEnd:
		return "QQSTRING_END"
	case TInvalid:
		return "INVALID_CHARACTER"
	}
	return "?"
}
