{"command":"cd /workspace && cat > parser.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

type CompileError struct {
	Msg      string
	Pos, End int // byte offsets into the source; -1 if none
}

type Parser struct {
	src    string
	toks   []Token
	p      int
	errors []CompileError
	// for "unterminated if" diagnostics
	ifStack []int
	lastWS  Token // last whitespace/comment span (for EOF location)
	fname   string
}

type parseAbort struct{}

func (ps *Parser) peek() Token { return ps.toks[ps.p] }
func (ps *Parser) next() Token {
	t := ps.toks[ps.p]
	if ps.p < len(ps.toks)-1 {
		ps.p++
	}
	return t
}

func (ps *Parser) isPunct(s string) bool {
	t := ps.peek()
	return t.Kind == TPunct && t.Text == s
}
func (ps *Parser) isKeyword(s string) bool {
	t := ps.peek()
	return t.Kind == TKeyword && t.Text == s
}

func (ps *Parser) fail(tok Token, msg string) {
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: tok.Pos, End: tok.End})
	panic(parseAbort{})
}

func (ps *Parser) failAt(pos, end int, msg string) {
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: pos, End: end})
	panic(parseAbort{})
}

// syntaxError reports a bison-style syntax error at the current token.
func (ps *Parser) syntaxError(expecting string) {
	t := ps.peek()
	msg := "syntax error, unexpected " + t.String()
	if expecting != "" {
		msg += ", expecting " + expecting
	}
	pos, end := t.Pos, t.End
	if t.Kind == TEOF {
		// location of last lexer match
		if ps.p > 0 {
			prev := ps.toks[ps.p-1]
			pos, end = prev.Pos, prev.End
			if ps.lastWS.End > prev.End {
				pos, end = ps.lastWS.Pos, ps.lastWS.End
			}
		} else {
			pos, end = 0, 0
		}
	}
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: pos, End: end})
	// unterminated if diagnostics
	if len(ps.ifStack) > 0 {
		ifPos := ps.ifStack[len(ps.ifStack)-1]
		ps.errors = append(ps.errors, CompileError{Msg: "Possibly unterminated 'if' statement", Pos: ifPos, End: end})
	}
	panic(parseAbort{})
}

func (ps *Parser) expectPunct(s string, expecting string) Token {
	if !ps.isPunct(s) {
		ps.syntaxError(expecting)
	}
	return ps.next()
}

func (ps *Parser) expectKeyword(s string, expecting string) Token {
	if !ps.isKeyword(s) {
		ps.syntaxError(expecting)
	}
	return ps.next()
}

// ParseProgram parses a full jq program (with optional module directive and imports).
func ParseProgram(src string, fname string) (prog *Program, errs []CompileError) {
	toks, lastWS, err := lexAllWithWS(src)
	if err != nil {
		return nil, []CompileError{{Msg: err.Error(), Pos: 0, End: 0}}
	}
	ps := &Parser{src: src, toks: toks, lastWS: lastWS, fname: fname}
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(parseAbort); ok {
				prog = nil
				errs = ps.errors
				return
			}
			panic(r)
		}
	}()
	prog = &Program{}
	// module directive
	if ps.isKeyword("module") {
		ps.next()
		meta := ps.parsePrimaryAndPostfix()
		obj, ok := constObjectOf(meta)
		if !ok {
			ps.failAt(ps.peek().Pos, ps.peek().End, "Module metadata must be constant")
		}
		prog.ModuleMeta = obj
		ps.expectPunct(";", "';'")
	}
	// imports
	for ps.isKeyword("import") || ps.isKeyword("include") {
		prog.Imports = append(prog.Imports, ps.parseImport())
	}
	if ps.peek().Kind == TEOF {
		// empty program: identity? jq treats empty program as "."? Actually it's an error for
		// main program; but a library can be empty.
		prog.Body = nil
		return prog, ps.errors
	}
	// A library consists only of definitions; a program may have defs followed by body.
	// Parse as a pipe; if the result is a chain of FuncDefNodes with a nil tail, it's a library.
	body := ps.parsePipeAllowingDefsOnly()
	if ps.peek().Kind != TEOF {
		ps.syntaxError("end of file")
	}
	prog.Body = body
	return prog, ps.errors
}

// lexAllWithWS lexes and also returns the last whitespace/comment span.
func lexAllWithWS(src string) ([]Token, Token, error) {
	toks, err := lexAll(src)
	if err != nil {
		return nil, Token{}, err
	}
	// compute trailing whitespace span: from end of last real token to end of source
	var ws Token
	if len(toks) >= 2 {
		last := toks[len(toks)-2]
		if last.End < len(src) {
			ws = Token{Pos: last.End, End: len(src)}
			// if there is a trailing comment/whitespace, jq's location is the start of the
			// final lexer match; approximate with the start of trailing whitespace.
			// Find last whitespace run start.
			i := len(src)
			for i > last.End && (src[i-1] == ' ' || src[i-1] == '\t' || src[i-1] == '\n' || src[i-1] == '\r') {
				i--
			}
			if i < len(src) {
				ws.Pos = i
			}
			if i == len(src) {
				ws = Token{}
			}
		}
	} else if len(src) > 0 {
		ws = Token{Pos: 0, End: len(src)}
	}
	return toks, ws, nil
}

func (ps *Parser) parseImport() *ImportDecl {
	start := ps.next() // import / include
	decl := &ImportDecl{Include: start.Text == "include", Pos: start.Pos}
	if ps.peek().Kind != TQQStart {
		ps.syntaxError("")
	}
	strNode := ps.parseString("")
	path, ok := constStringOf(strNode)
	if !ok {
		ps.failAt(start.Pos, ps.peek().End, "Import path must be constant")
	}
	decl.Path = path
	if !decl.Include {
		ps.expectKeyword("as", "")
		t := ps.peek()
		if t.Kind == TIdent {
			decl.Alias = t.Text
			ps.next()
		} else if t.Kind == TBinding {
			decl.Alias = t.Text[1:]
			decl.IsData = true
			ps.next()
		} else {
			ps.syntaxError("IDENT or BINDING")
		}
	}
	if !ps.isPunct(";") {
		meta := ps.parsePrimaryAndPostfix()
		obj, ok := constObjectOf(meta)
		if !ok {
			ps.failAt(start.Pos, ps.peek().End, "Module metadata must be constant")
		}
		decl.Meta = obj
	}
	decl.End = ps.peek().End
	ps.expectPunct(";", "';'")
	return decl
}

func constStringOf(n Node) (string, bool) {
	if l, ok := n.(*LiteralNode); ok {
		if s, ok := l.Value.(string); ok {
			return s, true
		}
	}
	if s, ok := n.(*StringNode); ok && s.Format == "" {
		var sb strings.Builder
		for _, p := range s.Parts {
			if str, ok := p.(string); ok {
				sb.WriteString(str)
			} else {
				return "", false
			}
		}
		return sb.String(), true
	}
	return "", false
}

func constValueOf(n Node) (Value, bool) {
	switch x := n.(type) {
	case *LiteralNode:
		return x.Value, true
	case *StringNode:
		s, ok := constStringOf(x)
		if ok {
			return s, true
		}
		return nil, false
	case *NegNode:
		v, ok := constValueOf(x.Body)
		if !ok {
			return nil, false
		}
		switch num := v.(type) {
		case float64:
			return -num, true
		case *LitNum:
			return num.Negate(), true
		}
		return nil, false
	case *ArrayNode:
		if x.Body == nil {
			return []Value{}, true
		}
		var arr []Value
		if !collectConstComma(x.Body, &arr) {
			return nil, false
		}
		return arr, true
	case *ObjectNode:
		obj := NewObject()
		for _, e := range x.Entries {
			if e.Value == nil || e.KeyIsVar {
				return nil, false
			}
			k, ok := constStringOf(e.Key)
			if !ok {
				return nil, false
			}
			v, ok := constValueOf(e.Value)
			if !ok {
				return nil, false
			}
			obj.SetInPlace(k, v)
		}
		return obj, true
	case *CallNode:
		if len(x.Args) == 0 {
			switch x.Name {
			case "null":
				return nil, true
			case "true":
				return true, true
			case "false":
				return false, true
			}
		}
	}
	return nil, false
}

func collectConstComma(n Node, out *[]Value) bool {
	if c, ok := n.(*CommaNode); ok {
		return collectConstComma(c.L, out) && collectConstComma(c.R, out)
	}
	v, ok := constValueOf(n)
	if !ok {
		return false
	}
	*out = append(*out, v)
	return true
}

func constObjectOf(n Node) (*Object, bool) {
	v, ok := constValueOf(n)
	if !ok {
		return nil, false
	}
	o, ok := v.(*Object)
	return o, ok
}

// parsePipeAllowingDefsOnly parses the top-level: a sequence of defs possibly followed by a body.
func (ps *Parser) parsePipeAllowingDefsOnly() Node {
	if ps.isKeyword("def") {
		def := ps.parseFuncDef()
		if ps.peek().Kind == TEOF {
			return &FuncDefNode{Def: def, Rest: nil}
		}
		rest := ps.parsePipeAllowingDefsOnly()
		return &FuncDefNode{Def: def, Rest: rest}
	}
	return ps.parsePipe()
}

// parsePipe: Pipe := CommaExpr ('|' Pipe)?
func (ps *Parser) parsePipe() Node {
	left := ps.parseComma()
	if ps.isPunct("|") {
		ps.next()
		right := ps.parsePipe()
		return &PipeNode{L: left, R: right}
	}
	return left
}

func (ps *Parser) parseComma() Node {
	left := ps.parseCommaOperand()
	for ps.isPunct(",") {
		ps.next()
		right := ps.parseCommaOperand()
		left = &CommaNode{L: left, R: right}
	}
	return left
}

// parseCommaOperand: def ... ; Pipe | label $x | Pipe | Alt (as Patterns | Pipe)?
func (ps *Parser) parseCommaOperand() Node {
	if ps.isKeyword("def") {
		def := ps.parseFuncDef()
		rest := ps.parsePipe()
		return &FuncDefNode{Def: def, Rest: rest}
	}
	if ps.isKeyword("label") {
		ps.next()
		t := ps.peek()
		if t.Kind != TBinding {
			ps.syntaxError("BINDING")
		}
		ps.next()
		ps.expectPunct("|", "'|'")
		body := ps.parsePipe()
		return &LabelNode{Name: t.Text[1:], Body: body}
	}
	e := ps.parseAlt()
	if ps.isKeyword("as") {
		ps.next()
		pats := ps.parsePatterns()
		ps.expectPunct("|", "'|'")
		body := ps.parsePipe()
		return &BindNode{Source: e, Patterns: pats, Body: body}
	}
	return e
}

// parseObjVal: ExpD := Alt ('|' Alt)*
func (ps *Parser) parseObjVal() Node {
	left := ps.parseAlt()
	for ps.isPunct("|") {
		ps.next()
		right := ps.parseAlt()
		left = &PipeNode{L: left, R: right}
	}
	return left
}

// parseAlt: right-assoc "//"
func (ps *Parser) parseAlt() Node {
	left := ps.parseAssign()
	if ps.isPunct("//") {
		ps.next()
		right := ps.parseAlt()
		return &AltNode{L: left, R: right}
	}
	return left
}

var assignOps = map[string]bool{"=": true, "|=": true, "+=": true, "-=": true, "*=": true, "/=": true, "%=": true, "//=": true}

func (ps *Parser) parseAssign() Node {
	left := ps.parseOr()
	t := ps.peek()
	if t.Kind == TPunct && assignOps[t.Text] {
		ps.next()
		right := ps.parseOr()
		n := &AssignNode{Op: t.Text, L: left, R: right}
		t2 := ps.peek()
		if t2.Kind == TPunct && assignOps[t2.Text] {
			ps.syntaxError("")
		}
		return n
	}
	return left
}

func (ps *Parser) parseOr() Node {
	left := ps.parseAnd()
	for ps.isKeyword("or") {
		ps.next()
		right := ps.parseAnd()
		left = &OrNode{L: left, R: right}
	}
	return left
}

func (ps *Parser) parseAnd() Node {
	left := ps.parseCompare()
	for ps.isKeyword("and") {
		ps.next()
		right := ps.parseCompare()
		left = &AndNode{L: left, R: right}
	}
	return left
}

var compareOps = map[string]bool{"==": true, "!=": true, "<": true, ">": true, "<=": true, ">=": true}

func (ps *Parser) parseCompare() Node {
	left := ps.parseAdditive()
	t := ps.peek()
	if t.Kind == TPunct && compareOps[t.Text] {
		ps.next()
		right := ps.parseAdditive()
		n := &BinopNode{Op: t.Text, L: left, R: right}
		t2 := ps.peek()
		if t2.Kind == TPunct && compareOps[t2.Text] {
			ps.syntaxError("")
		}
		return n
	}
	return left
}

func (ps *Parser) parseAdditive() Node {
	left := ps.parseMultiplicative()
	for {
		t := ps.peek()
		if t.Kind == TPunct && (t.Text == "+" || t.Text == "-") {
			ps.next()
			right := ps.parseMultiplicative()
			left = &BinopNode{Op: t.Text, L: left, R: right}
		} else {
			return left
		}
	}
}

func (ps *Parser) parseMultiplicative() Node {
	left := ps.parseUnary()
	for {
		t := ps.peek()
		if t.Kind == TPunct && (t.Text == "*" || t.Text == "/" || t.Text == "%") {
			ps.next()
			right := ps.parseUnary()
			left = &BinopNode{Op: t.Text, L: left, R: right}
		} else {
			return left
		}
	}
}

func (ps *Parser) parseUnary() Node {
	if ps.isPunct("-") {
		ps.next()
		body := ps.parseUnary()
		return &NegNode{Body: body}
	}
	return ps.parsePrimaryAndPostfix()
}

func (ps *Parser) parsePrimaryAndPostfix() Node {
	term := ps.parsePrimary()
	return ps.parsePostfix(term)
}

func (ps *Parser) parsePostfix(term Node) Node {
	for {
		t := ps.peek()
		switch {
		case t.Kind == TField:
			ps.next()
			term = &IndexNode{Target: term, Key: &LiteralNode{Value: t.Text[1:], Pos: t.Pos, End: t.End}, Pos: t.Pos}
			term = ps.maybeOpt(term)
		case t.Kind == TPunct && t.Text == ".":
			// ."str" or .[...]
			nt := ps.toks[ps.p+1]
			if nt.Kind == TQQStart {
				ps.next()
				s := ps.parseString("")
				term = &IndexNode{Target: term, Key: s, Pos: t.Pos}
				term = ps.maybeOpt(term)
			} else if nt.Kind == TPunct && nt.Text == "[" {
				ps.next()
				term = ps.parseBracketSuffix(term)
			} else if nt.Kind == TFormat {
				ps.next()
				s := ps.parseFormatString()
				term = &IndexNode{Target: term, Key: s, Pos: t.Pos}
				term = ps.maybeOpt(term)
			} else {
				ps.next()
				ps.syntaxError("FORMAT or QQSTRING_START or '['")
			}
		case t.Kind == TPunct && t.Text == "[":
			term = ps.parseBracketSuffix(term)
		case t.Kind == TPunct && t.Text == "?":
			ps.next()
			term = &TryNode{Body: term}
		default:
			return term
		}
	}
}

func (ps *Parser) maybeOpt(term Node) Node {
	if ps.isPunct("?") {
		ps.next()
		switch x := term.(type) {
		case *IndexNode:
			x.Opt = true
		case *SliceNode:
			x.Opt = true
		case *EachNode:
			x.Opt = true
		default:
			return &TryNode{Body: term}
		}
	}
	return term
}

// parseBracketSuffix parses [ ... ] after a term: .[], .[e], .[e:e], .[:e], .[e:]
func (ps *Parser) parseBracketSuffix(term Node) Node {
	open := ps.expectPunct("[", "")
	if ps.isPunct("]") {
		ps.next()
		return ps.maybeOpt(&EachNode{Target: term})
	}
	if ps.isPunct(":") {
		ps.next()
		to := ps.parsePipe()
		ps.expectPunct("]", "']'")
		return ps.maybeOpt(&SliceNode{Target: term, To: to})
	}
	e := ps.parsePipe()
	if ps.isPunct(":") {
		ps.next()
		if ps.isPunct("]") {
			ps.next()
			return ps.maybeOpt(&SliceNode{Target: term, From: e})
		}
		to := ps.parsePipe()
		ps.expectPunct("]", "']'")
		return ps.maybeOpt(&SliceNode{Target: term, From: e, To: to})
	}
	if !ps.isPunct("]") {
		ps.syntaxError("'|' or ',' or ':' or ']'")
	}
	ps.next()
	return ps.maybeOpt(&IndexNode{Target: term, Key: e, Pos: open.Pos})
}

func (ps *Parser) parsePrimary() Node {
	t := ps.peek()
	switch t.Kind {
	case TPunct:
		switch t.Text {
		case ".":
			ps.next()
			nt := ps.peek()
			if nt.Kind == TQQStart {
				s := ps.parseString("")
				return ps.maybeOpt(&IndexNode{Target: nil, Key: s, Pos: t.Pos})
			}
			if nt.Kind == TFormat {
				s := ps.parseFormatString()
				return ps.maybeOpt(&IndexNode{Target: nil, Key: s, Pos: t.Pos})
			}
			if nt.Kind == TPunct && nt.Text == "[" {
				return ps.parseBracketSuffix(nil)
			}
			if nt.Kind == TIdent {
				// ". a" error
				ps.errors = append(ps.errors, CompileError{Msg: "syntax error, unexpected IDENT, expecting end of file", Pos: nt.Pos, End: nt.End})
				ps.errors = append(ps.errors, CompileError{Msg: "try .[\"field\"] instead of .field for unusually named fields", Pos: t.Pos, End: nt.End})
				panic(parseAbort{})
			}
			return IdentityNode{}
		case "..":
			ps.next()
			return RecurseNode{}
		case "(":
			ps.next()
			e := ps.parsePipe()
			ps.expectPunct(")", "'|' or ',' or ')'")
			return e
		case "[":
			ps.next()
			if ps.isPunct("]") {
				ps.next()
				return &ArrayNode{}
			}
			e := ps.parsePipe()
			ps.expectPunct("]", "'|' or ',' or ']'")
			return &ArrayNode{Body: e}
		case "{":
			return ps.parseObject()
		case "$":
			ps.next()
			ps.syntaxError("'$'")
		}
	case TField:
		ps.next()
		return ps.maybeOpt(&IndexNode{Target: nil, Key: &LiteralNode{Value: t.Text[1:], Pos: t.Pos, End: t.End}, Pos: t.Pos})
	case TLiteral:
		ps.next()
		v, ok := parseDecimalLiteral(t.Text)
		if !ok {
			v = 0.0
		}
		return &LiteralNode{Value: v, Pos: t.Pos, End: t.End}
	case TQQStart:
		return ps.parseString("")
	case TFormat:
		ps.next()
		if ps.peek().Kind == TQQStart {
			return ps.parseString(t.Text)
		}
		return &FormatNode{Name: t.Text, Pos: t.Pos, End: t.End}
	case TLoc:
		ps.next()
		return &LocNode{File: ps.fname, Line: lineOf(ps.src, t.Pos)}
	case TBinding:
		ps.next()
		return &VarNode{Name: t.Text[1:], Pos: t.Pos, End: t.End}
	case TIdent:
		ps.next()
		call := &CallNode{Name: t.Text, Pos: t.Pos, End: t.End}
		if ps.isPunct("(") {
			ps.next()
			for {
				arg := ps.parsePipe()
				call.Args = append(call.Args, arg)
				if ps.isPunct(";") {
					ps.next()
					continue
				}
				ps.expectPunct(")", "'|' or ',' or ';' or ')'")
				break
			}
		}
		return call
	case TKeyword:
		switch t.Text {
		case "if":
			return ps.parseIf()
		case "try":
			ps.next()
			body := ps.parsePostTry()
			var catch Node
			if ps.isKeyword("catch") {
				ps.next()
				catch = ps.parsePostTry()
			}
			return &TryNode{Body: body, Catch: catch, hasCatch: catch != nil}
		case "reduce":
			ps.next()
			src := ps.parseReduceSource()
			ps.expectKeyword("as", "")
			pats := ps.parsePatterns()
			ps.expectPunct("(", "'('")
			init := ps.parsePipe()
			ps.expectPunct(";", "';'")
			update := ps.parsePipe()
			ps.expectPunct(")", "')'")
			return &ReduceNode{Source: src, Patterns: pats, Init: init, Update: update}
		case "foreach":
			ps.next()
			src := ps.parseReduceSource()
			ps.expectKeyword("as", "")
			pats := ps.parsePatterns()
			ps.expectPunct("(", "'('")
			init := ps.parsePipe()
			ps.expectPunct(";", "';'")
			update := ps.parsePipe()
			var extract Node
			if ps.isPunct(";") {
				ps.next()
				extract = ps.parsePipe()
			}
			ps.expectPunct(")", "')'")
			return &ForeachNode{Source: src, Patterns: pats, Init: init, Update: update, Extract: extract}
		case "def", "label":
			// not allowed here
			ps.syntaxError("")
		case "__loc__":
			ps.syntaxError("")
		}
		ps.syntaxError("")
	case TEOF:
		ps.syntaxError("")
	}
	ps.syntaxError("")
	return nil
}

// parseReduceSource parses the source of reduce/foreach (a postfix term, allowing unary minus and binary ops without comma).
func (ps *Parser) parseReduceSource() Node {
	return ps.parseAlt()
}

// parsePostTry parses the body of try/catch: a unary-level expression.
func (ps *Parser) parsePostTry() Node {
	return ps.parseUnary()
}

func (ps *Parser) parseIf() Node {
	ifTok := ps.next() // if
	ps.ifStack = append(ps.ifStack, ifTok.Pos)
	cond := ps.parsePipe()
	ps.expectKeyword("then", "then")
	then := ps.parsePipe()
	var els Node
	switch {
	case ps.isKeyword("elif"):
		els = ps.parseElif()
	case ps.isKeyword("else"):
		ps.next()
		els = ps.parsePipe()
		ps.expectKeyword("end", "end or '|' or ','")
	case ps.isKeyword("end"):
		ps.next()
	default:
		ps.syntaxError("")
	}
	ps.ifStack = ps.ifStack[:len(ps.ifStack)-1]
	return &IfNode{Cond: cond, Then: then, Else: els}
}

func (ps *Parser) parseElif() Node {
	ps.next() // elif
	cond := ps.parsePipe()
	ps.expectKeyword("then", "then")
	then := ps.parsePipe()
	var els Node
	switch {
	case ps.isKeyword("elif"):
		els = ps.parseElif()
	case ps.isKeyword("else"):
		ps.next()
		els = ps.parsePipe()
		ps.expectKeyword("end", "end or '|' or ','")
	case ps.isKeyword("end"):
		ps.next()
	default:
		ps.syntaxError("")
	}
	return &IfNode{Cond: cond, Then: then, Else: els}
}

func (ps *Parser) parseFuncDef() *FuncDef {
	defTok := ps.next() // def
	t := ps.peek()
	if t.Kind != TIdent {
		ps.syntaxError("IDENT")
	}
	ps.next()
	def := &FuncDef{Name: t.Text, Pos: defTok.Pos}
	if ps.isPunct("(") {
		ps.next()
		for {
			pt := ps.peek()
			if pt.Kind == TIdent {
				def.Params = append(def.Params, pt.Text)
			} else if pt.Kind == TBinding {
				def.Params = append(def.Params, pt.Text)
			} else {
				ps.syntaxError("IDENT or BINDING")
			}
			ps.next()
			if ps.isPunct(";") {
				ps.next()
				continue
			}
			ps.expectPunct(")", "';' or ')'")
			break
		}
	}
	ps.expectPunct(":", "':'")
	def.Body = ps.parsePipe()
	def.End = ps.peek().End
	ps.expectPunct(";", "'|' or ',' or ';'")
	return def
}

func (ps *Parser) parsePatterns() []Pattern {
	var pats []Pattern
	pats = append(pats, ps.parsePattern())
	for ps.isPunct("?//") {
		ps.next()
		pats = append(pats, ps.parsePattern())
	}
	return pats
}

func (ps *Parser) parsePattern() Pattern {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		return &VarPattern{Name: t.Text[1:]}
	case t.Kind == TPunct && t.Text == "[":
		ps.next()
		ap := &ArrayPattern{}
		for {
			ap.Elems = append(ap.Elems, ps.parsePattern())
			if ps.isPunct(",") {
				ps.next()
				continue
			}
			ps.expectPunct("]", "',' or ']'")
			break
		}
		return ap
	case t.Kind == TPunct && t.Text == "{":
		ps.next()
		op := &ObjectPattern{}
		for {
			op.Entries = append(op.Entries, ps.parseObjPatEntry())
			if ps.isPunct(",") {
				ps.next()
				continue
			}
			ps.expectPunct("}", "',' or '}'")
			break
		}
		return op
	}
	ps.syntaxError("BINDING or '[' or '{'")
	return nil
}

func (ps *Parser) parseObjPatEntry() ObjPatEntry {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		e := ObjPatEntry{KeyVar: t.Text[1:]}
		if ps.isPunct(":") {
			ps.next()
			e.Val = ps.parsePattern()
		}
		return e
	case t.Kind == TIdent || t.Kind == TKeyword:
		ps.next()
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: &LiteralNode{Value: t.Text, Pos: t.Pos, End: t.End}, Val: ps.parsePattern()}
	case t.Kind == TQQStart:
		s := ps.parseString("")
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: s, Val: ps.parsePattern()}
	case t.Kind == TFormat:
		ps.next()
		s := ps.parseString(t.Text)
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: s, Val: ps.parsePattern()}
	case t.Kind == TPunct && t.Text == "(":
		ps.next()
		k := ps.parsePipe()
		ps.expectPunct(")", "')'")
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: k, Val: ps.parsePattern()}
	}
	ps.syntaxError("")
	return ObjPatEntry{}
}

func (ps *Parser) parseObject() Node {
	ps.expectPunct("{", "")
	obj := &ObjectNode{}
	if ps.isPunct("}") {
		ps.next()
		return obj
	}
	for {
		obj.Entries = append(obj.Entries, ps.parseObjEntry())
		if ps.isPunct(",") {
			ps.next()
			if ps.isPunct("}") {
				ps.next()
				break
			}
			continue
		}
		ps.expectPunct("}", "'}'")
		break
	}
	return obj
}

func (ps *Parser) parseObjEntry() ObjectEntry {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		e := ObjectEntry{KeyVar: t.Text[1:], KeyIsVar: true, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TLoc:
		ps.next()
		e := ObjectEntry{KeyLoc: true, LocLine: lineOf(ps.src, t.Pos), KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TIdent || t.Kind == TKeyword:
		ps.next()
		e := ObjectEntry{Key: &LiteralNode{Value: t.Text, Pos: t.Pos, End: t.End}, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TQQStart:
		s := ps.parseString("")
		e := ObjectEntry{Key: s, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TFormat:
		ps.next()
		s := ps.parseString(t.Text)
		e := ObjectEntry{Key: s, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TLiteral:
		ps.next()
		v, _ := parseDecimalLiteral(t.Text)
		ps.failAt(t.Pos, t.End, fmt.Sprintf("Cannot use %s (%s) as object key", typeName(v), dumpTrunc(v, 11)))
	case t.Kind == TPunct && t.Text == "(":
		ps.next()
		k := ps.parsePipe()
		ps.expectPunct(")", "')'")
		ps.expectPunct(":", "':'")
		if cv, ok := constValueOf(k); ok {
			if _, isStr := cv.(string); !isStr {
				start, end := nodeSpan(k)
				ps.failAt(start, end, fmt.Sprintf("Cannot use %s (%s) as object key", typeName(cv), dumpTrunc(cv, 11)))
			}
		}
		return ObjectEntry{Key: k, Value: ps.parseObjVal(), KeyPos: t.Pos}
	}
	ps.syntaxError("")
	return ObjectEntry{}
}

func nodeSpan(n Node) (int, int) {
	switch x := n.(type) {
	case *LiteralNode:
		return x.Pos, x.End
	case *CallNode:
		return x.Pos, x.End
	}
	return 0, 0
}

// parseString parses a string literal starting at QQSTRING_START. format is e.g. "@base64" or "".
func (ps *Parser) parseString(format string) Node {
	start := ps.peek()
	if start.Kind != TQQStart {
		ps.syntaxError("QQSTRING_START")
	}
	ps.next()
	node := &StringNode{Format: format}
	for {
		t := ps.peek()
		switch t.Kind {
		case TQQText:
			ps.next()
			// unescape via JSON parser semantics
			s, err := unescapeStringLiteral(t.Text)
			if err != nil {
				ps.failAt(t.Pos, t.End, err.Error())
			}
			node.Parts = append(node.Parts, s)
		case TQQInterpStart:
			ps.next()
			e := ps.parsePipe()
			if ps.peek().Kind != TQQInterpEnd {
				ps.syntaxError("QQSTRING_INTERP_END or '|' or ','")
			}
			ps.next()
			node.Parts = append(node.Parts, e)
		case TQQEnd:
			ps.next()
			// constant string?
			if len(node.Parts) == 0 {
				return &LiteralNode{Value: "", Pos: start.Pos, End: t.End}
			}
			if len(node.Parts) == 1 {
				if s, ok := node.Parts[0].(string); ok && format == "" {
					return &LiteralNode{Value: s, Pos: start.Pos, End: t.End}
				}
			}
			return node
		default:
			ps.syntaxError("QQSTRING_TEXT or QQSTRING_INTERP_START or QQSTRING_END")
		}
	}
}

func (ps *Parser) parseFormatString() Node {
	t := ps.next() // format token
	return ps.parseString(t.Text)
}

// unescapeStringLiteral unescapes the raw text of a jq string literal segment using the JSON parser.
func unescapeStringLiteral(raw string) (string, error) {
	v, err := parseJSONOne("\"" + raw + "\"")
	if err != nil {
		return "", err
	}
	s, _ := v.(string)
	return s, nil
}

func lineOf(src string, pos int) int {
	line := 1
	for i := 0; i < pos && i < len(src); i++ {
		if src[i] == '\n' {
			line++
		}
	}
	return line
}

// formatCompileError renders the error message with location like jq does.
func formatCompileError(src string, fname string, e CompileError) string {
	if e.Pos < 0 {
		return fmt.Sprintf("jq: error: %s", e.Msg)
	}
	// find line
	lineStart := 0
	lineNo := 1
	for i := 0; i < e.Pos && i < len(src); i++ {
		if src[i] == '\n' {
			lineNo++
			lineStart = i + 1
		}
	}
	lineEnd := strings.IndexByte(src[lineStart:], '\n')
	if lineEnd < 0 {
		lineEnd = len(src)
	} else {
		lineEnd += lineStart
	}
	col := e.Pos - lineStart
	end := e.End
	if end > lineEnd {
		end = lineEnd
	}
	n := end - e.Pos
	if n < 1 {
		n = 1
	}
	return fmt.Sprintf("jq: error: %s at %s, line %d, column %d:\n    %s\n    %s%s", e.Msg, fname, lineNo, col+1, src[lineStart:lineEnd], strings.Repeat(" ", col), strings.Repeat("^", n))
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > parser.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

type CompileError struct {
	Msg      string
	Pos, End int // byte offsets into the source; -1 if none
}

type Parser struct {
	src    string
	toks   []Token
	p      int
	errors []CompileError
	// for "unterminated if" diagnostics
	ifStack []int
	lastWS  Token // last whitespace/comment span (for EOF location)
	fname   string
}

type parseAbort struct{}

func (ps *Parser) peek() Token { return ps.toks[ps.p] }
func (ps *Parser) next() Token {
	t := ps.toks[ps.p]
	if ps.p < len(ps.toks)-1 {
		ps.p++
	}
	return t
}

func (ps *Parser) isPunct(s string) bool {
	t := ps.peek()
	return t.Kind == TPunct && t.Text == s
}
func (ps *Parser) isKeyword(s string) bool {
	t := ps.peek()
	return t.Kind == TKeyword && t.Text == s
}

func (ps *Parser) fail(tok Token, msg string) {
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: tok.Pos, End: tok.End})
	panic(parseAbort{})
}

func (ps *Parser) failAt(pos, end int, msg string) {
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: pos, End: end})
	panic(parseAbort{})
}

// syntaxError reports a bison-style syntax error at the current token.
func (ps *Parser) syntaxError(expecting string) {
	t := ps.peek()
	msg := "syntax error, unexpected " + t.String()
	if expecting != "" {
		msg += ", expecting " + expecting
	}
	pos, end := t.Pos, t.End
	if t.Kind == TEOF {
		// location of last lexer match
		if ps.p > 0 {
			prev := ps.toks[ps.p-1]
			pos, end = prev.Pos, prev.End
			if ps.lastWS.End > prev.End {
				pos, end = ps.lastWS.Pos, ps.lastWS.End
			}
		} else {
			pos, end = 0, 0
		}
	}
	ps.errors = append(ps.errors, CompileError{Msg: msg, Pos: pos, End: end})
	// unterminated if diagnostics
	if len(ps.ifStack) > 0 {
		ifPos := ps.ifStack[len(ps.ifStack)-1]
		ps.errors = append(ps.errors, CompileError{Msg: "Possibly unterminated 'if' statement", Pos: ifPos, End: end})
	}
	panic(parseAbort{})
}

func (ps *Parser) expectPunct(s string, expecting string) Token {
	if !ps.isPunct(s) {
		ps.syntaxError(expecting)
	}
	return ps.next()
}

func (ps *Parser) expectKeyword(s string, expecting string) Token {
	if !ps.isKeyword(s) {
		ps.syntaxError(expecting)
	}
	return ps.next()
}

// ParseProgram parses a full jq program (with optional module directive and imports).
func ParseProgram(src string, fname string) (prog *Program, errs []CompileError) {
	toks, lastWS, err := lexAllWithWS(src)
	if err != nil {
		return nil, []CompileError{{Msg: err.Error(), Pos: 0, End: 0}}
	}
	ps := &Parser{src: src, toks: toks, lastWS: lastWS, fname: fname}
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(parseAbort); ok {
				prog = nil
				errs = ps.errors
				return
			}
			panic(r)
		}
	}()
	prog = &Program{}
	// module directive
	if ps.isKeyword("module") {
		ps.next()
		meta := ps.parsePrimaryAndPostfix()
		obj, ok := constObjectOf(meta)
		if !ok {
			ps.failAt(ps.peek().Pos, ps.peek().End, "Module metadata must be constant")
		}
		prog.ModuleMeta = obj
		ps.expectPunct(";", "';'")
	}
	// imports
	for ps.isKeyword("import") || ps.isKeyword("include") {
		prog.Imports = append(prog.Imports, ps.parseImport())
	}
	if ps.peek().Kind == TEOF {
		// empty program: identity? jq treats empty program as "."? Actually it's an error for
		// main program; but a library can be empty.
		prog.Body = nil
		return prog, ps.errors
	}
	// A library consists only of definitions; a program may have defs followed by body.
	// Parse as a pipe; if the result is a chain of FuncDefNodes with a nil tail, it's a library.
	body := ps.parsePipeAllowingDefsOnly()
	if ps.peek().Kind != TEOF {
		ps.syntaxError("end of file")
	}
	prog.Body = body
	return prog, ps.errors
}

// lexAllWithWS lexes and also returns the last whitespace/comment span.
func lexAllWithWS(src string) ([]Token, Token, error) {
	toks, err := lexAll(src)
	if err != nil {
		return nil, Token{}, err
	}
	// compute trailing whitespace span: from end of last real token to end of source
	var ws Token
	if len(toks) >= 2 {
		last := toks[len(toks)-2]
		if last.End < len(src) {
			ws = Token{Pos: last.End, End: len(src)}
			// if there is a trailing comment/whitespace, jq's location is the start of the
			// final lexer match; approximate with the start of trailing whitespace.
			// Find last whitespace run start.
			i := len(src)
			for i > last.End && (src[i-1] == ' ' || src[i-1] == '\t' || src[i-1] == '\n' || src[i-1] == '\r') {
				i--
			}
			if i < len(src) {
				ws.Pos = i
			}
			if i == len(src) {
				ws = Token{}
			}
		}
	} else if len(src) > 0 {
		ws = Token{Pos: 0, End: len(src)}
	}
	return toks, ws, nil
}

func (ps *Parser) parseImport() *ImportDecl {
	start := ps.next() // import / include
	decl := &ImportDecl{Include: start.Text == "include", Pos: start.Pos}
	if ps.peek().Kind != TQQStart {
		ps.syntaxError("")
	}
	strNode := ps.parseString("")
	path, ok := constStringOf(strNode)
	if !ok {
		ps.failAt(start.Pos, ps.peek().End, "Import path must be constant")
	}
	decl.Path = path
	if !decl.Include {
		ps.expectKeyword("as", "")
		t := ps.peek()
		if t.Kind == TIdent {
			decl.Alias = t.Text
			ps.next()
		} else if t.Kind == TBinding {
			decl.Alias = t.Text[1:]
			decl.IsData = true
			ps.next()
		} else {
			ps.syntaxError("IDENT or BINDING")
		}
	}
	if !ps.isPunct(";") {
		meta := ps.parsePrimaryAndPostfix()
		obj, ok := constObjectOf(meta)
		if !ok {
			ps.failAt(start.Pos, ps.peek().End, "Module metadata must be constant")
		}
		decl.Meta = obj
	}
	decl.End = ps.peek().End
	ps.expectPunct(";", "';'")
	return decl
}

func constStringOf(n Node) (string, bool) {
	if l, ok := n.(*LiteralNode); ok {
		if s, ok := l.Value.(string); ok {
			return s, true
		}
	}
	if s, ok := n.(*StringNode); ok && s.Format == "" {
		var sb strings.Builder
		for _, p := range s.Parts {
			if str, ok := p.(string); ok {
				sb.WriteString(str)
			} else {
				return "", false
			}
		}
		return sb.String(), true
	}
	return "", false
}

func constValueOf(n Node) (Value, bool) {
	switch x := n.(type) {
	case *LiteralNode:
		return x.Value, true
	case *StringNode:
		s, ok := constStringOf(x)
		if ok {
			return s, true
		}
		return nil, false
	case *NegNode:
		v, ok := constValueOf(x.Body)
		if !ok {
			return nil, false
		}
		switch num := v.(type) {
		case float64:
			return -num, true
		case *LitNum:
			return num.Negate(), true
		}
		return nil, false
	case *ArrayNode:
		if x.Body == nil {
			return []Value{}, true
		}
		var arr []Value
		if !collectConstComma(x.Body, &arr) {
			return nil, false
		}
		return arr, true
	case *ObjectNode:
		obj := NewObject()
		for _, e := range x.Entries {
			if e.Value == nil || e.KeyIsVar {
				return nil, false
			}
			k, ok := constStringOf(e.Key)
			if !ok {
				return nil, false
			}
			v, ok := constValueOf(e.Value)
			if !ok {
				return nil, false
			}
			obj.SetInPlace(k, v)
		}
		return obj, true
	case *CallNode:
		if len(x.Args) == 0 {
			switch x.Name {
			case "null":
				return nil, true
			case "true":
				return true, true
			case "false":
				return false, true
			}
		}
	}
	return nil, false
}

func collectConstComma(n Node, out *[]Value) bool {
	if c, ok := n.(*CommaNode); ok {
		return collectConstComma(c.L, out) && collectConstComma(c.R, out)
	}
	v, ok := constValueOf(n)
	if !ok {
		return false
	}
	*out = append(*out, v)
	return true
}

func constObjectOf(n Node) (*Object, bool) {
	v, ok := constValueOf(n)
	if !ok {
		return nil, false
	}
	o, ok := v.(*Object)
	return o, ok
}

// parsePipeAllowingDefsOnly parses the top-level: a sequence of defs possibly followed by a body.
func (ps *Parser) parsePipeAllowingDefsOnly() Node {
	if ps.isKeyword("def") {
		def := ps.parseFuncDef()
		if ps.peek().Kind == TEOF {
			return &FuncDefNode{Def: def, Rest: nil}
		}
		rest := ps.parsePipeAllowingDefsOnly()
		return &FuncDefNode{Def: def, Rest: rest}
	}
	return ps.parsePipe()
}

// parsePipe: Pipe := CommaExpr ('|' Pipe)?
func (ps *Parser) parsePipe() Node {
	left := ps.parseComma()
	if ps.isPunct("|") {
		ps.next()
		right := ps.parsePipe()
		return &PipeNode{L: left, R: right}
	}
	return left
}

func (ps *Parser) parseComma() Node {
	left := ps.parseCommaOperand()
	for ps.isPunct(",") {
		ps.next()
		right := ps.parseCommaOperand()
		left = &CommaNode{L: left, R: right}
	}
	return left
}

// parseCommaOperand: def ... ; Pipe | label $x | Pipe | Alt (as Patterns | Pipe)?
func (ps *Parser) parseCommaOperand() Node {
	if ps.isKeyword("def") {
		def := ps.parseFuncDef()
		rest := ps.parsePipe()
		return &FuncDefNode{Def: def, Rest: rest}
	}
	if ps.isKeyword("label") {
		ps.next()
		t := ps.peek()
		if t.Kind != TBinding {
			ps.syntaxError("BINDING")
		}
		ps.next()
		ps.expectPunct("|", "'|'")
		body := ps.parsePipe()
		return &LabelNode{Name: t.Text[1:], Body: body}
	}
	e := ps.parseAlt()
	if ps.isKeyword("as") {
		ps.next()
		pats := ps.parsePatterns()
		ps.expectPunct("|", "'|'")
		body := ps.parsePipe()
		return &BindNode{Source: e, Patterns: pats, Body: body}
	}
	return e
}

// parseObjVal: ExpD := Alt ('|' Alt)*
func (ps *Parser) parseObjVal() Node {
	left := ps.parseAlt()
	for ps.isPunct("|") {
		ps.next()
		right := ps.parseAlt()
		left = &PipeNode{L: left, R: right}
	}
	return left
}

// parseAlt: right-assoc "//"
func (ps *Parser) parseAlt() Node {
	left := ps.parseAssign()
	if ps.isPunct("//") {
		ps.next()
		right := ps.parseAlt()
		return &AltNode{L: left, R: right}
	}
	return left
}

var assignOps = map[string]bool{"=": true, "|=": true, "+=": true, "-=": true, "*=": true, "/=": true, "%=": true, "//=": true}

func (ps *Parser) parseAssign() Node {
	left := ps.parseOr()
	t := ps.peek()
	if t.Kind == TPunct && assignOps[t.Text] {
		ps.next()
		right := ps.parseOr()
		n := &AssignNode{Op: t.Text, L: left, R: right}
		t2 := ps.peek()
		if t2.Kind == TPunct && assignOps[t2.Text] {
			ps.syntaxError("")
		}
		return n
	}
	return left
}

func (ps *Parser) parseOr() Node {
	left := ps.parseAnd()
	for ps.isKeyword("or") {
		ps.next()
		right := ps.parseAnd()
		left = &OrNode{L: left, R: right}
	}
	return left
}

func (ps *Parser) parseAnd() Node {
	left := ps.parseCompare()
	for ps.isKeyword("and") {
		ps.next()
		right := ps.parseCompare()
		left = &AndNode{L: left, R: right}
	}
	return left
}

var compareOps = map[string]bool{"==": true, "!=": true, "<": true, ">": true, "<=": true, ">=": true}

func (ps *Parser) parseCompare() Node {
	left := ps.parseAdditive()
	t := ps.peek()
	if t.Kind == TPunct && compareOps[t.Text] {
		ps.next()
		right := ps.parseAdditive()
		n := &BinopNode{Op: t.Text, L: left, R: right}
		t2 := ps.peek()
		if t2.Kind == TPunct && compareOps[t2.Text] {
			ps.syntaxError("")
		}
		return n
	}
	return left
}

func (ps *Parser) parseAdditive() Node {
	left := ps.parseMultiplicative()
	for {
		t := ps.peek()
		if t.Kind == TPunct && (t.Text == "+" || t.Text == "-") {
			ps.next()
			right := ps.parseMultiplicative()
			left = &BinopNode{Op: t.Text, L: left, R: right}
		} else {
			return left
		}
	}
}

func (ps *Parser) parseMultiplicative() Node {
	left := ps.parseUnary()
	for {
		t := ps.peek()
		if t.Kind == TPunct && (t.Text == "*" || t.Text == "/" || t.Text == "%") {
			ps.next()
			right := ps.parseUnary()
			left = &BinopNode{Op: t.Text, L: left, R: right}
		} else {
			return left
		}
	}
}

func (ps *Parser) parseUnary() Node {
	if ps.isPunct("-") {
		ps.next()
		body := ps.parseUnary()
		return &NegNode{Body: body}
	}
	return ps.parsePrimaryAndPostfix()
}

func (ps *Parser) parsePrimaryAndPostfix() Node {
	term := ps.parsePrimary()
	return ps.parsePostfix(term)
}

func (ps *Parser) parsePostfix(term Node) Node {
	for {
		t := ps.peek()
		switch {
		case t.Kind == TField:
			ps.next()
			term = &IndexNode{Target: term, Key: &LiteralNode{Value: t.Text[1:], Pos: t.Pos, End: t.End}, Pos: t.Pos}
			term = ps.maybeOpt(term)
		case t.Kind == TPunct && t.Text == ".":
			// ."str" or .[...]
			nt := ps.toks[ps.p+1]
			if nt.Kind == TQQStart {
				ps.next()
				s := ps.parseString("")
				term = &IndexNode{Target: term, Key: s, Pos: t.Pos}
				term = ps.maybeOpt(term)
			} else if nt.Kind == TPunct && nt.Text == "[" {
				ps.next()
				term = ps.parseBracketSuffix(term)
			} else if nt.Kind == TFormat {
				ps.next()
				s := ps.parseFormatString()
				term = &IndexNode{Target: term, Key: s, Pos: t.Pos}
				term = ps.maybeOpt(term)
			} else {
				ps.next()
				ps.syntaxError("FORMAT or QQSTRING_START or '['")
			}
		case t.Kind == TPunct && t.Text == "[":
			term = ps.parseBracketSuffix(term)
		case t.Kind == TPunct && t.Text == "?":
			ps.next()
			term = &TryNode{Body: term}
		default:
			return term
		}
	}
}

func (ps *Parser) maybeOpt(term Node) Node {
	if ps.isPunct("?") {
		ps.next()
		switch x := term.(type) {
		case *IndexNode:
			x.Opt = true
		case *SliceNode:
			x.Opt = true
		case *EachNode:
			x.Opt = true
		default:
			return &TryNode{Body: term}
		}
	}
	return term
}

// parseBracketSuffix parses [ ... ] after a term: .[], .[e], .[e:e], .[:e], .[e:]
func (ps *Parser) parseBracketSuffix(term Node) Node {
	open := ps.expectPunct("[", "")
	if ps.isPunct("]") {
		ps.next()
		return ps.maybeOpt(&EachNode{Target: term})
	}
	if ps.isPunct(":") {
		ps.next()
		to := ps.parsePipe()
		ps.expectPunct("]", "']'")
		return ps.maybeOpt(&SliceNode{Target: term, To: to})
	}
	e := ps.parsePipe()
	if ps.isPunct(":") {
		ps.next()
		if ps.isPunct("]") {
			ps.next()
			return ps.maybeOpt(&SliceNode{Target: term, From: e})
		}
		to := ps.parsePipe()
		ps.expectPunct("]", "']'")
		return ps.maybeOpt(&SliceNode{Target: term, From: e, To: to})
	}
	if !ps.isPunct("]") {
		ps.syntaxError("'|' or ',' or ':' or ']'")
	}
	ps.next()
	return ps.maybeOpt(&IndexNode{Target: term, Key: e, Pos: open.Pos})
}

func (ps *Parser) parsePrimary() Node {
	t := ps.peek()
	switch t.Kind {
	case TPunct:
		switch t.Text {
		case ".":
			ps.next()
			nt := ps.peek()
			if nt.Kind == TQQStart {
				s := ps.parseString("")
				return ps.maybeOpt(&IndexNode{Target: nil, Key: s, Pos: t.Pos})
			}
			if nt.Kind == TFormat {
				s := ps.parseFormatString()
				return ps.maybeOpt(&IndexNode{Target: nil, Key: s, Pos: t.Pos})
			}
			if nt.Kind == TPunct && nt.Text == "[" {
				return ps.parseBracketSuffix(nil)
			}
			if nt.Kind == TIdent {
				// ". a" error
				ps.errors = append(ps.errors, CompileError{Msg: "syntax error, unexpected IDENT, expecting end of file", Pos: nt.Pos, End: nt.End})
				ps.errors = append(ps.errors, CompileError{Msg: "try .[\"field\"] instead of .field for unusually named fields", Pos: t.Pos, End: nt.End})
				panic(parseAbort{})
			}
			return IdentityNode{}
		case "..":
			ps.next()
			return RecurseNode{}
		case "(":
			ps.next()
			e := ps.parsePipe()
			ps.expectPunct(")", "'|' or ',' or ')'")
			return e
		case "[":
			ps.next()
			if ps.isPunct("]") {
				ps.next()
				return &ArrayNode{}
			}
			e := ps.parsePipe()
			ps.expectPunct("]", "'|' or ',' or ']'")
			return &ArrayNode{Body: e}
		case "{":
			return ps.parseObject()
		case "$":
			ps.next()
			ps.syntaxError("'$'")
		}
	case TField:
		ps.next()
		return ps.maybeOpt(&IndexNode{Target: nil, Key: &LiteralNode{Value: t.Text[1:], Pos: t.Pos, End: t.End}, Pos: t.Pos})
	case TLiteral:
		ps.next()
		v, ok := parseDecimalLiteral(t.Text)
		if !ok {
			v = 0.0
		}
		return &LiteralNode{Value: v, Pos: t.Pos, End: t.End}
	case TQQStart:
		return ps.parseString("")
	case TFormat:
		ps.next()
		if ps.peek().Kind == TQQStart {
			return ps.parseString(t.Text)
		}
		return &FormatNode{Name: t.Text, Pos: t.Pos, End: t.End}
	case TLoc:
		ps.next()
		return &LocNode{File: ps.fname, Line: lineOf(ps.src, t.Pos)}
	case TBinding:
		ps.next()
		return &VarNode{Name: t.Text[1:], Pos: t.Pos, End: t.End}
	case TIdent:
		ps.next()
		call := &CallNode{Name: t.Text, Pos: t.Pos, End: t.End}
		if ps.isPunct("(") {
			ps.next()
			for {
				arg := ps.parsePipe()
				call.Args = append(call.Args, arg)
				if ps.isPunct(";") {
					ps.next()
					continue
				}
				ps.expectPunct(")", "'|' or ',' or ';' or ')'")
				break
			}
		}
		return call
	case TKeyword:
		switch t.Text {
		case "if":
			return ps.parseIf()
		case "try":
			ps.next()
			body := ps.parsePostTry()
			var catch Node
			if ps.isKeyword("catch") {
				ps.next()
				catch = ps.parsePostTry()
			}
			return &TryNode{Body: body, Catch: catch, hasCatch: catch != nil}
		case "reduce":
			ps.next()
			src := ps.parseReduceSource()
			ps.expectKeyword("as", "")
			pats := ps.parsePatterns()
			ps.expectPunct("(", "'('")
			init := ps.parsePipe()
			ps.expectPunct(";", "';'")
			update := ps.parsePipe()
			ps.expectPunct(")", "')'")
			return &ReduceNode{Source: src, Patterns: pats, Init: init, Update: update}
		case "foreach":
			ps.next()
			src := ps.parseReduceSource()
			ps.expectKeyword("as", "")
			pats := ps.parsePatterns()
			ps.expectPunct("(", "'('")
			init := ps.parsePipe()
			ps.expectPunct(";", "';'")
			update := ps.parsePipe()
			var extract Node
			if ps.isPunct(";") {
				ps.next()
				extract = ps.parsePipe()
			}
			ps.expectPunct(")", "')'")
			return &ForeachNode{Source: src, Patterns: pats, Init: init, Update: update, Extract: extract}
		case "def", "label":
			// not allowed here
			ps.syntaxError("")
		case "__loc__":
			ps.syntaxError("")
		}
		ps.syntaxError("")
	case TEOF:
		ps.syntaxError("")
	}
	ps.syntaxError("")
	return nil
}

// parseReduceSource parses the source of reduce/foreach (a postfix term, allowing unary minus and binary ops without comma).
func (ps *Parser) parseReduceSource() Node {
	return ps.parseAlt()
}

// parsePostTry parses the body of try/catch: a unary-level expression.
func (ps *Parser) parsePostTry() Node {
	return ps.parseUnary()
}

func (ps *Parser) parseIf() Node {
	ifTok := ps.next() // if
	ps.ifStack = append(ps.ifStack, ifTok.Pos)
	cond := ps.parsePipe()
	ps.expectKeyword("then", "then")
	then := ps.parsePipe()
	var els Node
	switch {
	case ps.isKeyword("elif"):
		els = ps.parseElif()
	case ps.isKeyword("else"):
		ps.next()
		els = ps.parsePipe()
		ps.expectKeyword("end", "end or '|' or ','")
	case ps.isKeyword("end"):
		ps.next()
	default:
		ps.syntaxError("")
	}
	ps.ifStack = ps.ifStack[:len(ps.ifStack)-1]
	return &IfNode{Cond: cond, Then: then, Else: els}
}

func (ps *Parser) parseElif() Node {
	ps.next() // elif
	cond := ps.parsePipe()
	ps.expectKeyword("then", "then")
	then := ps.parsePipe()
	var els Node
	switch {
	case ps.isKeyword("elif"):
		els = ps.parseElif()
	case ps.isKeyword("else"):
		ps.next()
		els = ps.parsePipe()
		ps.expectKeyword("end", "end or '|' or ','")
	case ps.isKeyword("end"):
		ps.next()
	default:
		ps.syntaxError("")
	}
	return &IfNode{Cond: cond, Then: then, Else: els}
}

func (ps *Parser) parseFuncDef() *FuncDef {
	defTok := ps.next() // def
	t := ps.peek()
	if t.Kind != TIdent {
		ps.syntaxError("IDENT")
	}
	ps.next()
	def := &FuncDef{Name: t.Text, Pos: defTok.Pos}
	if ps.isPunct("(") {
		ps.next()
		for {
			pt := ps.peek()
			if pt.Kind == TIdent {
				def.Params = append(def.Params, pt.Text)
			} else if pt.Kind == TBinding {
				def.Params = append(def.Params, pt.Text)
			} else {
				ps.syntaxError("IDENT or BINDING")
			}
			ps.next()
			if ps.isPunct(";") {
				ps.next()
				continue
			}
			ps.expectPunct(")", "';' or ')'")
			break
		}
	}
	ps.expectPunct(":", "':'")
	def.Body = ps.parsePipe()
	def.End = ps.peek().End
	ps.expectPunct(";", "'|' or ',' or ';'")
	return def
}

func (ps *Parser) parsePatterns() []Pattern {
	var pats []Pattern
	pats = append(pats, ps.parsePattern())
	for ps.isPunct("?//") {
		ps.next()
		pats = append(pats, ps.parsePattern())
	}
	return pats
}

func (ps *Parser) parsePattern() Pattern {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		return &VarPattern{Name: t.Text[1:]}
	case t.Kind == TPunct && t.Text == "[":
		ps.next()
		ap := &ArrayPattern{}
		for {
			ap.Elems = append(ap.Elems, ps.parsePattern())
			if ps.isPunct(",") {
				ps.next()
				continue
			}
			ps.expectPunct("]", "',' or ']'")
			break
		}
		return ap
	case t.Kind == TPunct && t.Text == "{":
		ps.next()
		op := &ObjectPattern{}
		for {
			op.Entries = append(op.Entries, ps.parseObjPatEntry())
			if ps.isPunct(",") {
				ps.next()
				continue
			}
			ps.expectPunct("}", "',' or '}'")
			break
		}
		return op
	}
	ps.syntaxError("BINDING or '[' or '{'")
	return nil
}

func (ps *Parser) parseObjPatEntry() ObjPatEntry {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		e := ObjPatEntry{KeyVar: t.Text[1:]}
		if ps.isPunct(":") {
			ps.next()
			e.Val = ps.parsePattern()
		}
		return e
	case t.Kind == TIdent || t.Kind == TKeyword:
		ps.next()
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: &LiteralNode{Value: t.Text, Pos: t.Pos, End: t.End}, Val: ps.parsePattern()}
	case t.Kind == TQQStart:
		s := ps.parseString("")
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: s, Val: ps.parsePattern()}
	case t.Kind == TFormat:
		ps.next()
		s := ps.parseString(t.Text)
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: s, Val: ps.parsePattern()}
	case t.Kind == TPunct && t.Text == "(":
		ps.next()
		k := ps.parsePipe()
		ps.expectPunct(")", "')'")
		ps.expectPunct(":", "':'")
		return ObjPatEntry{Key: k, Val: ps.parsePattern()}
	}
	ps.syntaxError("")
	return ObjPatEntry{}
}

func (ps *Parser) parseObject() Node {
	ps.expectPunct("{", "")
	obj := &ObjectNode{}
	if ps.isPunct("}") {
		ps.next()
		return obj
	}
	for {
		obj.Entries = append(obj.Entries, ps.parseObjEntry())
		if ps.isPunct(",") {
			ps.next()
			if ps.isPunct("}") {
				ps.next()
				break
			}
			continue
		}
		ps.expectPunct("}", "'}'")
		break
	}
	return obj
}

func (ps *Parser) parseObjEntry() ObjectEntry {
	t := ps.peek()
	switch {
	case t.Kind == TBinding:
		ps.next()
		e := ObjectEntry{KeyVar: t.Text[1:], KeyIsVar: true, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TLoc:
		ps.next()
		e := ObjectEntry{KeyLoc: true, LocLine: lineOf(ps.src, t.Pos), KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TIdent || t.Kind == TKeyword:
		ps.next()
		e := ObjectEntry{Key: &LiteralNode{Value: t.Text, Pos: t.Pos, End: t.End}, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TQQStart:
		s := ps.parseString("")
		e := ObjectEntry{Key: s, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TFormat:
		ps.next()
		s := ps.parseString(t.Text)
		e := ObjectEntry{Key: s, KeyPos: t.Pos}
		if ps.isPunct(":") {
			ps.next()
			e.Value = ps.parseObjVal()
		}
		return e
	case t.Kind == TLiteral:
		ps.next()
		v, _ := parseDecimalLiteral(t.Text)
		ps.failAt(t.Pos, t.End, fmt.Sprintf("Cannot use %s (%s) as object key", typeName(v), dumpTrunc(v, 11)))
	case t.Kind == TPunct && t.Text == "(":
		ps.next()
		k := ps.parsePipe()
		ps.expectPunct(")", "')'")
		ps.expectPunct(":", "':'")
		if cv, ok := constValueOf(k); ok {
			if _, isStr := cv.(string); !isStr {
				start, end := nodeSpan(k)
				ps.failAt(start, end, fmt.Sprintf("Cannot use %s (%s) as object key", typeName(cv), dumpTrunc(cv, 11)))
			}
		}
		return ObjectEntry{Key: k, Value: ps.parseObjVal(), KeyPos: t.Pos}
	}
	ps.syntaxError("")
	return ObjectEntry{}
}

func nodeSpan(n Node) (int, int) {
	switch x := n.(type) {
	case *LiteralNode:
		return x.Pos, x.End
	case *CallNode:
		return x.Pos, x.End
	}
	return 0, 0
}

// parseString parses a string literal starting at QQSTRING_START. format is e.g. "@base64" or "".
func (ps *Parser) parseString(format string) Node {
	start := ps.peek()
	if start.Kind != TQQStart {
		ps.syntaxError("QQSTRING_START")
	}
	ps.next()
	node := &StringNode{Format: format}
	for {
		t := ps.peek()
		switch t.Kind {
		case TQQText:
			ps.next()
			// unescape via JSON parser semantics
			s, err := unescapeStringLiteral(t.Text)
			if err != nil {
				ps.failAt(t.Pos, t.End, err.Error())
			}
			node.Parts = append(node.Parts, s)
		case TQQInterpStart:
			ps.next()
			e := ps.parsePipe()
			if ps.peek().Kind != TQQInterpEnd {
				ps.syntaxError("QQSTRING_INTERP_END or '|' or ','")
			}
			ps.next()
			node.Parts = append(node.Parts, e)
		case TQQEnd:
			ps.next()
			// constant string?
			if len(node.Parts) == 0 {
				return &LiteralNode{Value: "", Pos: start.Pos, End: t.End}
			}
			if len(node.Parts) == 1 {
				if s, ok := node.Parts[0].(string); ok && format == "" {
					return &LiteralNode{Value: s, Pos: start.Pos, End: t.End}
				}
			}
			return node
		default:
			ps.syntaxError("QQSTRING_TEXT or QQSTRING_INTERP_START or QQSTRING_END")
		}
	}
}

func (ps *Parser) parseFormatString() Node {
	t := ps.next() // format token
	return ps.parseString(t.Text)
}

// unescapeStringLiteral unescapes the raw text of a jq string literal segment using the JSON parser.
func unescapeStringLiteral(raw string) (string, error) {
	v, err := parseJSONOne("\"" + raw + "\"")
	if err != nil {
		return "", err
	}
	s, _ := v.(string)
	return s, nil
}

func lineOf(src string, pos int) int {
	line := 1
	for i := 0; i < pos && i < len(src); i++ {
		if src[i] == '\n' {
			line++
		}
	}
	return line
}

// formatCompileError renders the error message with location like jq does.
func formatCompileError(src string, fname string, e CompileError) string {
	if e.Pos < 0 {
		return fmt.Sprintf("jq: error: %s", e.Msg)
	}
	// find line
	lineStart := 0
	lineNo := 1
	for i := 0; i < e.Pos && i < len(src); i++ {
		if src[i] == '\n' {
			lineNo++
			lineStart = i + 1
		}
	}
	lineEnd := strings.IndexByte(src[lineStart:], '\n')
	if lineEnd < 0 {
		lineEnd = len(src)
	} else {
		lineEnd += lineStart
	}
	col := e.Pos - lineStart
	end := e.End
	if end > lineEnd {
		end = lineEnd
	}
	n := end - e.Pos
	if n < 1 {
		n = 1
	}
	return fmt.Sprintf("jq: error: %s at %s, line %d, column %d:\n    %s\n    %s%s", e.Msg, fname, lineNo, col+1, src[lineStart:lineEnd], strings.Repeat(" ", col), strings.Repeat("^", n))
}
