func (in *Interp) eval(n Node, env *Frame, input Value, path *pathT, emit emitFn) error {
	switch x := n.(type) {
	case IdentityNode:
		return emit(input, path)
	case RecurseNode:
		return in.recurseDefault(input, path, emit)
	case *LiteralNode:
		return emit(x.Value, path)
	case *LocNode:
		o := NewObject()
		o.SetInPlace("file", x.File)
		o.SetInPlace("line", float64(x.Line))
		return emit(o, path)
	case *VarNode:
		f := lookupFrame(env, x.res.hops)
		return emit(f.vars[x.res.slot], path)
	case *PipeNode:
		return in.eval(x.L, env, input, path, func(v Value, p *pathT) error {
			return in.eval(x.R, env, v, p, emit)
		})
	case *CommaNode:
		if err := in.eval(x.L, env, input, path, emit); err != nil {
			return err
		}
		return in.eval(x.R, env, input, path, emit)
	case *IndexNode:
		return in.evalIndex(x, env, input, path, emit)
	case *SliceNode:
		return in.evalSlice(x, env, input, path, emit)
	case *EachNode:
		return in.evalEach(x, env, input, path, emit)
	case *StringNode:
		return in.evalString(x, env, input, path, emit)
	case *FormatNode:
		s, err := applyFormat(x.Name, input)
		if err != nil {
			return err
		}
		return emit(s, path)
	case *ArrayNode:
		if x.Body == nil {
			return emit([]Value{}, path)
		}
		arr := []Value{}
		err := in.eval(x.Body, env, input, nil, func(v Value, _ *pathT) error {
			arr = append(arr, v)
			return nil
		})
		if err != nil {
			return err
		}
		return emit(arr, path)
	case *ObjectNode:
		return in.evalObject(x, env, input, path, emit)
	case *NegNode:
		return in.eval(x.Body, env, input, nil, func(v Value, _ *pathT) error {
			switch num := v.(type) {
			case float64:
				return emit(-num, path)
			case *LitNum:
				return emit(num.Negate(), path)
			}
			return emit(nil, path) // unreachable
		})
	case *BinopNode:
		// rhs outer, lhs inner
		return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
			return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
				v, err := binop(x.Op, l, r)
				if err != nil {
					return err
				}
				return emit(v, path)
			})
		})
	case *AndNode:
		return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
			if !truthy(l) {
				return emit(false, path)
			}
			return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
				return emit(truthy(r), path)
			})
		})
	case *OrNode:
		return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
			if truthy(l) {
				return emit(true, path)
			}
			return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
				return emit(truthy(r), path)
			})
		})
	case *AltNode:
		any := false
		err := in.eval(x.L, env, input, path, func(v Value, p *pathT) error {
			if truthy(v) {
				any = true
				return emit(v, p)
			}
			return nil
		})
		if err != nil {
			if isPassthrough(err) {
				return err
			}
			if _, ok := err.(*JQError); !ok {
				return err
			}
			// errors in lhs are suppressed
			if any {
				return nil
			}
		}
		if any {
			return nil
		}
		return in.eval(x.R, env, input, path, emit)
	case *IfNode:
		return in.eval(x.Cond, env, input, nil, func(c Value, _ *pathT) error {
			if truthy(c) {
				return in.eval(x.Then, env, input, path, emit)
			}
			if x.Else == nil {
				return emit(input, path)
			}
			return in.eval(x.Else, env, input, path, emit)
		})
	case *TryNode:
		return in.evalTry(x, env, input, path, emit)
	case *ReduceNode:
		return in.evalReduce(x, env, input, path, emit)
	case *ForeachNode:
		return in.evalForeach(x, env, input, path, emit)
	case *FuncDefNode:
