		fr := &Frame{parent: env}
		node := Node(x)
		var rest Node = x
		for {
			fd, ok := rest.(*FuncDefNode)
			if !ok {
				break
			}
			fr.funcs = append(fr.funcs, &Closure{def: fd.Def, env: fr})
			rest = fd.Rest
			node = fd
		}
