cd /workspace && cat > interp.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

// ---- runtime structures ----

type Frame struct {
	parent *Frame
	vars   []Value
	funcs  []*Closure
}

type Closure struct {
	def  *FuncDef // nil for param closures
	body Node     // for param closures
	env  *Frame
}

type pathT struct {
	path []Value
	vap  Value // value at path
}

func (p *pathT) append(k Value, v Value) *pathT {
	np := make([]Value, len(p.path)+1)
	copy(np, p.path)
	np[len(p.path)] = k
	return &pathT{path: np, vap: v}
}

func (p *pathT) appendAll(ks []Value, v Value) *pathT {
	np := make([]Value, len(p.path)+len(ks))
	copy(np, p.path)
	copy(np[len(p.path):], ks)
	return &pathT{path: np, vap: v}
}

type emitFn func(v Value, p *pathT) error

// ---- errors ----

type JQError struct {
	Val Value
}

func (e *JQError) Error() string {
	if s, ok := e.Val.(string); ok {
		return s
	}
	return toJSON(e.Val)
}

func newError(format string, args ...any) error {
	return &JQError{Val: sanitizeUTF8(fmt.Sprintf(format, args...))}
}

type BreakError struct {
	label *labelToken
}

func (e *BreakError) Error() string { return "break" }

type labelToken struct{ id int }

type HaltError struct {
	Code int
	Val  Value
	Has  bool
}

func (e *HaltError) Error() string { return "halt" }

// passthrough wraps errors raised downstream of a try body so the try doesn't catch them.
type passthrough struct{ err error }

func (e *passthrough) Error() string { return e.err.Error() }

// stopIteration is used internally to stop generators early.
type stopIteration struct{}

func (stopIteration) Error() string { return "stop" }

var errStop error = stopIteration{}

// ---- interpreter ----

type Interp struct {
	root       *Frame
	labelCount int
	inputs     InputSource
	stderr     func(string)
	envObj     *Object
	namedArgs  *Object
	posArgs    []Value
	loader     *ModuleLoader
	progOrigin string
	jqOrigin   string
	searchList []Value
	nullInput  bool
	// module metadata for imported modules
}

type InputSource interface {
	Next() (Value, bool, error) // next input value; ok=false at end
	CurrentFilename() Value
	CurrentLine() int
}

func (in *Interp) newLabel() *labelToken {
	in.labelCount++
	return &labelToken{id: in.labelCount}
}

func lookupFrame(env *Frame, hops int) *Frame {
	for i := 0; i < hops; i++ {
		env = env.parent
	}
	return env
}

// ---- type error helpers ----

func typeErr(v Value, msg string) error {
	return newError("%s (%s) %s", typeName(v), dumpTrunc(v, 15), msg)
}

func typeErr2(a, b Value, msg string) error {
	return newError("%s (%s) and %s (%s) %s", typeName(a), dumpTrunc(a, 15), typeName(b), dumpTrunc(b, 15), msg)
}

// ---- core eval ----

func (in *Interp) eval(n Node, env *Frame, input Value, path *pathT, emit emitFn) error {
	switch x := n.(type) {
	case IdentityNode:
		return emit(input, path)
	case RecurseNode:
		return in.recurseDefault(input, path, emit)
	case *LiteralNode:
		return emit(x.Value, path)
	case *LocNode:
		o := NewObject()
		o.SetInPlace("file", x.File)
		o.SetInPlace("line", float64(x.Line))
		return emit(o, path)
	case *VarNode:
		f := lookupFrame(env, x.res.hops)
		return emit(f.vars[x.res.slot], path)
	case *PipeNode:
		return in.eval(x.L, env, input, path, func(v Value, p *pathT) error {
			return in.eval(x.R, env, v, p, emit)
		})
	case *CommaNode:
		if err := in.eval(x.L, env, input, path, emit); err != nil {
			return err
		}
		return in.eval(x.R, env, input, path, emit)
	case *IndexNode:
		return in.evalIndex(x, env, input, path, emit)
	case *SliceNode:
		return in.evalSlice(x, env, input, path, emit)
	case *EachNode:
		return in.evalEach(x, env, input, path, emit)
	case *StringNode:
		return in.evalString(x, env, input, path, emit)
	case *FormatNode:
		s, err := applyFormat(x.Name, input)
		if err != nil {
			return err
		}
		return emit(s, path)
	case *ArrayNode:
		if x.Body == nil {
			return emit([]Value{}, path)
		}
		arr := []Value{}
		err := in.eval(x.Body, env, input, nil, func(v Value, _ *pathT) error {
			arr = append(arr, v)
			return nil
		})
		if err != nil {
			return err
		}
		return emit(arr, path)
	case *ObjectNode:
		return in.evalObject(x, env, input, path, emit)
	case *NegNode:
		return in.eval(x.Body, env, input, nil, func(v Value, _ *pathT) error {
			switch num := v.(type) {
			case float64:
				return emit(-num, path)
			case *LitNum:
				return emit(num.Negate(), path)
			}
			return emit(nil, path) // unreachable
		})
	case *BinopNode:
		// rhs outer, lhs inner
		return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
			return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
				v, err := binop(x.Op, l, r)
				if err != nil {
					return err
				}
				return emit(v, path)
			})
		})
	case *AndNode:
		return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
			if !truthy(l) {
				return emit(false, path)
			}
			return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
				return emit(truthy(r), path)
			})
		})
	case *OrNode:
		return in.eval(x.L, env, input, nil, func(l Value, _ *pathT) error {
			if truthy(l) {
				return emit(true, path)
			}
			return in.eval(x.R, env, input, nil, func(r Value, _ *pathT) error {
				return emit(truthy(r), path)
			})
		})
	case *AltNode:
		any := false
		err := in.eval(x.L, env, input, path, func(v Value, p *pathT) error {
			if truthy(v) {
				any = true
				return emit(v, p)
			}
			return nil
		})
		if err != nil {
			if isPassthrough(err) {
				return err
			}
			if _, ok := err.(*JQError); !ok {
				return err
			}
			// errors in lhs are suppressed
			if any {
				return nil
			}
		}
		if any {
			return nil
		}
		return in.eval(x.R, env, input, path, emit)
	case *IfNode:
		return in.eval(x.Cond, env, input, nil, func(c Value, _ *pathT) error {
			if truthy(c) {
				return in.eval(x.Then, env, input, path, emit)
			}
			if x.Else == nil {
				return emit(input, path)
			}
			return in.eval(x.Else, env, input, path, emit)
		})
	case *TryNode:
		return in.evalTry(x, env, input, path, emit)
	case *ReduceNode:
		return in.evalReduce(x, env, input, path, emit)
	case *ForeachNode:
		return in.evalForeach(x, env, input, path, emit)
	case *FuncDefNode:
		// new frame with the def closure(s)
		fr := &Frame{parent: env}
		node := Node(x)
		var rest Node = x
		for {
			fd, ok := rest.(*FuncDefNode)
			if !ok {
				break
			}
			fr.funcs = append(fr.funcs, &Closure{def: fd.Def, env: fr})
			rest = fd.Rest
			node = fd
		}
		_ = node
		if rest == nil {
			return emit(input, path)
		}
		return in.eval(rest, fr, input, path, emit)
	case *CallNode:
		return in.evalCall(x, env, input, path, emit)
	case *BindNode:
		return in.evalBind(x, env, input, path, emit)
	case *LabelNode:
		tok := in.newLabel()
		fr := &Frame{parent: env, vars: []Value{tok}}
		err := in.eval(x.Body, fr, input, path, emit)
		if err != nil {
			if be, ok := err.(*BreakError); ok && be.label == tok {
				return nil
			}
			return err
		}
		return nil
	case *BreakNode:
		f := lookupFrame(env, x.res.hops)
		tok := f.vars[x.res.slot].(*labelToken)
		return &BreakError{label: tok}
	case *AssignNode:
		return in.evalAssign(x, env, input, path, emit)
	}
	return fmt.Errorf("unknown node type %T", n)
}

func isPassthrough(err error) bool {
	_, ok := err.(*passthrough)
	return ok
}

// ---- indexing ----

func (in *Interp) evalTarget(t Node, env *Frame, input Value, path *pathT, f func(v Value, p *pathT) error) error {
	if t == nil {
		return f(input, path)
	}
	return in.eval(t, env, input, path, f)
}

func (in *Interp) evalIndex(x *IndexNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	// key evaluated first (outer), against the original input
	return in.eval(x.Key, env, input, nil, func(k Value, _ *pathT) error {
		return in.evalTarget(x.Target, env, input, path, func(t Value, tp *pathT) error {
			if tp != nil && !identical(t, tp.vap) {
				return newError("Invalid path expression near attempt to access element %s of %s", dumpTrunc(k, 15), dumpTrunc(t, 30))
			}
			v, err := indexValue(t, k)
			if err != nil {
				if x.Opt {
					return nil
				}
				return err
			}
			var np *pathT
			if tp != nil {
				np = tp.append(k, v)
			}
			return emit(v, np)
		})
	})
}

func (in *Interp) evalSlice(x *SliceNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	evalOpt := func(n Node, f func(Value) error) error {
		if n == nil {
			return f(nil)
		}
		return in.eval(n, env, input, nil, func(v Value, _ *pathT) error { return f(v) })
	}
	return evalOpt(x.From, func(from Value) error {
		return evalOpt(x.To, func(to Value) error {
			k := NewObject()
			k.SetInPlace("start", from)
			k.SetInPlace("end", to)
			return in.evalTarget(x.Target, env, input, path, func(t Value, tp *pathT) error {
				if tp != nil && !identical(t, tp.vap) {
					return newError("Invalid path expression near attempt to access element %s of %s", dumpTrunc(k, 15), dumpTrunc(t, 30))
				}
				v, err := indexValue(t, k)
				if err != nil {
					if x.Opt {
						return nil
					}
					return err
				}
				var np *pathT
				if tp != nil {
					np = tp.append(k, v)
				}
				return emit(v, np)
			})
		})
	})
}

func (in *Interp) evalEach(x *EachNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	return in.evalTarget(x.Target, env, input, path, func(t Value, tp *pathT) error {
		if tp != nil && !identical(t, tp.vap) {
			return newError("Invalid path expression near attempt to iterate through %s", dumpTrunc(t, 30))
		}
		return in.iterate(t, tp, x.Opt, emit)
	})
}

func (in *Interp) iterate(t Value, tp *pathT, opt bool, emit emitFn) error {
	switch c := t.(type) {
	case []Value:
		for i, e := range c {
			var np *pathT
			if tp != nil {
				np = tp.append(float64(i), e)
			}
			if err := emit(e, np); err != nil {
				return err
			}
		}
		return nil
	case *Object:
		for i, k := range c.keys {
			e := c.vals[i]
			var np *pathT
			if tp != nil {
				np = tp.append(k, e)
			}
			if err := emit(e, np); err != nil {
				return err
			}
		}
		return nil
	}
	if opt {
		return nil
	}
	return newError("Cannot iterate over %s", typeNameWithValue(t))
}

func typeNameWithValue(v Value) string {
	if v == nil {
		return "null (null)"
	}
	return fmt.Sprintf("%s (%s)", typeName(v), dumpTrunc(v, 15))
}

// indexValue implements jv_get semantics.
func indexValue(t Value, k Value) (Value, error) {
	switch tv := t.(type) {
	case *Object:
		if ks, ok := k.(string); ok {
			v, _ := tv.Get(ks)
			return v, nil
		}
		return nil, newError("Cannot index object with %s", typeName(k))
	case []Value:
		switch kv := k.(type) {
		case float64, *LitNum:
			d := numVal(kv)
			if math.IsNaN(d) {
				return nil, nil
			}
			idx := jvArrayIndex(d)
			if idx < 0 {
				idx += len(tv)
			}
			if idx < 0 || idx >= len(tv) {
				return nil, nil
			}
			return tv[idx], nil
		case *Object:
			start, end, ok := parseSlice(len(tv), kv)
			if !ok {
				return nil, newError("Array/string slice indices must be integers")
			}
			out := make([]Value, end-start)
			copy(out, tv[start:end])
			return out, nil
		case []Value:
			return arrayIndices(tv, kv), nil
		}
		return nil, newError("Cannot index array with %s", typeName(k))
	case nil:
		switch k.(type) {
		case string, float64, *LitNum, *Object:
			return nil, nil
		}
		return nil, newError("Cannot index null with %s", typeName(k))
	case string:
		if ko, ok := k.(*Object); ok {
			runes := []rune(tv)
			start, end, ok := parseSlice(len(runes), ko)
			if !ok {
				return nil, newError("Array/string slice indices must be integers")
			}
			return string(runes[start:end]), nil
		}
	}
	if ks, ok := k.(string); ok {
		return nil, newError("Cannot index %s with string \"%s\"", typeName(t), ks)
	}
	return nil, newError("Cannot index %s with %s", typeName(t), typeName(k))
}

// jvArrayIndex converts a double index to int the way jq does (truncation toward zero; floor for negatives).
func jvArrayIndex(d float64) int {
	if d >= 2147483647 {
		return math.MaxInt32
	}
	if d <= -2147483648 {
		return math.MinInt32
	}
	// jq uses (int) cast: truncation toward zero. But jv_array_get with negative double:
	// jq 1.7 does: int idx = (int)jv_number_value(k); if (idx < 0) idx += len
	return int(d)
}

func parseSlice(length int, k *Object) (int, int, bool) {
	startV, hasStart := k.Get("start")
	endV, hasEnd := k.Get("end")
	if !hasStart || !hasEnd {
		return 0, 0, false
	}
	var dstart, dend float64
	if startV == nil {
		dstart = 0
	} else if isNumber(startV) {
		dstart = numVal(startV)
	} else {
		return 0, 0, false
	}
	if endV == nil {
		dend = float64(length)
	} else if isNumber(endV) {
		dend = numVal(endV)
	} else {
		return 0, 0, false
	}
	flen := float64(length)
	if dstart < 0 {
		dstart += flen
	}
	if dend < 0 {
		dend += flen
	}
	if dstart < 0 {
		dstart = 0
	}
	if dstart > flen {
		dstart = flen
	}
	if dend > flen {
		dend = flen
	}
	if dend < dstart {
		dend = dstart
	}
	start := int(dstart)
	end := int(dend)
	if dend > float64(end) {
		end++
	}
	if end > length {
		end = length
	}
	return start, end, true
}

func arrayIndices(a []Value, b []Value) Value {
	res := []Value{}
	if len(b) == 0 {
		return res
	}
	for i := 0; i+len(b) <= len(a); i++ {
		match := true
		for j := range b {
			if !valuesEqual(a[i+j], b[j]) {
				match = false
				break
			}
		}
		if match {
			res = append(res, float64(i))
		}
	}
	return res
}

// ---- strings ----

func (in *Interp) evalString(x *StringNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	// Parts evaluated with the last interpolation as the outermost loop.
	parts := x.Parts
	var rec func(i int, acc []string) error
	rec = func(i int, acc []string) error {
		if i < 0 {
			// acc is in reverse order
			var sb strings.Builder
			for j := len(acc) - 1; j >= 0; j-- {
				sb.WriteString(acc[j])
			}
			return emit(sb.String(), path)
		}
		switch p := parts[i].(type) {
		case string:
			return rec(i-1, append(acc, p))
		case Node:
			return in.eval(p, env, input, nil, func(v Value, _ *pathT) error {
				var s string
				if x.Format != "" {
					fs, err := applyFormat(x.Format, v)
					if err != nil {
						return err
					}
					s = fs
				} else {
					if str, ok := v.(string); ok {
						s = str
					} else {
						s = toJSON(v)
					}
				}
				return rec(i-1, append(acc, s))
			})
		}
		return nil
	}
	return rec(len(parts)-1, nil)
}

// ---- objects ----

func (in *Interp) evalObject(x *ObjectNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	entries := x.Entries
	var rec func(i int, obj *Object) error
	rec = func(i int, obj *Object) error {
		if i >= len(entries) {
			return emit(obj.Copy(), path)
		}
		e := entries[i]
		withKey := func(k Value) error {
			ks, ok := k.(string)
			if !ok {
				return newError("Cannot use %s (%s) as object key", typeName(k), dumpTrunc(k, 11))
			}
			if e.Value == nil {
				var v Value
				if e.KeyIsVar {
					f := lookupFrame(env, e.keyVarRes.hops)
					v = f.vars[e.keyVarRes.slot]
				} else if e.KeyLoc {
					o := NewObject()
					o.SetInPlace("file", "<top-level>")
					o.SetInPlace("line", float64(e.LocLine))
					v = o
				} else {
					var err error
					v, err = indexValue(input, ks)
					if err != nil {
						return err
					}
				}
				obj.SetInPlace(ks, v)
				return rec(i+1, obj)
			}
			return in.eval(e.Value, env, input, nil, func(v Value, _ *pathT) error {
				n := obj.Copy()
				n.SetInPlace(ks, v)
				return rec(i+1, n)
			})
		}
		if e.KeyIsVar {
			if e.Value == nil {
				return withKey(e.KeyVar)
			}
			f := lookupFrame(env, e.keyVarRes.hops)
			return withKey(f.vars[e.keyVarRes.slot])
		}
		if e.KeyLoc {
			return withKey("__loc__")
		}
		return in.eval(e.Key, env, input, nil, func(k Value, _ *pathT) error {
			return withKey(k)
		})
	}
	return rec(0, NewObject())
}

// ---- try ----

func (in *Interp) evalTry(x *TryNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	err := in.eval(x.Body, env, input, path, func(v Value, p *pathT) error {
		if e := emit(v, p); e != nil {
			return &passthrough{e}
		}
		return nil
	})
	if err == nil {
		return nil
	}
	if pt, ok := err.(*passthrough); ok {
		return pt.err
	}
	jerr, ok := err.(*JQError)
	if !ok {
		// break, halt, stop: propagate
		return err
	}
	if x.Catch == nil {
		return nil
	}
	var ev Value = jerr.Val
	return in.eval(x.Catch, env, ev, path, emit)
}

// ---- reduce / foreach ----

func (in *Interp) evalReduce(x *ReduceNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	return in.eval(x.Init, env, input, path, func(acc Value, accPath *pathT) error {
		hasAcc := true
		err := in.eval(x.Source, env, input, nil, func(item Value, _ *pathT) error {
			return in.bindPatterns(x.Patterns, env, item, func(fr *Frame) error {
				var last Value
				got := false
				err := in.eval(x.Update, fr, acc, accPath, func(v Value, _ *pathT) error {
					last = v
					got = true
					return nil
				})
				if err != nil {
					return err
				}
				if got {
					acc = last
					hasAcc = true
				} else {
					acc = nil
					hasAcc = false
				}
				return nil
			})
		})
		if err != nil {
			return err
		}
		_ = hasAcc
		return emit(acc, accPath)
	})
}

func (in *Interp) evalForeach(x *ForeachNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	return in.eval(x.Init, env, input, path, func(acc Value, accPath *pathT) error {
		return in.eval(x.Source, env, input, nil, func(item Value, _ *pathT) error {
			return in.bindPatterns(x.Patterns, env, item, func(fr *Frame) error {
				return in.eval(x.Update, fr, acc, accPath, func(v Value, vp *pathT) error {
					acc = v
					if x.Extract == nil {
						return emit(v, vp)
					}
					return in.eval(x.Extract, fr, v, vp, emit)
				})
			})
		})
	})
}

// ---- bind / destructuring ----

func (in *Interp) evalBind(x *BindNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	return in.eval(x.Source, env, input, nil, func(src Value, _ *pathT) error {
		return in.bindPatterns(x.Patterns, env, src, func(fr *Frame) error {
			return in.eval(x.Body, fr, input, path, emit)
		})
	})
}

// bindPatterns binds the value against the alternatives, calling body for each binding frame.
// All variables from all patterns live in one frame (slots assigned at compile time).
func (in *Interp) bindPatterns(pats []Pattern, env *Frame, val Value, body func(fr *Frame) error) error {
	nvars := patternsVarCount(pats)
	if len(pats) == 1 {
		fr := &Frame{parent: env, vars: make([]Value, nvars)}
		return in.destructure(pats[0], env, fr, val, func() error {
			return body(fr)
		})
	}
	// alternatives: try each in order; errors (from destructuring or body) move to the next
	for i, pat := range pats {
		fr := &Frame{parent: env, vars: make([]Value, nvars)}
		err := in.destructure(pat, env, fr, val, func() error {
			return body(fr)
		})
		if err == nil {
			return nil
		}
		if _, ok := err.(*JQError); !ok {
			return err
		}
		if i == len(pats)-1 {
			return err
		}
	}
	return nil
}

func patternsVarCount(pats []Pattern) int {
	n := 0
	for _, p := range pats {
		n = maxInt(n, patternMaxSlot(p)+1)
	}
	return n
}

func patternMaxSlot(p Pattern) int {
	m := -1
	switch x := p.(type) {
	case *VarPattern:
		if x.res != nil {
			m = maxInt(m, x.res.slot)
		}
	case *ArrayPattern:
		for _, e := range x.Elems {
			m = maxInt(m, patternMaxSlot(e))
		}
	case *ObjectPattern:
		for _, e := range x.Entries {
			if e.KeyVarRes != nil {
				m = maxInt(m, e.KeyVarRes.slot)
			}
			if e.Val != nil {
				m = maxInt(m, patternMaxSlot(e.Val))
			}
		}
	}
	return m
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// destructure binds pattern variables in frame fr (whose parent is env), then calls k.
// Key expressions in object patterns may generate multiple values -> multiple bindings.
func (in *Interp) destructure(p Pattern, env *Frame, fr *Frame, val Value, k func() error) error {
	switch x := p.(type) {
	case *VarPattern:
		fr.vars[x.res.slot] = val
		return k()
	case *ArrayPattern:
		var rec func(i int) error
		rec = func(i int) error {
			if i >= len(x.Elems) {
				return k()
			}
			elem, err := indexValue(val, float64(i))
			if err != nil {
				return err
			}
			return in.destructure(x.Elems[i], env, fr, elem, func() error { return rec(i + 1) })
		}
		if _, isArr := val.([]Value); !isArr && val != nil {
			// produce the proper error from indexing
			_, err := indexValue(val, float64(0))
			if err != nil {
				return err
			}
		}
		return rec(0)
	case *ObjectPattern:
		var rec func(i int) error
		rec = func(i int) error {
			if i >= len(x.Entries) {
				return k()
			}
			e := x.Entries[i]
			if e.KeyVar != "" {
				v, err := indexValue(val, e.KeyVar)
				if err != nil {
					return err
				}
				fr.vars[e.KeyVarRes.slot] = v
				if e.Val == nil {
					return rec(i + 1)
				}
				return in.destructure(e.Val, env, fr, v, func() error { return rec(i + 1) })
			}
			// key expression evaluated in the frame (variables bound so far are visible)
			return in.eval(e.Key, fr, val, nil, func(kv Value, _ *pathT) error {
				ks, ok := kv.(string)
				if !ok {
					return newError("Cannot index %s with %s", typeName(val), typeName(kv))
				}
				v, err := indexValue(val, ks)
				if err != nil {
					return err
				}
				return in.destructure(e.Val, env, fr, v, func() error { return rec(i + 1) })
			})
		}
		return rec(0)
	}
	return nil
}

// ---- calls ----

const (
	callDef = iota
	callParam
	callNative
)

type resolvedCall struct {
	kind   int
	hops   int
	slot   int
	native *NativeFunc
}

type resolvedVar struct {
	hops int
	slot int
}

func (in *Interp) evalCall(x *CallNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	r := x.res
	switch r.kind {
	case callNative:
		return in.callNative(r.native, x.Args, env, input, path, emit)
	case callParam:
		f := lookupFrame(env, r.hops)
		cl := f.funcs[r.slot]
		return in.callClosure(cl, nil, nil, input, path, emit)
	case callDef:
		f := lookupFrame(env, r.hops)
		cl := f.funcs[r.slot]
		return in.callClosure(cl, x.Args, env, input, path, emit)
	}
	return fmt.Errorf("bad call")
}

// callClosure invokes a closure. For def closures, args are the argument expressions in argEnv.
func (in *Interp) callClosure(cl *Closure, args []Node, argEnv *Frame, input Value, path *pathT, emit emitFn) error {
	if cl.def == nil {
		return in.eval(cl.body, cl.env, input, path, emit)
	}
	def := cl.def
	fr := &Frame{parent: cl.env}
	nParams := len(def.Params)
	fr.funcs = make([]*Closure, nParams)
	nvals := 0
	for i, p := range def.Params {
		fr.funcs[i] = &Closure{body: args[i], env: argEnv}
		if p[0] == '$' {
			nvals++
		}
	}
	if nvals == 0 {
		return in.eval(def.Body, fr, input, path, emit)
	}
	fr.vars = make([]Value, nvals)
	// evaluate $params as cartesian product, first param outermost
	var rec func(i, vi int) error
	rec = func(i, vi int) error {
		if i >= nParams {
			return in.eval(def.Body, fr, input, path, emit)
		}
		if def.Params[i][0] != '$' {
			return rec(i+1, vi)
		}
		return in.eval(args[i], argEnv, input, nil, func(v Value, _ *pathT) error {
			fr.vars[vi] = v
			return rec(i+1, vi+1)
		})
	}
	return rec(0, 0)
}

// ---- assignment ----

func (in *Interp) evalAssign(x *AssignNode, env *Frame, input Value, path *pathT, emit emitFn) error {
	switch x.Op {
	case "=":
		// for each rhs value (evaluated against input), set all paths
		return in.eval(x.R, env, input, nil, func(rv Value, _ *pathT) error {
			result := input
			err := in.eval(x.L, env, input, &pathT{path: []Value{}, vap: input}, func(v Value, p *pathT) error {
				if p == nil || !identical(v, p.vap) {
					return newError("Invalid path expression with result %s", dumpTrunc(v, 30))
				}
				var err error
				result, err = setpath(result, p.path, rv)
				return err
			})
			if err != nil {
				return err
			}
			return emit(result, path)
		})
	case "|=":
		res, err := in.modify(x.L, env, input, func(v Value, emitU func(Value) error) error {
			return in.eval(x.R, env, v, nil, func(u Value, _ *pathT) error { return emitU(u) })
		})
		if err != nil {
			return err
		}
		return emit(res, path)
	default:
		// arithmetic update: rhs as $v | lhs |= . op $v
		op := x.Op[:len(x.Op)-1]
		return in.eval(x.R, env, input, nil, func(rv Value, _ *pathT) error {
			res, err := in.modify(x.L, env, input, func(v Value, emitU func(Value) error) error {
				if op == "//" {
					if truthy(v) {
						return emitU(v)
					}
					return emitU(rv)
				}
				nv, err := binop(op, v, rv)
				if err != nil {
					return err
				}
				return emitU(nv)
			})
			if err != nil {
				return err
			}
			return emit(res, path)
		})
	}
}

// modify implements _modify(paths; update): first output of update replaces the value;
// empty output deletes the path (deletions applied at the end).
func (in *Interp) modify(lhs Node, env *Frame, input Value, update func(v Value, emitU func(Value) error) error) (Value, error) {
	result := input
	var dels []Value
	err := in.eval(lhs, env, input, &pathT{path: []Value{}, vap: input}, func(v Value, p *pathT) error {
		if p == nil || !identical(v, p.vap) {
			return newError("Invalid path expression with result %s", dumpTrunc(v, 30))
		}
		cur, err := getpath(result, p.path)
		if err != nil {
			return err
		}
		got := false
		var nv Value
		err = update(cur, func(u Value) error {
			nv = u
			got = true
			return errStop
		})
		if err != nil && err != errStop {
			return err
		}
		if got {
			result, err = setpath(result, p.path, nv)
			if err != nil {
				return err
			}
		} else {
			dels = append(dels, p.path)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if len(dels) > 0 {
		return delpaths(result, dels)
	}
	return result, nil
}

// ---- recurse ----

func (in *Interp) recurseDefault(v Value, p *pathT, emit emitFn) error {
	if err := emit(v, p); err != nil {
		return err
	}
	switch c := v.(type) {
	case []Value:
		for i, e := range c {
			var np *pathT
			if p != nil {
				np = p.append(float64(i), e)
			}
			if err := in.recurseDefault(e, np, emit); err != nil {
				return err
			}
		}
	case *Object:
		for i, k := range c.keys {
			e := c.vals[i]
			var np *pathT
			if p != nil {
				np = p.append(k, e)
			}
			if err := in.recurseDefault(e, np, emit); err != nil {
				return err
			}
		}
	}
	return nil
}

// ---- paths ----

func getpath(v Value, path []Value) (Value, error) {
	cur := v
	for _, k := range path {
		if cur == nil {
			// null indexed by anything valid gives null; but invalid key types error
			switch k.(type) {
			case string, float64, *LitNum, *Object:
				cur = nil
				continue
			}
		}
		nv, err := indexValue(cur, k)
		if err != nil {
			return nil, err
		}
		cur = nv
	}
	return cur, nil
}

func setpath(v Value, path []Value, nv Value) (Value, error) {
	if len(path) == 0 {
		return nv, nil
	}
	k := path[0]
	switch kv := k.(type) {
	case string:
		switch t := v.(type) {
		case nil:
			child, err := setpath(nil, path[1:], nv)
			if err != nil {
				return nil, err
			}
			o := NewObject()
			o.SetInPlace(kv, child)
			return o, nil
		case *Object:
			cur, _ := t.Get(kv)
			child, err := setpath(cur, path[1:], nv)
			if err != nil {
				return nil, err
			}
			return t.Set(kv, child), nil
		default:
			return nil, newError("Cannot index %s with string \"%s\"", typeName(v), kv)
		}
	case float64, *LitNum:
		switch t := v.(type) {
		case nil:
			return setArrayIndex(nil, numVal(kv), path[1:], nv)
		case []Value:
			return setArrayIndex(t, numVal(kv), path[1:], nv)
		default:
			return nil, newError("Cannot index %s with number", typeName(v))
		}
	case *Object:
		// slice assignment
		switch t := v.(type) {
		case nil, []Value:
			var arr []Value
			if t != nil {
				arr = t.([]Value)
			}
			start, end, ok := parseSlice(len(arr), kv)
			if !ok {
				return nil, newError("Array/string slice indices must be integers")
			}
			cur := make([]Value, end-start)
			copy(cur, arr[start:end])
			child, err := setpath(cur, path[1:], nv)
			if err != nil {
				return nil, err
			}
			repl, ok := child.([]Value)
			if !ok {
				return nil, newError("A slice of an array can only be assigned another array")
			}
			out := make([]Value, 0, len(arr)-(end-start)+len(repl))
			out = append(out, arr[:start]...)
			out = append(out, repl...)
			out = append(out, arr[end:]...)
			return out, nil
		case string:
			return nil, newError("Cannot update string slices")
		default:
			return nil, newError("Cannot update field at object index of %s", typeName(v))
		}
	}
	switch v.(type) {
	case []Value:
		return nil, newError("Cannot update field at object index of array")
	case *Object:
		return nil, newError("Cannot index object with %s", typeName(k))
	}
	return nil, newError("Invalid path component of type %s", typeName(k))
}

func setArrayIndex(arr []Value, d float64, rest []Value, nv Value) (Value, error) {
	if math.IsNaN(d) {
		return nil, newError("Cannot set array element at NaN index")
	}
	idx := jvArrayIndex(d)
	if idx < 0 {
		idx += len(arr)
		if idx < 0 {
			return nil, newError("Out of bounds negative array index")
		}
	}
	if idx > 536870911 {
		return nil, newError("Array index too large")
	}
	var cur Value
	if idx < len(arr) {
		cur = arr[idx]
	}
	child, err := setpath(cur, rest, nv)
	if err != nil {
		return nil, err
	}
	n := len(arr)
	if idx >= n {
		n = idx + 1
	}
	out := make([]Value, n)
	copy(out, arr)
	out[idx] = child
	return out, nil
}

func delpaths(v Value, paths []Value) (Value, error) {
	ps := make([]Value, len(paths))
	copy(ps, paths)
	sortValues(ps)
	// delete longest/last first
	for i := len(ps) - 1; i >= 0; i-- {
		p, ok := ps[i].([]Value)
		if !ok {
			return nil, newError("Path must be specified as array, not %s", typeName(ps[i]))
		}
		var err error
		v, err = delpath(v, p)
		if err != nil {
			return nil, err
		}
	}
	return v, nil
}

func delpath(v Value, path []Value) (Value, error) {
	if len(path) == 0 {
		return nil, nil
	}
	if v == nil {
		return nil, nil
	}
	k := path[0]
	if len(path) == 1 {
		switch t := v.(type) {
		case *Object:
			ks, ok := k.(string)
			if !ok {
				return nil, newError("Cannot delete field at object index of %s", typeName(k))
			}
			return t.Delete(ks), nil
		case []Value:
			switch kv := k.(type) {
			case float64, *LitNum:
				idx := jvArrayIndex(numVal(kv))
				if idx < 0 {
					idx += len(t)
				}
				if idx < 0 || idx >= len(t) {
					return t, nil
				}
				out := make([]Value, 0, len(t)-1)
				out = append(out, t[:idx]...)
				out = append(out, t[idx+1:]...)
				return out, nil
			case *Object:
				start, end, ok := parseSlice(len(t), kv)
				if !ok {
					return nil, newError("Array/string slice indices must be integers")
				}
				out := make([]Value, 0, len(t)-(end-start))
				out = append(out, t[:start]...)
				out = append(out, t[end:]...)
				return out, nil
			}
			return nil, newError("Cannot delete field at index of %s", typeName(k)) // approximate
		default:
			if ks, ok := k.(string); ok {
				return nil, newError("Cannot delete field at object index of %s", typeName(v)) // placeholder, refined below
			} else {
				_ = ks
			}
			return nil, newError("Cannot delete field at index of %s", typeName(v))
		}
	}
	child, err := indexValue(v, k)
	if err != nil {
		return nil, err
	}
	if child == nil {
		return v, nil
	}
	nchild, err := delpath(child, path[1:])
	if err != nil {
		return nil, err
	}
	return setpath(v, []Value{k}, nchild)
}

// ---- natives ----

type NativeFunc struct {
	Name  string
	Arity int
	// Simple: all args evaluated as values (last arg outermost), returns one value
	Fn func(in *Interp, input Value, args []Value) (Value, error)
	// Gen: full control
	Gen func(in *Interp, env *Frame, input Value, path *pathT, args []Node, emit emitFn) error
}

func (in *Interp) callNative(nf *NativeFunc, args []Node, env *Frame, input Value, path *pathT, emit emitFn) error {
	if nf.Gen != nil {
		return nf.Gen(in, env, input, path, args, emit)
	}
	vals := make([]Value, len(args))
	var rec func(i int) error
	rec = func(i int) error {
		if i < 0 {
			v, err := nf.Fn(in, input, vals)
			if err != nil {
				return err
			}
			return emit(v, path)
		}
		return in.eval(args[i], env, input, nil, func(v Value, _ *pathT) error {
			vals[i] = v
			return rec(i - 1)
		})
	}
	return rec(len(args) - 1)
}

// ---- sorting helpers ----

func sortByKeys(items []Value, keys []Value) []Value {
	idx := make([]int, len(items))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		return compareValues(keys[idx[a]], keys[idx[b]]) < 0
	})
	out := make([]Value, len(items))
	for i, j := range idx {
		out[i] = items[j]
	}
	return out
}
