package main

import (
	"math"
	"strings"
)

func binop(op string, l, r Value) (Value, error) {
	switch op {
	case "+":
		return opAdd(l, r)
	case "-":
		return opSub(l, r)
	case "*":
		return opMul(l, r)
	case "/":
		return opDiv(l, r)
	case "%":
		return opMod(l, r)
	case "==":
		return valuesEqual(l, r), nil
	case "!=":
		return !valuesEqual(l, r), nil
	case "<":
		return compareValues(l, r) < 0, nil
	case ">":
		return compareValues(l, r) > 0, nil
	case "<=":
		return compareValues(l, r) <= 0, nil
	case ">=":
		return compareValues(l, r) >= 0, nil
	}
	return nil, newError("unknown operator %s", op)
}

func opAdd(l, r Value) (Value, error) {
	if l == nil {
		return r, nil
	}
	if r == nil {
		return l, nil
	}
	switch a := l.(type) {
	case float64, *LitNum:
		if isNumber(r) {
			return numVal(a) + numVal(r), nil
		}
	case string:
		if b, ok := r.(string); ok {
			return a + b, nil
		}
	case []Value:
		if b, ok := r.([]Value); ok {
			out := make([]Value, 0, len(a)+len(b))
			out = append(out, a...)
			out = append(out, b...)
			return out, nil
		}
	case *Object:
		if b, ok := r.(*Object); ok {
			n := a.Copy()
			for i, k := range b.keys {
				n.SetInPlace(k, b.vals[i])
			}
			return n, nil
		}
	}
	return nil, typeErr2(l, r, "cannot be added")
}

func opSub(l, r Value) (Value, error) {
	if isNumber(l) && isNumber(r) {
		return numVal(l) - numVal(r), nil
	}
	if a, ok := l.([]Value); ok {
		if b, ok := r.([]Value); ok {
			out := []Value{}
			for _, x := range a {
				found := false
				for _, y := range b {
					if valuesEqual(x, y) {
						found = true
						break
					}
				}
				if !found {
					out = append(out, x)
				}
			}
			return out, nil
		}
	}
	return nil, typeErr2(l, r, "cannot be subtracted")
}

func opMul(l, r Value) (Value, error) {
	if isNumber(l) && isNumber(r) {
		return numVal(l) * numVal(r), nil
	}
	var s string
	var n float64
	isStrNum := false
	if a, ok := l.(string); ok && isNumber(r) {
		s, n, isStrNum = a, numVal(r), true
	} else if b, ok := r.(string); ok && isNumber(l) {
		s, n, isStrNum = b, numVal(l), true
	}
	if isStrNum {
		if math.IsNaN(n) || n < 0 {
			return nil, nil
		}
		if n*float64(len(s)) > 1e9 {
			return nil, newError("Repeat string result too long")
		}
		cnt := int(n)
		if cnt <= 0 {
			return "", nil
		}
		return strings.Repeat(s, cnt), nil
	}
	if a, ok := l.(*Object); ok {
		if b, ok := r.(*Object); ok {
			return deepMerge(a, b), nil
		}
	}
	return nil, typeErr2(l, r, "cannot be multiplied")
}

func deepMerge(a, b *Object) *Object {
	n := a.Copy()
	for i, k := range b.keys {
		bv := b.vals[i]
		if av, ok := n.Get(k); ok {
			ao, aok := av.(*Object)
			bo, bok := bv.(*Object)
			if aok && bok {
				n.SetInPlace(k, deepMerge(ao, bo))
				continue
			}
		}
		n.SetInPlace(k, bv)
	}
	return n
}

func opDiv(l, r Value) (Value, error) {
	if isNumber(l) && isNumber(r) {
		d := numVal(r)
		if d == 0 {
			return nil, typeErr2(l, r, "cannot be divided because the divisor is zero")
		}
		return numVal(l) / d, nil
	}
	if a, ok := l.(string); ok {
		if b, ok := r.(string); ok {
			return splitString(a, b), nil
		}
	}
	return nil, typeErr2(l, r, "cannot be divided")
}

func splitString(s, sep string) Value {
	out := []Value{}
	if s == "" {
		return out
	}
	if sep == "" {
		for _, r := range s {
			out = append(out, string(r))
		}
		return out
	}
	parts := strings.Split(s, sep)
	for _, p := range parts {
		out = append(out, p)
	}
	return out
}

func opMod(l, r Value) (Value, error) {
	if isNumber(l) && isNumber(r) {
