func (c *Compiler) errorf(pos, end int, format string, args ...any) {
	c.errors = append(c.errors, CompileError{Msg: fmt.Sprintf(format, args...), Pos: pos, End: end})
}

// lookupFunc finds a function by name/arity walking up the scope chain.
func (c *Compiler) lookupFunc(sc *scope, name string, arity int) (*resolvedCall, bool) {
	hops := 0
	limit := len(sc.funcs)
	for s := sc; s != nil; s = s.parent {
		n := limit
		if n > len(s.funcs) || n < 0 {
			n = len(s.funcs)
		}
		for i := n - 1; i >= 0; i-- {
			fe := s.funcs[i]
			if fe.name == name && fe.arity == arity {
				kind := callDef
				if fe.def == nil {
					kind = callParam
				} else {
					c.ensureCompiled(fe.def, s, i)
				}
				return &resolvedCall{kind: kind, hops: hops, slot: i}, true
			}
		}
		limit = s.parentLimit
		hops++
	}
	if nf, ok := c.natives[fmt.Sprintf("%s/%d", name, arity)]; ok {
		return &resolvedCall{kind: callNative, native: nf}, true
	}
	return nil, false
}

func (c *Compiler) lookupVar(sc *scope, name string) (*resolvedVar, bool) {
	hops := 0
	for s := sc; s != nil; s = s.parent {
		for i := len(s.vars) - 1; i >= 0; i-- {
			if s.vars[i] == name {
				return &resolvedVar{hops: hops, slot: i}, true
			}
		}
		hops++
	}
	return nil, false
}

// ensureCompiled resolves a def's body (once). defScope is the scope containing the def at index idx.
func (c *Compiler) ensureCompiled(def *FuncDef, defScope *scope, idx int) {
	if def.compiled || def.compiling {
		return
	}
	def.compiling = true
	ps := &scope{parent: defScope, parentLimit: idx + 1}
	for _, p := range def.Params {
		if p[0] == '$' {
			ps.funcs = append(ps.funcs, funcEntry{name: p[1:], arity: 0})
			ps.vars = append(ps.vars, p[1:])
		} else {
			ps.funcs = append(ps.funcs, funcEntry{name: p, arity: 0})
		}
	}
	c.resolve(def.Body, ps)
	def.compiling = false
	def.compiled = true
}

func (c *Compiler) resolve(n Node, sc *scope) {
	switch x := n.(type) {
	case nil:
	case IdentityNode, RecurseNode, *LiteralNode, *LocNode, *FormatNode:
	case *VarNode:
		r, ok := c.lookupVar(sc, x.Name)
		if !ok {
			c.errorf(x.Pos, x.End, "$%s is not defined", x.Name)
			x.res = &resolvedVar{}
			return
		}
		x.res = r
	case *PipeNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *CommaNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *IndexNode:
		c.resolve(x.Target, sc)
		c.resolve(x.Key, sc)
	case *SliceNode:
		c.resolve(x.Target, sc)
		c.resolve(x.From, sc)
		c.resolve(x.To, sc)
	case *EachNode:
		c.resolve(x.Target, sc)
	case *StringNode:
		for _, p := range x.Parts {
			if pn, ok := p.(Node); ok {
				c.resolve(pn, sc)
			}
		}
	case *ArrayNode:
		c.resolve(x.Body, sc)
	case *ObjectNode:
		for i := range x.Entries {
			e := &x.Entries[i]
			if e.KeyIsVar {
				r, ok := c.lookupVar(sc, e.KeyVar)
				if !ok {
					c.errorf(e.KeyPos, e.KeyPos+1+len(e.KeyVar), "$%s is not defined", e.KeyVar)
					r = &resolvedVar{}
				}
				e.keyVarRes = r
			} else if !e.KeyLoc {
				c.resolve(e.Key, sc)
			}
			c.resolve(e.Value, sc)
		}
	case *NegNode:
		c.resolve(x.Body, sc)
	case *BinopNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *AndNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *OrNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *AltNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *AssignNode:
		c.resolve(x.L, sc)
		c.resolve(x.R, sc)
	case *IfNode:
		c.resolve(x.Cond, sc)
		c.resolve(x.Then, sc)
		c.resolve(x.Else, sc)
	case *TryNode:
		c.resolve(x.Body, sc)
		c.resolve(x.Catch, sc)
	case *ReduceNode:
		c.resolve(x.Source, sc)
		c.resolve(x.Init, sc)
		vs := c.patternScope(x.Patterns, sc)
		c.resolve(x.Update, vs)
	case *ForeachNode:
		c.resolve(x.Source, sc)
		c.resolve(x.Init, sc)
		vs := c.patternScope(x.Patterns, sc)
		c.resolve(x.Update, vs)
		c.resolve(x.Extract, vs)
	case *FuncDefNode:
		ds := newScope(sc)
		var rest Node = x
		for {
			fd, ok := rest.(*FuncDefNode)
			if !ok {
				break
			}
			ds.funcs = append(ds.funcs, funcEntry{name: fd.Def.Name, arity: len(fd.Def.Params), def: fd.Def})
			rest = fd.Rest
		}
		c.resolve(rest, ds)
	case *CallNode:
		for _, a := range x.Args {
			c.resolve(a, sc)
		}
		r, ok := c.lookupFunc(sc, x.Name, len(x.Args))
		if !ok {
			c.errorf(x.Pos, x.End, "%s/%d is not defined", x.Name, len(x.Args))
			x.res = &resolvedCall{kind: callNative, native: &NativeFunc{Name: x.Name, Fn: func(in *Interp, input Value, args []Value) (Value, error) { return nil, newError("undefined") }}}
			return
		}
		x.res = r
	case *BindNode:
		c.resolve(x.Source, sc)
		vs := c.patternScope(x.Patterns, sc)
		c.resolve(x.Body, vs)
	case *LabelNode:
		ls := newScope(sc)
		ls.vars = append(ls.vars, "*label-"+x.Name)
		c.resolve(x.Body, ls)
	case *BreakNode:
		r, ok := c.lookupVar(sc, "*label-"+x.Name)
		if !ok {
			c.errorf(x.Pos, x.End, "$*label-%s is not defined", x.Name)
			x.res = &resolvedVar{}
			return
		}
		x.res = r
	default:
		panic(fmt.Sprintf("resolve: unknown node %T", n))
	}
}

// patternScope creates a scope with all variables of the patterns, resolving key expressions.
func (c *Compiler) patternScope(pats []Pattern, sc *scope) *scope {
	vs := newScope(sc)
	slotOf := func(name string) int {
		for i, v := range vs.vars {
			if v == name {
				return i
			}
		}
		vs.vars = append(vs.vars, name)
		return len(vs.vars) - 1
	}
	var walk func(p Pattern)
	walk = func(p Pattern) {
		switch x := p.(type) {
		case *VarPattern:
			x.res = &resolvedVar{hops: 0, slot: slotOf(x.Name)}
		case *ArrayPattern:
			for _, e := range x.Elems {
				walk(e)
			}
		case *ObjectPattern:
			for i := range x.Entries {
				e := &x.Entries[i]
				if e.KeyVar != "" {
					e.KeyVarRes = &resolvedVar{hops: 0, slot: slotOf(e.KeyVar)}
				}
				if e.Key != nil {
					c.resolve(e.Key, vs)
				}
				if e.Val != nil {
					walk(e.Val)
				}
			}
		}
	}
	for _, p := range pats {
		walk(p)
	}
	return vs
}
