		switch x := p.(type) {
		case *VarPattern:
			x.res = &resolvedVar{hops: 0, slot: slotOf(x.Name)}
		case *ArrayPattern:
			for _, e := range x.Elems {
				walk(e)
			}
		case *ObjectPattern:
			for i := range x.Entries {
				e := &x.Entries[i]
				if e.KeyVar != "" {
					e.KeyVarRes = &resolvedVar{hops: 0, slot: slotOf(e.KeyVar)}
				}
				if e.Key != nil {
					c.resolve(e.Key, vs)
				}
				if e.Val != nil {
					walk(e.Val)
				}
			}
		}
	}
	for _, p := range pats {
		walk(p)
	}
	return vs
}
