package main

import (
	"encoding/base64"
	"math"
	"strings"
)

func applyFormat(name string, v Value) (string, error) {
	switch name {
	case "@text":
		return toStringValue(v), nil
	case "@json":
		return toJSON(v), nil
	case "@html":
		s := toStringValue(v)
		var sb strings.Builder
		for i := 0; i < len(s); i++ {
			switch s[i] {
			case '<':
				sb.WriteString("&lt;")
			case '>':
				sb.WriteString("&gt;")
			case '&':
				sb.WriteString("&amp;")
			case '\'':
				sb.WriteString("&apos;")
			case '"':
				sb.WriteString("&quot;")
			default:
				sb.WriteByte(s[i])
			}
		}
		return sb.String(), nil
	case "@uri":
		s := toStringValue(v)
		var sb strings.Builder
		for i := 0; i < len(s); i++ {
			c := s[i]
			if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' {
				sb.WriteByte(c)
			} else {
				sb.WriteByte('%')
				sb.WriteByte("0123456789ABCDEF"[c>>4])
				sb.WriteByte("0123456789ABCDEF"[c&0xf])
			}
		}
		return sb.String(), nil
	case "@urid":
		s := toStringValue(v)
		var sb strings.Builder
		for i := 0; i < len(s); i++ {
			c := s[i]
			if c == '%' {
				if i+2 >= len(s) {
					return "", typeErr(v, "is not a valid uri encoding")
				}
				h, ok := parseHex4([]byte("00" + s[i+1:i+3]))
				if !ok {
					return "", typeErr(v, "is not a valid uri encoding")
				}
				sb.WriteByte(byte(h))
				i += 2
			} else {
				sb.WriteByte(c)
			}
		}
		return sanitizeUTF8(sb.String()), nil
	case "@csv", "@tsv":
		arr, ok := v.([]Value)
		if !ok {
			if name == "@csv" {
				return "", typeErr(v, "cannot be csv-formatted, only array")
			}
			return "", typeErr(v, "cannot be tsv-formatted, only array")
		}
		var sb strings.Builder
		sep := ","
		if name == "@tsv" {
			sep = "\t"
		}
		for i, e := range arr {
			if i > 0 {
				sb.WriteString(sep)
			}
			switch x := e.(type) {
			case nil:
			case bool:
				if x {
					sb.WriteString("true")
				} else {
					sb.WriteString("false")
				}
			case float64, *LitNum:
				if math.IsNaN(numVal(x)) {
					// empty
				} else {
					sb.WriteString(formatNumber(x))
				}
			case string:
				if name == "@csv" {
					sb.WriteByte('"')
					sb.WriteString(strings.ReplaceAll(x, "\"", "\"\""))
					sb.WriteByte('"')
				} else {
					r := strings.NewReplacer("\\", "\\\\", "\t", "\\t", "\n", "\\n", "\r", "\\r")
					sb.WriteString(r.Replace(x))
				}
			default:
				if name == "@csv" {
					return "", typeErr(e, "is not valid in a csv row")
				}
				return "", typeErr(e, "is not valid in a csv row")
			}
		}
		return sb.String(), nil
	case "@sh":
		quote := func(e Value) (string, error) {
			switch x := e.(type) {
			case string:
				s := strings.ReplaceAll(x, "'", "'\\''")
				s = strings.ReplaceAll(s, "\x00", "\\0")
				return "'" + s + "'", nil
			case []Value, *Object:
				return "", typeErr(e, "can not be escaped for shell")
			default:
				return toJSON(e), nil
			}
		}
		if arr, ok := v.([]Value); ok {
			parts := make([]string, len(arr))
			for i, e := range arr {
				q, err := quote(e)
				if err != nil {
					return "", err
				}
				parts[i] = q
			}
			return strings.Join(parts, " "), nil
		}
		return quote(v)
	case "@base64":
		s := toStringValue(v)
		return base64.StdEncoding.EncodeToString([]byte(s)), nil
	case "@base64d":
		s := toStringValue(v)
		return base64Decode(v, s)
	}
	return "", newError("%s is not a valid format", name[1:])
}

func toStringValue(v Value) string {
	if s, ok := v.(string); ok {
		return s
	}
	return toJSON(v)
}

const b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

func base64Decode(v Value, s string) (string, error) {
	// jq decodes ignoring trailing '=' padding; invalid chars -> error
	var out []byte
	var buf uint32
	nbits := 0
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '=' {
			break
		}
		idx := strings.IndexByte(b64chars, c)
		if idx < 0 {
			return "", typeErr(v, "is not valid base64 data")
		}
		buf = (buf << 6) | uint32(idx)
		nbits += 6
		if nbits >= 8 {
			nbits -= 8
			out = append(out, byte(buf>>uint(nbits)))
			buf &= (1 << uint(nbits)) - 1
		}
		i++
	}
	// check trailing: remaining chars must be '='
	for ; i < len(s); i++ {
		if s[i] != '=' {
			return "", typeErr(v, "is not valid base64 data")
		}
	}
	// count of data chars
	n := 0
	for j := 0; j < len(s) && s[j] != '='; j++ {
		n++
	}
	if n%4 == 1 {
		return "", typeErr(v, "trailing base64 byte found")
	}
	return sanitizeUTF8(string(out)), nil
}
