			case nil:
			case bool:
				if x {
					sb.WriteString("true")
				} else {
					sb.WriteString("false")
				}
			case float64, *LitNum:
				if math.IsNaN(numVal(x)) {
					// empty
				} else {
					sb.WriteString(formatNumber(x))
				}
			case string:
