func (in *Interp) keysFor(f Node, env *Frame, input Value) ([]Value, []Value, error) {
	arr, ok := input.([]Value)
	if !ok {
		// produce iterate error
		err := in.iterate(input, nil, false, func(Value, *pathT) error { return nil })
		if err != nil {
			return nil, nil, err
		}
		if o, ok := input.(*Object); ok {
			// map over object values -> then _sort_by_impl requires array: jq errors
			_ = o
			return nil, nil, typeErr2(input, input, "cannot be sorted, as they are not both arrays")
		}
		return nil, nil, typeErr(input, "cannot be sorted, as it is not an array")
	}
	keys := make([]Value, len(arr))
	for i, e := range arr {
		k := []Value{}
		err := in.eval(f, env, e, nil, func(v Value, _ *pathT) error {
			k = append(k, v)
			return nil
		})
		if err != nil {
			return nil, nil, err
		}
		keys[i] = k
	}
	return arr, keys, nil
}

func groupByKeys(arr []Value, keys []Value) []Value {
	idx := make([]int, len(arr))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		return compareValues(keys[idx[a]], keys[idx[b]]) < 0
	})
	out := []Value{}
	var cur []Value
	var curKey Value
	for n, i := range idx {
		if n == 0 || compareValues(curKey, keys[i]) != 0 {
			if cur != nil {
				out = append(out, cur)
			}
			cur = []Value{}
			curKey = keys[i]
		}
		cur = append(cur, arr[i])
	}
	if cur != nil {
		out = append(out, cur)
	}
	return out
}

func minmaxBy(arr []Value, keys []Value, isMin bool) Value {
	if len(arr) == 0 {
		return nil
	}
	ret := arr[0]
	retkey := keys[0]
	for i := 1; i < len(arr); i++ {
		cmp := compareValues(keys[i], retkey)
		if (cmp < 0) == isMin {
			ret = arr[i]
			retkey = keys[i]
		}
	}
	return ret
}

func minmax(input Value, isMin bool) (Value, error) {
	arr, ok := input.([]Value)
	if !ok {
		return nil, typeErr2(input, input, "cannot be iterated over")
	}
	return minmaxBy(arr, arr, isMin), nil
}

func containsValue(a, b Value) (Value, error) {
	ka, kb := kindOf(a), kindOf(b)
	if ka == KindObject && kb == KindObject {
		oa, ob := a.(*Object), b.(*Object)
		for i, k := range ob.keys {
			av, ok := oa.Get(k)
			if !ok {
				return false, nil
			}
			r, err := containsValue(av, ob.vals[i])
			if err != nil {
				return nil, err
			}
			if !truthy(r) {
				return false, nil
			}
		}
		return true, nil
	}
	if ka == KindArray && kb == KindArray {
		aa, ba := a.([]Value), b.([]Value)
		for _, be := range ba {
			found := false
			for _, ae := range aa {
				if kindOf(ae) != kindOf(be) && !(kindOf(ae) == KindTrue && kindOf(be) == KindTrue) {
					// different kinds: compare as equality only if same kind; jv_contains on different kinds -> equal check
					if kindOf(ae) == kindOf(be) {
						continue
					}
				}
				r, err := containsValueNoErr(ae, be)
				if err != nil {
					continue
				}
				if truthy(r) {
