}

func tmToValue(tm brokenDown) Value {
	return []Value{float64(tm.year), float64(tm.mon), float64(tm.mday), float64(tm.hour), float64(tm.min), tm.sec, float64(tm.wday), float64(tm.yday)}
}

func timeToTm(t time.Time, frac float64) brokenDown {
	zone, off := t.Zone()
	return brokenDown{
		year: t.Year(), mon: int(t.Month()) - 1, mday: t.Day(), hour: t.Hour(), min: t.Minute(),
		sec:  float64(t.Second()) + frac,
		wday: int(t.Weekday()), yday: t.YearDay() - 1, zone: zone, gmtoff: off,
	}
}

func fnGmtime(input Value) (Value, error) {
	if !isNumber(input) {
		return nil, newError("gmtime() requires numeric inputs")
	}
	x := numVal(input)
	fl := math.Floor(x)
	t := time.Unix(int64(fl), 0).UTC()
	tm := timeToTm(t, x-fl)
	tm.zone = "GMT"
	return tmToValue(tm), nil
}

func fnLocaltime(input Value) (Value, error) {
	if !isNumber(input) {
		return nil, newError("localtime() requires numeric inputs")
	}
	x := numVal(input)
	fl := math.Floor(x)
	t := time.Unix(int64(fl), 0).In(time.Local)
	return tmToValue(timeToTm(t, x-fl)), nil
}

func valueToTm(v Value, fname string) (brokenDown, error) {
	arr, ok := v.([]Value)
	if !ok {
		return brokenDown{}, newError("%s requires array inputs", fname)
	}
	var tm brokenDown
	get := func(i int) (float64, error) {
		if i >= len(arr) {
			return 0, nil
		}
		if !isNumber(arr[i]) {
			return 0, newError("%s requires parsed datetime inputs", fname)
		}
		return numVal(arr[i]), nil
	}
	var err error
	var f float64
	if f, err = get(0); err != nil {
		return tm, err
	}
	tm.year = int(f)
	if f, err = get(1); err != nil {
		return tm, err
	}
	tm.mon = int(f)
	if f, err = get(2); err != nil {
		return tm, err
	}
	tm.mday = int(f)
	if f, err = get(3); err != nil {
		return tm, err
	}
	tm.hour = int(f)
	if f, err = get(4); err != nil {
		return tm, err
	}
	tm.min = int(f)
	if f, err = get(5); err != nil {
		return tm, err
	}
	tm.sec = f
	if f, err = get(6); err != nil {
		return tm, err
	}
	tm.wday = int(f)
	if f, err = get(7); err != nil {
		return tm, err
	}
	tm.yday = int(f)
	tm.zone = "GMT"
	return tm, nil
}

func tmToTime(tm brokenDown, loc *time.Location) time.Time {
	return time.Date(tm.year, time.Month(tm.mon+1), tm.mday, tm.hour, tm.min, int(math.Floor(tm.sec)), 0, loc)
}

func fnMktime(input Value) (Value, error) {
	tm, err := valueToTm(input, "mktime")
	if err != nil {
		return nil, err
	}
	t := tmToTime(tm, time.UTC)
	return float64(t.Unix()), nil
}

func fnStrftime(input Value, fmtV Value, local bool) (Value, error) {
	var tm brokenDown
	if isNumber(input) {
		var v Value
		var err error
		if local {
			v, err = fnLocaltime(input)
		} else {
			v, err = fnGmtime(input)
		}
		if err != nil {
			return nil, err
		}
		tm, _ = valueToTm(v, "strftime/1")
		if local {
			x := numVal(input)
			t := time.Unix(int64(math.Floor(x)), 0).In(time.Local)
			tm.zone, tm.gmtoff = t.Zone()
		}
	} else if _, ok := input.([]Value); ok {
		var err error
		tm, err = valueToTm(input, "strftime/1")
		if err != nil {
			return nil, newError("strftime/1 requires parsed datetime inputs")
		}
		if local {
			t := tmToTime(tm, time.Local)
			tm.zone, tm.gmtoff = t.Zone()
		}
	} else {
		return nil, newError("strftime/1 requires parsed datetime inputs")
	}
	f, ok := fmtV.(string)
	if !ok {
		return nil, newError("strftime/1 requires a string format")
	}
	return strftime(f, tm), nil
}

var weekdayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}

func isLeap(y int) bool { return y%4 == 0 && (y%100 != 0 || y%400 == 0) }

var monYday = [2][13]int{
	{0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365},
	{0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335, 366},
}

func pad(n int, width int, padc byte) string {
	s := strconv.Itoa(n)
	neg := false
	if n < 0 {
		neg = true
		s = s[1:]
	}
	for len(s) < width {
		s = string(padc) + s
	}
	if neg {
		return "-" + s
	}
	return s
}

func isoWeek(tm brokenDown) (int, int) {
	// ISO 8601 week number and year
	wday := (tm.wday + 6) % 7 // Monday=0
	yday := tm.yday
	year := tm.year
	// week number
	w := (yday - wday + 10) / 7
	if w < 1 {
		year--
		// weeks in previous year
		pyday := yday + 365
		if isLeap(year) {
			pyday++
		}
		w = (pyday - wday + 10) / 7
	} else if w == 53 {
		// check if belongs to next year
		daysInYear := 365
		if isLeap(year) {
			daysInYear = 366
		}
		if yday-wday+3 >= daysInYear {
			w = 1
			year++
		}
	}
	return year, w
}

func strftime(f string, tm brokenDown) string {
	var sb strings.Builder
	sec := int(math.Floor(tm.sec))
	wd := tm.wday
	if wd < 0 || wd > 6 {
		wd = ((wd % 7) + 7) % 7
	}
	mon := tm.mon
	if mon < 0 || mon > 11 {
		mon = ((mon % 12) + 12) % 12
	}
	hour12 := tm.hour % 12
	if hour12 == 0 {
		hour12 = 12
	}
	var epoch int64
	epochComputed := false
	for i := 0; i < len(f); i++ {
		c := f[i]
		if c != '%' || i+1 >= len(f) {
			sb.WriteByte(c)
			continue
		}
		i++
		// skip flags/modifiers E and O
		for i < len(f) && (f[i] == 'E' || f[i] == 'O' || f[i] == '-' || f[i] == '_' || f[i] == '0' || f[i] == '^' || f[i] == '#') {
			if f[i] == 'E' || f[i] == 'O' {
				// glibc: %E followed by unknown -> literal
				if i+1 < len(f) && strings.IndexByte("cCxXyYdeHImMSuUVwWy", f[i+1]) >= 0 {
					i++
					continue
				}
				sb.WriteByte('%')
				sb.WriteByte(f[i])
				goto next
			}
			i++
		}
		if i >= len(f) {
			sb.WriteByte('%')
			break
		}
		switch f[i] {
		case 'a':
			sb.WriteString(weekdayNames[wd][:3])
		case 'A':
			sb.WriteString(weekdayNames[wd])
		case 'b', 'h':
			sb.WriteString(monthNames[mon][:3])
		case 'B':
			sb.WriteString(monthNames[mon])
		case 'c':
			sb.WriteString(fmt.Sprintf("%s %s %2d %02d:%02d:%02d %d", weekdayNames[wd][:3], monthNames[mon][:3], tm.mday, tm.hour, tm.min, sec, tm.year))
		case 'C':
			sb.WriteString(pad(tm.year/100, 2, '0'))
		case 'd':
			sb.WriteString(pad(tm.mday, 2, '0'))
		case 'D':
			sb.WriteString(fmt.Sprintf("%02d/%02d/%02d", mon+1, tm.mday, ((tm.year%100)+100)%100))
		case 'e':
			sb.WriteString(pad(tm.mday, 2, ' '))
		case 'F':
			sb.WriteString(fmt.Sprintf("%d-%02d-%02d", tm.year, mon+1, tm.mday))
		case 'g':
			y, _ := isoWeek(tm)
			sb.WriteString(pad(((y%100)+100)%100, 2, '0'))
		case 'G':
			y, _ := isoWeek(tm)
			sb.WriteString(strconv.Itoa(y))
		case 'H':
			sb.WriteString(pad(tm.hour, 2, '0'))
		case 'I':
			sb.WriteString(pad(hour12, 2, '0'))
		case 'j':
			sb.WriteString(pad(tm.yday+1, 3, '0'))
		case 'k':
			sb.WriteString(pad(tm.hour, 2, ' '))
		case 'l':
			sb.WriteString(pad(hour12, 2, ' '))
		case 'm':
			sb.WriteString(pad(mon+1, 2, '0'))
		case 'M':
			sb.WriteString(pad(tm.min, 2, '0'))
		case 'n':
			sb.WriteByte('\n')
		case 'p':
			if tm.hour >= 12 {
				sb.WriteString("PM")
			} else {
				sb.WriteString("AM")
			}
		case 'P':
			if tm.hour >= 12 {
				sb.WriteString("pm")
			} else {
				sb.WriteString("am")
			}
		case 'r':
			ampm := "AM"
			if tm.hour >= 12 {
				ampm = "PM"
			}
			sb.WriteString(fmt.Sprintf("%02d:%02d:%02d %s", hour12, tm.min, sec, ampm))
		case 'R':
			sb.WriteString(fmt.Sprintf("%02d:%02d", tm.hour, tm.min))
		case 's':
			if !epochComputed {
				epoch = tmToTime(tm, time.UTC).Unix() - int64(tm.gmtoff)
				epochComputed = true
			}
			sb.WriteString(strconv.FormatInt(epoch, 10))
		case 'S':
			sb.WriteString(pad(sec, 2, '0'))
		case 't':
			sb.WriteByte('\t')
		case 'T':
			sb.WriteString(fmt.Sprintf("%02d:%02d:%02d", tm.hour, tm.min, sec))
		case 'u':
			u := wd
			if u == 0 {
				u = 7
			}
			sb.WriteString(strconv.Itoa(u))
		case 'U':
			sb.WriteString(pad((tm.yday+7-wd)/7, 2, '0'))
		case 'V':
			_, w := isoWeek(tm)
			sb.WriteString(pad(w, 2, '0'))
		case 'w':
			sb.WriteString(strconv.Itoa(wd))
		case 'W':
			sb.WriteString(pad((tm.yday+7-((wd+6)%7))/7, 2, '0'))
		case 'x':
			sb.WriteString(fmt.Sprintf("%02d/%02d/%02d", mon+1, tm.mday, ((tm.year%100)+100)%100))
		case 'X':
			sb.WriteString(fmt.Sprintf("%02d:%02d:%02d", tm.hour, tm.min, sec))
		case 'y':
			sb.WriteString(pad(((tm.year%100)+100)%100, 2, '0'))
		case 'Y':
			sb.WriteString(strconv.Itoa(tm.year))
		case 'z':
			off := tm.gmtoff
			sign := '+'
			if off < 0 {
				sign = '-'
				off = -off
			}
			sb.WriteString(fmt.Sprintf("%c%02d%02d", sign, off/3600, (off%3600)/60))
		case 'Z':
			sb.WriteString(tm.zone)
		case '%':
			sb.WriteByte('%')
		case '+':
			sb.WriteString(fmt.Sprintf("%s %s %2d %02d:%02d:%02d %s %d", weekdayNames[wd][:3], monthNames[mon][:3], tm.mday, tm.hour, tm.min, sec, tm.zone, tm.year))
		default:
			sb.WriteByte('%')
			sb.WriteByte(f[i])
		}
	next:
	}
	return sb.String()
}

// ---- strptime (glibc-like) ----

type strptimeState struct {
	haveWday, haveYday, haveMon, haveMday, wantXday, haveI, isPM bool
	century                                                      int
	wantCentury                                                  bool
	haveUweek, haveWweek                                         bool
	weekNo                                                       int
}

func fnStrptime(input Value, fmtV Value) (Value, error) {
	s, ok1 := input.(string)
	f, ok2 := fmtV.(string)
	if !ok1 || !ok2 {
		return nil, newError("strptime/1 requires string inputs and arguments")
	}
	tm := brokenDown{wday: 8, yday: 367, year: 1900}
	st := &strptimeState{century: -1}
	rest, ok := strptimeParse(s, f, &tm, st)
	if !ok || (rest != "" && !isCSpace(rest[0])) {
		return nil, newError("date \"%s\" does not match format \"%s\"", s, f)
	}
	// glibc post-processing
	if st.haveI && st.isPM {
		tm.hour += 12
	}
	if st.century != -1 {
		if st.wantCentury {
			tm.year = tm.year%100 + (st.century-19)*100 + 1900 - 1900
			tm.year = (tm.year+1900)%100 + st.century*100
		} else {
			tm.year = st.century*100 + ((tm.year % 100) + 100) % 100
		}
	}
	if st.wantXday && !st.haveWday {
		if !(st.haveMon && st.haveMday) && st.haveYday {
			tMon := 0
			leap := 0
			if isLeap(tm.year) {
				leap = 1
			}
			for tMon < 12 && monYday[leap][tMon] <= tm.yday {
				tMon++
			}
			if !st.haveMon {
				tm.mon = tMon - 1
			}
			if !st.haveMday {
				tm.mday = tm.yday - monYday[leap][tMon-1] + 1
			}
			st.haveMon = true
			st.haveMday = true
		}
		if st.haveMon || (tm.mon >= 0 && tm.mon <= 11) {
			tm.wday = dayOfTheWeek(tm.year, tm.mon, tm.mday)
		}
	}
	if st.wantXday && !st.haveYday && (st.haveMon || (tm.mon >= 0 && tm.mon <= 11)) {
		tm.yday = dayOfTheYear(tm.year, tm.mon, tm.mday)
	}
	// jq's own fixups
	if tm.wday == 8 && tm.mday >= 1 && tm.mday <= 31 {
		tm.wday = dayOfTheWeek(tm.year, tm.mon, tm.mday)
	}
	if tm.yday == 367 && tm.mday >= 1 && tm.mday <= 31 {
		tm.yday = dayOfTheYear(tm.year, tm.mon, tm.mday)
	}
	r := tmToValue(tm).([]Value)
	if rest != "" {
		r = append(r, rest)
	}
	return r, nil
}

func isCSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r'
}

func dayOfTheWeek(year, mon, mday int) int {
	// glibc day_of_the_week: uses tm_year (years since 1900)
	y := year - 1900
	corrYear := 1900 + y - boolToInt(mon < 2)
	wday := (-473 + (365 * (y - 70)) + (corrYear / 4) - ((corrYear/4)/25) + ((corrYear/4)%25 < 0) + (((corrYear / 4) / 25) / 4) + monYday[0][mon] + mday - 1)
	return ((wday % 7) + 7) % 7
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func dayOfTheYear(year, mon, mday int) int {
	leap := 0
	if isLeap(year) {
		leap = 1
	}
	m := mon
	if m < 0 {
		m = 0
	}
	if m > 11 {
		m = 11
	}
	return monYday[leap][m] + mday - 1
}

// strptimeParse parses input according to format. Returns remaining input and success.
func strptimeParse(s, f string, tm *brokenDown, st *strptimeState) (string, bool) {
	rp := s
	for i := 0; i < len(f); i++ {
		c := f[i]
		if isCSpace(c) {
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
			continue
		}
		if c != '%' {
			if rp == "" || rp[0] != c {
				return rp, false
			}
			rp = rp[1:]
			continue
		}
		i++
		if i >= len(f) {
			return rp, false
		}
		// skip E/O modifiers
		for i < len(f) && (f[i] == 'E' || f[i] == 'O') {
			i++
		}
		if i >= len(f) {
			return rp, false
		}
		getNum := func(lo, hi, maxDigits int) (int, bool) {
			for rp != "" && rp[0] == ' ' {
				rp = rp[1:]
			}
			if rp == "" || rp[0] < '0' || rp[0] > '9' {
				return 0, false
			}
			val := 0
			n := 0
			for rp != "" && n < maxDigits && rp[0] >= '0' && rp[0] <= '9' {
				val = val*10 + int(rp[0]-'0')
				rp = rp[1:]
				n++
			}
			if val < lo || val > hi {
				return 0, false
			}
			return val, true
		}
		matchName := func(names []string, abbrevOK bool) (int, bool) {
			for idx, name := range names {
				if len(rp) >= len(name) && strings.EqualFold(rp[:len(name)], name) {
					rp = rp[len(name):]
					return idx, true
				}
			}
			if abbrevOK {
				for idx, name := range names {
					ab := name[:3]
					if len(rp) >= 3 && strings.EqualFold(rp[:3], ab) {
						rp = rp[3:]
						return idx, true
					}
				}
			}
			return 0, false
		}
		switch f[i] {
		case '%':
			if rp == "" || rp[0] != '%' {
				return rp, false
			}
			rp = rp[1:]
		case 'a', 'A':
			idx, ok := matchName(weekdayNames, true)
			if !ok {
				return rp, false
			}
			tm.wday = idx
			st.haveWday = true
		case 'b', 'B', 'h':
			idx, ok := matchName(monthNames, true)
			if !ok {
				return rp, false
			}
			tm.mon = idx
			st.haveMon = true
			st.wantXday = true
		case 'c':
			var ok bool
			rp, ok = strptimeParse(rp, "%a %b %e %H:%M:%S %Y", tm, st)
			if !ok {
				return rp, false
			}
		case 'C':
			v, ok := getNum(0, 99, 2)
			if !ok {
				return rp, false
			}
			st.century = v
			st.wantXday = true
		case 'd', 'e':
			v, ok := getNum(1, 31, 2)
			if !ok {
				return rp, false
			}
			tm.mday = v
			st.haveMday = true
			st.wantXday = true
		case 'F':
			var ok bool
			rp, ok = strptimeParse(rp, "%Y-%m-%d", tm, st)
			if !ok {
				return rp, false
			}
			st.wantXday = true
		case 'D', 'x':
			var ok bool
			rp, ok = strptimeParse(rp, "%m/%d/%y", tm, st)
			if !ok {
				return rp, false
			}
			st.wantXday = true
		case 'k', 'H':
			v, ok := getNum(0, 23, 2)
			if !ok {
				return rp, false
			}
			tm.hour = v
			st.haveI = false
		case 'l', 'I':
			v, ok := getNum(1, 12, 2)
			if !ok {
				return rp, false
			}
			tm.hour = v % 12
			st.haveI = true
		case 'j':
			v, ok := getNum(1, 366, 3)
			if !ok {
				return rp, false
			}
			tm.yday = v - 1
			st.haveYday = true
		case 'm':
			v, ok := getNum(1, 12, 2)
			if !ok {
				return rp, false
			}
			tm.mon = v - 1
			st.haveMon = true
			st.wantXday = true
		case 'M':
			v, ok := getNum(0, 59, 2)
			if !ok {
				return rp, false
			}
			tm.min = v
		case 'n', 't':
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
		case 'p', 'P':
			if len(rp) >= 2 && strings.EqualFold(rp[:2], "AM") {
				st.isPM = false
				rp = rp[2:]
			} else if len(rp) >= 2 && strings.EqualFold(rp[:2], "PM") {
				st.isPM = true
				rp = rp[2:]
			} else {
				return rp, false
			}
		case 'r':
			var ok bool
			rp, ok = strptimeParse(rp, "%I:%M:%S %p", tm, st)
			if !ok {
				return rp, false
			}
		case 'R':
			var ok bool
			rp, ok = strptimeParse(rp, "%H:%M", tm, st)
			if !ok {
				return rp, false
			}
		case 's':
			neg := false
			if rp != "" && rp[0] == '-' {
				neg = true
				rp = rp[1:]
			}
			if rp == "" || rp[0] < '0' || rp[0] > '9' {
				return rp, false
			}
			var secs int64
			for rp != "" && rp[0] >= '0' && rp[0] <= '9' {
				secs = secs*10 + int64(rp[0]-'0')
				rp = rp[1:]
			}
			if neg {
				secs = -secs
			}
			t := time.Unix(secs, 0).In(time.Local)
			*tm = timeToTm(t, 0)
			st.haveWday = true
			st.haveYday = true
			st.haveMon = true
			st.haveMday = true
		case 'S':
			v, ok := getNum(0, 61, 2)
			if !ok {
				return rp, false
			}
			tm.sec = float64(v)
		case 'T', 'X':
			var ok bool
			rp, ok = strptimeParse(rp, "%H:%M:%S", tm, st)
			if !ok {
				return rp, false
			}
		case 'u':
			v, ok := getNum(1, 7, 1)
			if !ok {
				return rp, false
			}
			tm.wday = v % 7
			st.haveWday = true
		case 'g':
			_, ok := getNum(0, 99, 2)
			if !ok {
				return rp, false
			}
		case 'G':
			_, ok := getNum(0, 9999, 4)
			if !ok {
				return rp, false
			}
		case 'U', 'W', 'V':
			v, ok := getNum(0, 53, 2)
			if !ok {
				return rp, false
			}
			st.weekNo = v
			if f[i] == 'U' {
				st.haveUweek = true
			} else if f[i] == 'W' {
				st.haveWweek = true
			}
		case 'w':
			v, ok := getNum(0, 6, 1)
			if !ok {
				return rp, false
			}
			tm.wday = v
			st.haveWday = true
		case 'y':
			v, ok := getNum(0, 99, 2)
			if !ok {
				return rp, false
			}
			if v >= 69 {
				tm.year = 1900 + v
			} else {
				tm.year = 2000 + v
			}
			st.wantCentury = true
			st.wantXday = true
		case 'Y':
			v, ok := getNum(0, 9999, 4)
			if !ok {
				return rp, false
			}
			tm.year = v
			st.wantCentury = false
			st.wantXday = true
		case 'Z':
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
			for rp != "" && !isCSpace(rp[0]) {
				rp = rp[1:]
			}
		case 'z':
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
			if rp != "" && rp[0] == 'Z' {
				rp = rp[1:]
				tm.gmtoff = 0
				break
			}
			if rp == "" || (rp[0] != '+' && rp[0] != '-') {
				return rp, false
			}
			neg := rp[0] == '-'
			rp = rp[1:]
			n := 0
			val := 0
			for n < 4 && rp != "" && rp[0] >= '0' && rp[0] <= '9' {
				val = val*10 + int(rp[0]-'0')
				rp = rp[1:]
				n++
				if n == 2 && rp != "" && rp[0] == ':' {
					rp = rp[1:]
				}
			}
			if n == 2 {
				val *= 100
			} else if n != 4 {
				return rp, false
			}
			if val%100 >= 60 || val/100 >= 25 {
				return rp, false
			}
			off := (val/100)*3600 + (val%100)*60
			if neg {
				off = -off
			}
			tm.gmtoff = off
		default:
			return rp, false
		}
	}
	return rp, true
}
