				tm.year = 1900 + v
			} else {
				tm.year = 2000 + v
			}
			st.wantCentury = true
			st.wantXday = true
		case 'Y':
			v, ok := getNum(0, 9999, 4)
			if !ok {
				return rp, false
			}
			tm.year = v
			st.wantCentury = false
			st.wantXday = true
		case 'Z':
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
			for rp != "" && !isCSpace(rp[0]) {
				rp = rp[1:]
			}
		case 'z':
			for rp != "" && isCSpace(rp[0]) {
				rp = rp[1:]
			}
			if rp != "" && rp[0] == 'Z' {
				rp = rp[1:]
				tm.gmtoff = 0
				break
			}
			if rp == "" || (rp[0] != '+' && rp[0] != '-') {
				return rp, false
			}
			neg := rp[0] == '-'
			rp = rp[1:]
			n := 0
			val := 0
			for n < 4 && rp != "" && rp[0] >= '0' && rp[0] <= '9' {
				val = val*10 + int(rp[0]-'0')
				rp = rp[1:]
				n++
				if n == 2 && rp != "" && rp[0] == ':' {
					rp = rp[1:]
				}
			}
			if n == 2 {
				val *= 100
			} else if n != 4 {
				return rp, false
			}
			if val%100 >= 60 || val/100 >= 25 {
				return rp, false
			}
			off := (val/100)*3600 + (val%100)*60
			if neg {
				off = -off
			}
			tm.gmtoff = off
		default:
			return rp, false
		}
	}
	return rp, true
}
