{"command":"cd /workspace && cat > regex.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// ---- regex AST ----

type reNode interface{}

type (
	reLit      struct{ r rune; fold bool }
	reAny      struct{ dotall bool }
	reClass    struct{ set *charSet; fold bool }
	reStart    struct{ multiline bool } // ^
	reEnd      struct{ multiline bool } // $
	reBufStart struct{}                 // \A
	reBufEnd   struct{}                 // \z
	reBufEndNL struct{}                 // \Z
	reWordB    struct{ neg bool }
	reGroup    struct {
		idx  int // capture index (1-based), 0 = non-capturing
		body reNode
	}
	reConcat struct{ items []reNode }
	reAlt    struct{ alts []reNode }
	reRepeat struct {
		body               reNode
		min, max           int // max -1 = inf
		greedy, possessive bool
	}
	reBackref struct {
		idx  int
		name string
		fold bool
	}
	reLook struct {
		body   reNode
		neg    bool
		behind bool
	}
	reAtomic struct{ body reNode }
	reEmpty  struct{}
	reKeep   struct{}
	reLineBreak struct{}
)

type charSet struct {
	neg    bool
	ranges []rune // pairs
	fns    []func(rune) bool
	negFns []func(rune) bool
}

func (cs *charSet) matches(r rune, fold bool) bool {
	m := cs.matchRaw(r)
	if !m && fold {
		for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
			if cs.matchRaw(f) {
				m = true
				break
			}
		}
	}
	if cs.neg {
		return !m
	}
	return m
}

func (cs *charSet) matchRaw(r rune) bool {
	for i := 0; i+1 < len(cs.ranges); i += 2 {
		if r >= cs.ranges[i] && r <= cs.ranges[i+1] {
			return true
		}
	}
	for _, f := range cs.fns {
		if f(r) {
			return true
		}
	}
	for _, f := range cs.negFns {
		if !f(r) {
			return true
		}
	}
	return false
}

// ---- compiled regex ----

type Regex struct {
	root       reNode
	ncap       int
	names      []string // index -> name ("" if unnamed), 1-based (names[0] unused)
	nameToIdx  map[string][]int
	ignoreCase bool
	findLongest bool
	notEmpty   bool
}

type regexError struct{ msg string }

func (e *regexError) Error() string { return e.msg }

type reParser struct {
	src      []rune
	pos      int
	ncap     int
	names    []string
	nameIdx  map[string][]int
	flagI    bool
	flagX    bool
	flagS    bool // dotall
	flagM    bool // multiline anchors
	backrefs []*reBackref
}

func (p *reParser) fail(msg string) {
	panic(&regexError{msg})
}

func compileRegex(pattern string, flags string) (re *Regex, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*regexError); ok {
				re = nil
				err = e
				return
			}
			panic(r)
		}
	}()
	p := &reParser{src: []rune(pattern), nameIdx: map[string][]int{}}
	p.names = []string{""}
	re = &Regex{}
	for _, f := range flags {
		switch f {
		case 'g':
		case 'i':
			p.flagI = true
			re.ignoreCase = true
		case 'x':
			p.flagX = true
		case 'n':
			re.notEmpty = true
		case 'p':
			p.flagS = true
		case 's':
		case 'l':
			re.findLongest = true
		default:
			return nil, &regexError{fmt.Sprintf("%s is not a valid modifier string", flags)}
		}
	}
	root := p.parseAlt()
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			p.fail("unmatched close parenthesis")
		}
		p.fail("invalid pattern")
	}
	// resolve named backrefs
	for _, b := range p.backrefs {
		if b.name != "" {
			idxs, ok := p.nameIdx[b.name]
			if !ok {
				p.fail(fmt.Sprintf("undefined name <%s> reference", b.name))
			}
			b.idx = idxs[len(idxs)-1]
		} else if b.idx > p.ncap {
			p.fail("invalid backref number/name")
		}
	}
	re.root = root
	re.ncap = p.ncap
	re.names = p.names
	re.nameToIdx = p.nameIdx
	return re, nil
}

func (p *reParser) more() bool { return p.pos < len(p.src) }
func (p *reParser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}
func (p *reParser) next() rune {
	r := p.src[p.pos]
	p.pos++
	return r
}

func (p *reParser) skipExtended() {
	if !p.flagX {
		return
	}
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
		} else if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
		} else {
			break
		}
	}
}

func (p *reParser) parseAlt() reNode {
	var alts []reNode
	alts = append(alts, p.parseConcat())
	for p.more() && p.peek() == '|' {
		p.pos++
		alts = append(alts, p.parseConcat())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reAlt{alts: alts}
}

func (p *reParser) parseConcat() reNode {
	var items []reNode
	for {
		p.skipExtended()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuantifiers(atom)
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0]
	}
	return &reConcat{items: items}
}

func (p *reParser) parseQuantifiers(atom reNode) reNode {
	for {
		p.skipExtended()
		if !p.more() {
			return atom
		}
		c := p.peek()
		var min, max int
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			save := p.pos
			p.pos++
			n1, ok1 := p.parseInt()
			if !ok1 {
				p.pos = save
				return atom
			}
			if p.peek() == '}' {
				p.pos++
				min, max = n1, n1
			} else if p.peek() == ',' {
				p.pos++
				n2, ok2 := p.parseInt()
				if p.peek() != '}' {
					p.pos = save
					return atom
				}
				p.pos++
				if ok2 {
					min, max = n1, n2
					if max < min {
						p.fail("upper is smaller than lower in repeat range")
					}
				} else {
					min, max = n1, -1
				}
			} else {
				p.pos = save
				return atom
			}
		default:
			return atom
		}
		greedy, possessive := true, false
		if p.more() && p.peek() == '?' {
			greedy = false
			p.pos++
		} else if p.more() && p.peek() == '+' && c != '{' {
			possessive = true
			p.pos++
		}
		if _, isAnchor := atom.(*reStart); isAnchor {
			p.fail("target of repeat operator is invalid")
		}
		atom = &reRepeat{body: atom, min: min, max: max, greedy: greedy, possessive: possessive}
	}
}

func (p *reParser) parseInt() (int, bool) {
	start := p.pos
	v := 0
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		v = v*10 + int(p.next()-'0')
		if v > 100000 {
			p.fail("too big number for repeat range")
		}
	}
	if p.pos == start {
		return 0, false
	}
	return v, true
}

func (p *reParser) parseAtom() reNode {
	c := p.next()
	switch c {
	case '(':
		return p.parseGroup()
	case ')':
		p.fail("unmatched close parenthesis")
	case '[':
		return &reClass{set: p.parseClass(), fold: p.flagI}
	case '.':
		return &reAny{dotall: p.flagS}
	case '^':
		return &reStart{multiline: p.flagM}
	case '$':
		return &reEnd{multiline: p.flagM}
	case '*', '+', '?':
		p.fail("target of repeat operator is not specified")
	case '{':
		// literal unless valid quantifier (which would have been consumed)
		return &reLit{r: c, fold: p.flagI}
	case '\\':
		return p.parseEscape(false)
	}
	return &reLit{r: c, fold: p.flagI}
}

func (p *reParser) parseGroup() reNode {
	if !p.more() {
		p.fail("end pattern with unmatched parenthesis")
	}
	if p.peek() == '?' {
		p.pos++
		if !p.more() {
			p.fail("end pattern in group")
		}
		c := p.next()
		switch c {
		case ':':
			body := p.parseAltUntilClose()
			return &reGroup{idx: 0, body: body}
		case '=', '!':
			body := p.parseAltUntilClose()
			return &reLook{body: body, neg: c == '!'}
		case '>':
			body := p.parseAltUntilClose()
			return &reAtomic{body: body}
		case '#':
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			if !p.more() {
				p.fail("end pattern in group")
			}
			p.pos++
			return nil
		case '<':
			if !p.more() {
				p.fail("end pattern with unmatched parenthesis")
			}
			if p.peek() == '=' || p.peek() == '!' {
				neg := p.next() == '!'
				body := p.parseAltUntilClose()
				return &reLook{body: body, neg: neg, behind: true}
			}
			name := p.parseName('>')
			return p.captureGroup(name)
		case '\'':
			name := p.parseName('\'')
			return p.captureGroup(name)
		case 'P':
			if p.more() && p.peek() == '<' {
				p.pos++
				name := p.parseName('>')
				return p.captureGroup(name)
			}
			p.fail("undefined group option")
		default:
			// option flags (?imsx-imsx) or (?imsx-imsx:...)
			p.pos--
			saveI, saveX, saveS, saveM := p.flagI, p.flagX, p.flagS, p.flagM
			neg := false
			for p.more() {
				o := p.next()
				switch o {
				case 'i':
					p.flagI = !neg
				case 'x':
					p.flagX = !neg
				case 's':
					p.flagS = !neg
				case 'm':
					p.flagM = !neg
				case '-':
					neg = true
				case ')':
					// applies to the rest of the enclosing group
					return nil
				case ':':
					body := p.parseAltUntilClose()
					p.flagI, p.flagX, p.flagS, p.flagM = saveI, saveX, saveS, saveM
					return &reGroup{idx: 0, body: body}
				default:
					p.fail("undefined group option")
				}
			}
			p.fail("end pattern in group")
		}
	}
	return p.captureGroup("")
}

func (p *reParser) captureGroup(name string) reNode {
	p.ncap++
	idx := p.ncap
	p.names = append(p.names, name)
	if name != "" {
		p.nameIdx[name] = append(p.nameIdx[name], idx)
	}
	body := p.parseAltUntilClose()
	return &reGroup{idx: idx, body: body}
}

func (p *reParser) parseName(end rune) string {
	var sb strings.Builder
	for {
		if !p.more() {
			p.fail("invalid group name <>")
		}
		c := p.next()
		if c == end {
			break
		}
		sb.WriteRune(c)
	}
	name := sb.String()
	if name == "" {
		p.fail("group name is empty")
	}
	return name
}

func (p *reParser) parseAltUntilClose() reNode {
	saveI, saveX, saveS, saveM := p.flagI, p.flagX, p.flagS, p.flagM
	body := p.parseAlt()
	if !p.more() || p.peek() != ')' {
		p.fail("end pattern with unmatched parenthesis")
	}
	p.pos++
	p.flagI, p.flagX, p.flagS, p.flagM = saveI, saveX, saveS, saveM
	return body
}

func (p *reParser) parseHex(maxDigits int) (rune, bool) {
	v := 0
	n := 0
	for n < maxDigits && p.more() {
		c := p.peek()
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			goto done
		}
		v = v*16 + d
		p.pos++
		n++
	}
done:
	if n == 0 {
		return 0, false
	}
	return rune(v), true
}

// parseEscape parses after a backslash. inClass indicates inside [...].
func (p *reParser) parseEscape(inClass bool) reNode {
	if !p.more() {
		p.fail("end pattern at escape")
	}
	c := p.next()
	switch c {
	case 't':
		return &reLit{r: '\t', fold: p.flagI}
	case 'n':
		return &reLit{r: '\n', fold: p.flagI}
	case 'r':
		return &reLit{r: '\r', fold: p.flagI}
	case 'f':
		return &reLit{r: '\f', fold: p.flagI}
	case 'v':
		return &reLit{r: '\v', fold: p.flagI}
	case 'a':
		return &reLit{r: 7, fold: p.flagI}
	case 'e':
		return &reLit{r: 27, fold: p.flagI}
	case 'x':
		if p.more() && p.peek() == '{' {
			p.pos++
			v, ok := p.parseHex(8)
			if !ok || !p.more() || p.peek() != '}' {
				p.fail("invalid code point value")
			}
			p.pos++
			return &reLit{r: v, fold: p.flagI}
		}
		v, ok := p.parseHex(2)
		if !ok {
			return &reLit{r: 0, fold: p.flagI}
		}
		return &reLit{r: v, fold: p.flagI}
	case '0':
		v := 0
		n := 0
		for n < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.next()-'0')
			n++
		}
		return &reLit{r: rune(v), fold: p.flagI}
	case 'd':
		return &reClass{set: &charSet{fns: []func(rune) bool{unicode.IsDigit}}}
	case 'D':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{unicode.IsDigit}}}
	case 'w':
		return &reClass{set: &charSet{fns: []func(rune) bool{isWordRune}}}
	case 'W':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{isWordRune}}}
	case 's':
		return &reClass{set: &charSet{fns: []func(rune) bool{unicode.IsSpace}}}
	case 'S':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{unicode.IsSpace}}}
	case 'p', 'P':
		neg := c == 'P'
		if !p.more() || p.peek() != '{' {
			p.fail("invalid character property name {}")
		}
		p.pos++
		var sb strings.Builder
		for p.more() && p.peek() != '}' {
			sb.WriteRune(p.next())
		}
		if !p.more() {
			p.fail("invalid character property name {" + sb.String() + "}")
		}
		p.pos++
		name := sb.String()
		if strings.HasPrefix(name, "^") {
			neg = !neg
			name = name[1:]
		}
		fn := propertyFunc(name)
		if fn == nil {
			p.fail("invalid character property name {" + sb.String() + "}")
		}
		return &reClass{set: &charSet{neg: neg, fns: []func(rune) bool{fn}}}
	}
	if inClass {
		if c == 'b' {
			return &reLit{r: '\b'}
		}
		return &reLit{r: c}
	}
	switch c {
	case 'b':
		return &reWordB{}
	case 'B':
		return &reWordB{neg: true}
	case 'A':
		return &reBufStart{}
	case 'z':
		return &reBufEnd{}
	case 'Z':
		return &reBufEndNL{}
	case 'G':
		return &reBufStart{}
	case 'K':
		return &reKeep{}
	case 'R':
		return &reLineBreak{}
	case 'X':
		return &reAny{dotall: true}
	case 'O':
		return &reAny{dotall: true}
	case 'N':
		return &reAny{dotall: false}
	case 'Q':
		var items []reNode
		for p.more() {
			if p.peek() == '\\' && p.pos+1 < len(p.src) && p.src[p.pos+1] == 'E' {
				p.pos += 2
				break
			}
			items = append(items, &reLit{r: p.next(), fold: p.flagI})
		}
		return &reConcat{items: items}
	case 'k':
		if p.more() && p.peek() == '<' {
			p.pos++
			name := p.parseName('>')
			b := &reBackref{name: name, fold: p.flagI}
			if n, err := strconv.Atoi(name); err == nil {
				b.name = ""
				b.idx = n
			}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		p.fail("invalid backref number/name")
	case 'g':
		if p.more() && p.peek() == '<' {
			p.pos++
			name := p.parseName('>')
			b := &reBackref{name: name, fold: p.flagI}
			if n, err := strconv.Atoi(name); err == nil {
				b.name = ""
				b.idx = n
			}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		p.fail("invalid group name <>")
	}
	if c >= '1' && c <= '9' {
		v := int(c - '0')
		for p.more() && p.peek() >= '0' && p.peek() <= '9' && v*10+int(p.peek()-'0') <= p.ncap {
			v = v*10 + int(p.next()-'0')
		}
		if v <= 9 || v <= p.ncap {
			b := &reBackref{idx: v, fold: p.flagI}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		// octal
		p.pos--
		ov := 0
		n := 0
		for n < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			ov = ov*8 + int(p.next()-'0')
			n++
		}
		return &reLit{r: rune(ov), fold: p.flagI}
	}
	return &reLit{r: c, fold: p.flagI}
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsNumber(r) || unicode.IsMark(r) || r == '_' || unicode.Is(unicode.Pc, r)
}

func (p *reParser) parseClass() *charSet {
	cs := &charSet{}
	if p.more() && p.peek() == '^' {
		cs.neg = true
		p.pos++
	}
	first := true
	addRange := func(lo, hi rune) {
		cs.ranges = append(cs.ranges, lo, hi)
	}
	for {
		if !p.more() {
			p.fail("premature end of char-class")
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		if c == ']' && first {
			if cs.neg || true {
				// "[]" or "[^]" -> empty class error unless ] is literal; Oniguruma treats ']' first as literal
				// but "[^]" errors: empty char-class
				if p.pos+1 < len(p.src) {
					// treat as literal ']'
					p.pos++
					addRange(']', ']')
					first = false
					if p.more() && p.peek() == ']' && len(p.src) > p.pos {
						// e.g. "[]]": close
						continue
					}
					continue
				}
				p.fail("empty char-class")
			}
		}
		first = false
		p.pos++
		var lo rune
		var single reNode
		if c == '[' && p.more() && p.peek() == ':' {
			// POSIX bracket
			end := -1
			for j := p.pos + 1; j+1 < len(p.src); j++ {
				if p.src[j] == ':' && p.src[j+1] == ']' {
					end = j
					break
				}
				if p.src[j] == ']' {
					break
				}
			}
			if end >= 0 {
				name := string(p.src[p.pos+1 : end])
				neg := false
				if strings.HasPrefix(name, "^") {
					neg = true
					name = name[1:]
				}
				fn := posixClass(name)
				if fn == nil {
					p.fail("invalid POSIX bracket type")
				}
				p.pos = end + 2
				if neg {
					cs.negFns = append(cs.negFns, fn)
				} else {
					cs.fns = append(cs.fns, fn)
				}
				continue
			}
			lo = '['
		} else if c == '\\' {
			single = p.parseEscape(true)
			switch n := single.(type) {
			case *reLit:
				lo = n.r
			case *reClass:
				if n.set.neg {
					if len(n.set.fns) == 1 {
						cs.negFns = append(cs.negFns, n.set.fns[0])
					} else {
						inner := n.set
						cs.fns = append(cs.fns, func(r rune) bool { return !inner.matchRaw(r) })
					}
				} else {
					cs.fns = append(cs.fns, n.set.fns...)
					cs.ranges = append(cs.ranges, n.set.ranges...)
				}
				continue
			default:
				continue
			}
		} else {
			lo = c
		}
		// range?
		if p.more() && p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hc := p.next()
			var hi rune
			if hc == '\\' {
				n := p.parseEscape(true)
				if lit, ok := n.(*reLit); ok {
					hi = lit.r
				} else {
					p.fail("char-class value at end of range")
				}
			} else if hc == '[' && p.more() && p.peek() == ':' {
				p.fail("char-class value at end of range")
			} else {
				hi = hc
			}
			if hi < lo {
				p.fail("empty range in char class")
			}
			addRange(lo, hi)
		} else {
			addRange(lo, lo)
		}
	}
	if len(cs.ranges) == 0 && len(cs.fns) == 0 && len(cs.negFns) == 0 {
		p.fail("empty char-class")
	}
	return cs
}

func posixClass(name string) func(rune) bool {
	switch name {
	case "alpha":
		return unicode.IsLetter
	case "digit":
		return unicode.IsDigit
	case "alnum":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) }
	case "upper":
		return unicode.IsUpper
	case "lower":
		return unicode.IsLower
	case "space":
		return unicode.IsSpace
	case "punct":
		return func(r rune) bool { return unicode.IsPunct(r) || (r < 128 && unicode.IsSymbol(r)) }
	case "cntrl":
		return unicode.IsControl
	case "xdigit":
		return func(r rune) bool { return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') }
	case "blank":
		return func(r rune) bool { return r == '\t' || unicode.Is(unicode.Zs, r) }
	case "graph":
		return func(r rune) bool { return !unicode.IsSpace(r) && !unicode.IsControl(r) && unicode.IsPrint(r) }
	case "print":
		return func(r rune) bool { return (unicode.IsPrint(r) || unicode.Is(unicode.Zs, r)) && !unicode.IsControl(r) }
	case "word":
		return isWordRune
	case "ascii":
		return func(r rune) bool { return r < 128 }
	}
	return nil
}

var longCategoryNames = map[string]string{
	"letter": "L", "uppercaseletter": "Lu", "lowercaseletter": "Ll", "titlecaseletter": "Lt", "casedletter": "LC", "lc": "LC",
	"modifierletter": "Lm", "otherletter": "Lo", "mark": "M", "nonspacingmark": "Mn", "spacingmark": "Mc", "enclosingmark": "Me",
	"number": "N", "decimalnumber": "Nd", "letternumber": "Nl", "othernumber": "No", "punctuation": "P", "connectorpunctuation": "Pc",
	"dashpunctuation": "Pd", "openpunctuation": "Ps", "closepunctuation": "Pe", "initialpunctuation": "Pi", "finalpunctuation": "Pf",
	"otherpunctuation": "Po", "symbol": "S", "mathsymbol": "Sm", "currencysymbol": "Sc", "modifiersymbol": "Sk", "othersymbol": "So",
	"separator": "Z", "spaceseparator": "Zs", "lineseparator": "Zl", "paragraphseparator": "Zp", "other": "C", "control": "Cc",
	"format": "Cf", "surrogate": "Cs", "privateuse": "Co", "unassigned": "Cn",
}

func normPropName(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if r == ' ' || r == '_' || r == '-' {
			continue
		}
		sb.WriteRune(unicode.ToLower(r))
	}
	return sb.String()
}

func propertyFunc(name string) func(rune) bool {
	n := normPropName(name)
	if n == "" {
		return nil
	}
	// general categories by short name
	for k, tab := range unicode.Categories {
		if strings.ToLower(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	if n == "lc" || n == "l&" {
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
	}
	if long, ok := longCategoryNames[n]; ok {
		if long == "LC" {
			return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
		}
		t := unicode.Categories[long]
		return func(r rune) bool { return unicode.Is(t, r) }
	}
	switch n {
	case "any":
		return func(r rune) bool { return true }
	case "assigned":
		return func(r rune) bool { return !unicode.Is(unicode.Cn, r) && (unicode.IsGraphic(r) || unicode.IsControl(r) || unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Co, r) || unicode.Is(unicode.Mn, r)) }
	case "ascii":
		return func(r rune) bool { return r < 128 }
	case "alpha", "alphabetic":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_Alphabetic, r) }
	case "digit":
		return unicode.IsDigit
	case "alnum":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_Alphabetic, r) }
	case "upper", "uppercase":
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.Is(unicode.Other_Uppercase, r) }
	case "lower", "lowercase":
		return func(r rune) bool { return unicode.IsLower(r) || unicode.Is(unicode.Other_Lowercase, r) }
	case "space", "whitespace":
		return unicode.IsSpace
	case "punct":
		return unicode.IsPunct
	case "cntrl":
		return unicode.IsControl
	case "xdigit":
		return func(r rune) bool { return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') }
	case "hexdigit":
		return func(r rune) bool { return unicode.Is(unicode.Hex_Digit, r) }
	case "blank":
		return func(r rune) bool { return r == '\t' || unicode.Is(unicode.Zs, r) }
	case "graph":
		return func(r rune) bool { return !unicode.IsSpace(r) && !unicode.IsControl(r) && unicode.IsPrint(r) }
	case "print":
		return func(r rune) bool { return (unicode.IsPrint(r) || unicode.Is(unicode.Zs, r)) && !unicode.IsControl(r) }
	case "word":
		return isWordRune
	case "cased":
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
	case "emoji":
		return func(r rune) bool { return (r >= 0x1F300 && r <= 0x1FAFF) || (r >= 0x2600 && r <= 0x27BF) || r == '#' || r == '*' || (r >= '0' && r <= '9') || r == 0xA9 || r == 0xAE }
	}
	// scripts
	for k, tab := range unicode.Scripts {
		if strings.ToLower(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	if alias, ok := scriptAliases[n]; ok {
		t := unicode.Scripts[alias]
		return func(r rune) bool { return unicode.Is(t, r) }
	}
	// properties
	for k, tab := range unicode.Properties {
		if normPropName(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	switch n {
	case "idstart":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r) }
	case "idcontinue":
		return func(r rune) bool { return isWordRune(r) || unicode.Is(unicode.Other_ID_Continue, r) }
	}
	// blocks (subset)
	if strings.HasPrefix(n, "in") {
		if b, ok := unicodeBlocks[n[2:]]; ok {
			lo, hi := b[0], b[1]
			return func(r rune) bool { return r >= lo && r <= hi }
		}
	}
	return nil
}

var scriptAliases = map[string]string{
	"latn": "Latin", "grek": "Greek", "cyrl": "Cyrillic", "hani": "Han", "hira": "Hiragana", "kana": "Katakana", "arab": "Arabic",
	"hebr": "Hebrew", "zyyy": "Common", "zinh": "Inherited", "qaai": "Inherited", "hang": "Hangul", "thai": "Thai", "deva": "Devanagari",
	"armn": "Armenian", "beng": "Bengali", "geor": "Georgian", "ethi": "Ethiopic", "khmr": "Khmer", "mong": "Mongolian", "tibt": "Tibetan",
}

var unicodeBlocks = map[string][2]rune{
	"basiclatin": {0x0000, 0x007F}, "latin1supplement": {0x0080, 0x00FF}, "latinextendeda": {0x0100, 0x017F}, "latinextendedb": {0x0180, 0x024F},
	"greekandcoptic": {0x0370, 0x03FF}, "greek": {0x0370, 0x03FF}, "cyrillic": {0x0400, 0x04FF}, "hebrew": {0x0590, 0x05FF}, "arabic": {0x0600, 0x06FF},
	"cjkunifiedideographs": {0x4E00, 0x9FFF}, "hiragana": {0x3040, 0x309F}, "katakana": {0x30A0, 0x30FF}, "hangulsyllables": {0xAC00, 0xD7AF},
	"generalpunctuation": {0x2000, 0x206F}, "emoticons": {0x1F600, 0x1F64F}, "thai": {0x0E00, 0x0E7F}, "devanagari": {0x0900, 0x097F},
}

// ---- matcher ----

type reMatcher struct {
	re    *Regex
	input string
	caps  []int // 2*(ncap+1)
	steps int
	keepStart int
}

const maxRegexSteps = 50000000

func (m *reMatcher) matchAt(start int) bool {
	for i := range m.caps {
		m.caps[i] = -1
	}
	m.caps[0] = start
	m.keepStart = -1
	if m.re.findLongest {
		bestEnd := -1
		var bestCaps []int
		m.match(m.re.root, start, func(pos int) bool {
			if m.re.notEmpty && pos == start {
				return false
			}
			if pos > bestEnd {
				bestEnd = pos
				bestCaps = make([]int, len(m.caps))
				copy(bestCaps, m.caps)
				bestCaps[1] = pos
			}
			return false
		})
		if bestEnd < 0 {
			return false
		}
		copy(m.caps, bestCaps)
		return true
	}
	return m.match(m.re.root, start, func(pos int) bool {
		if m.re.notEmpty && pos == start {
			return false
		}
		m.caps[1] = pos
		if m.keepStart >= 0 {
			m.caps[0] = m.keepStart
		}
		return true
	})
}

func (m *reMatcher) runeAt(pos int) (rune, int) {
	if pos >= len(m.input) {
		return -1, 0
	}
	r, size := utf8.DecodeRuneInString(m.input[pos:])
	return r, size
}

func (m *reMatcher) runeBefore(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	r, size := utf8.DecodeLastRuneInString(m.input[:pos])
	return r, size
}

func foldEq(a, b rune) bool {
	if a == b {
		return true
	}
	for f := unicode.SimpleFold(a); f != a; f = unicode.SimpleFold(f) {
		if f == b {
			return true
		}
	}
	return false
}

func (m *reMatcher) isWordAt(pos int) bool {
	r, _ := m.runeAt(pos)
	return r >= 0 && isWordRune(r)
}
func (m *reMatcher) isWordBefore(pos int) bool {
	r, _ := m.runeBefore(pos)
	return r >= 0 && isWordRune(r)
}

func (m *reMatcher) match(n reNode, pos int, k func(int) bool) bool {
	m.steps++
	if m.steps > maxRegexSteps {
		panic(&regexError{"match-stack limit over"})
	}
	switch x := n.(type) {
	case nil, *reEmpty:
		return k(pos)
	case *reLit:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if r == x.r || (x.fold && foldEq(r, x.r)) {
			return k(pos + size)
		}
		return false
	case *reAny:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if !x.dotall && r == '\n' {
			return false
		}
		return k(pos + size)
	case *reLineBreak:
		if strings.HasPrefix(m.input[pos:], "\r\n") {
			if k(pos + 2) {
				return true
			}
		}
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if r == '\n' || r == '\v' || r == '\f' || r == '\r' || r == 0x85 || r == 0x2028 || r == 0x2029 {
			return k(pos + size)
		}
		return false
	case *reClass:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if x.set.matches(r, x.fold) {
			return k(pos + size)
		}
		return false
	case *reStart:
		if pos == 0 || (x.multiline && m.input[pos-1] == '\n') {
			return k(pos)
		}
		return false
	case *reEnd:
		if pos == len(m.input) || (pos == len(m.input)-1 && m.input[pos] == '\n') || (x.multiline && m.input[pos] == '\n') {
			return k(pos)
		}
		return false
	case *reBufStart:
		if pos == 0 {
			return k(pos)
		}
		return false
	case *reBufEnd:
		if pos == len(m.input) {
			return k(pos)
		}
		return false
	case *reBufEndNL:
		if pos == len(m.input) || (pos == len(m.input)-1 && m.input[pos] == '\n') {
			return k(pos)
		}
		return false
	case *reWordB:
		a := m.isWordBefore(pos)
		b := m.isWordAt(pos)
		if (a != b) != x.neg {
			return k(pos)
		}
		return false
	case *reKeep:
		old := m.keepStart
		m.keepStart = pos
		if k(pos) {
			return true
		}
		m.keepStart = old
		return false
	case *reGroup:
		if x.idx == 0 {
			return m.match(x.body, pos, k)
		}
		oldS, oldE := m.caps[2*x.idx], m.caps[2*x.idx+1]
		if m.match(x.body, pos, func(e int) bool {
			ps, pe := m.caps[2*x.idx], m.caps[2*x.idx+1]
			m.caps[2*x.idx] = pos
			m.caps[2*x.idx+1] = e
			if k(e) {
				return true
			}
			m.caps[2*x.idx] = ps
			m.caps[2*x.idx+1] = pe
			return false
		}) {
			return true
		}
		m.caps[2*x.idx] = oldS
		m.caps[2*x.idx+1] = oldE
		return false
	case *reConcat:
		return m.matchSeq(x.items, 0, pos, k)
	case *reAlt:
		for _, a := range x.alts {
			if m.match(a, pos, k) {
				return true
			}
		}
		return false
	case *reRepeat:
		if x.possessive {
			// match greedily without backtracking into the repeat
			end := -1
			count := 0
			cur := pos
			for x.max < 0 || count < x.max {
				np := -1
				m.match(x.body, cur, func(e int) bool { np = e; return true })
				if np < 0 || np == cur {
					if np == cur {
						count++
					}
					break
				}
				cur = np
				count++
			}
			if count < x.min {
				return false
			}
			end = cur
			return k(end)
		}
		return m.matchRepeat(x, pos, 0, k)
	case *reBackref:
		s, e := m.caps[2*x.idx], m.caps[2*x.idx+1]
		if s < 0 || e < 0 {
			return false
		}
		sub := m.input[s:e]
		if x.fold {
			// compare rune by rune with folding
			p := pos
			for _, r := range sub {
				r2, size := m.runeAt(p)
				if r2 < 0 || !foldEq(r, r2) {
					return false
				}
				p += size
			}
			return k(p)
		}
		if strings.HasPrefix(m.input[pos:], sub) {
			return k(pos + len(sub))
		}
		return false
	case *reLook:
		if !x.behind {
			saved := make([]int, len(m.caps))
			copy(saved, m.caps)
			ok := m.match(x.body, pos, func(int) bool { return true })
			if x.neg {
				copy(m.caps, saved)
				if ok {
					return false
				}
				return k(pos)
			}
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		// lookbehind: find a start s <= pos such that body matches exactly [s, pos)
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		found := false
		for s := pos; s >= 0; s-- {
			if s < len(m.input) && s > 0 && !utf8.RuneStart(m.input[s]) {
				continue
			}
			if m.match(x.body, s, func(e int) bool { return e == pos }) {
				found = true
				break
			}
		}
		if x.neg {
			copy(m.caps, saved)
			if found {
				return false
			}
			return k(pos)
		}
		if !found {
			copy(m.caps, saved)
			return false
		}
		if k(pos) {
			return true
		}
		copy(m.caps, saved)
		return false
	case *reAtomic:
		end := -1
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		if !m.match(x.body, pos, func(e int) bool { end = e; return true }) {
			copy(m.caps, saved)
			return false
		}
		if k(end) {
			return true
		}
		copy(m.caps, saved)
		return false
	}
	panic(fmt.Sprintf("regex: unknown node %T", n))
}

func (m *reMatcher) matchSeq(items []reNode, i int, pos int, k func(int) bool) bool {
	if i >= len(items) {
		return k(pos)
	}
	return m.match(items[i], pos, func(np int) bool {
		return m.matchSeq(items, i+1, np, k)
	})
}

func (m *reMatcher) matchRepeat(x *reRepeat, pos int, count int, k func(int) bool) bool {
	canStop := count >= x.min
	canMore := x.max < 0 || count < x.max
	tryMore := func() bool {
		if !canMore {
			return false
		}
		return m.match(x.body, pos, func(np int) bool {
			if np == pos && count >= x.min {
				// empty iteration: don't loop forever
				return false
			}
			return m.matchRepeat(x, np, count+1, k)
		})
	}
	if x.greedy {
		if tryMore() {
			return true
		}
		if canStop {
			return k(pos)
		}
		return false
	}
	if canStop && k(pos) {
		return true
	}
	return tryMore()
}

// ---- jq interface ----

func cpOffset(s string, bytePos int) int {
	// count characters starting before bytePos (jq counts decode lengths until >= bytePos)
	n := 0
	i := 0
	for i < bytePos && i < len(s) {
		_, size := utf8.DecodeRuneInString(s[i:])
		i += size
		n++
	}
	return n
}

func matchImpl(input Value, reV Value, flagsV Value, testV Value) (Value, error) {
	s, ok := input.(string)
	if !ok {
		return nil, typeErr(input, "cannot be matched, as it is not a string")
	}
	pattern, ok := reV.(string)
	if !ok {
		return nil, typeErr(reV, "is not a string")
	}
	flags := ""
	if flagsV != nil {
		fs, ok := flagsV.(string)
		if !ok {
			return nil, typeErr(flagsV, "is not a string")
		}
		flags = fs
	}
	global := strings.Contains(flags, "g")
	test := truthy(testV)
	re, err := compileRegex(pattern, flags)
	if err != nil {
		if strings.HasSuffix(err.Error(), "is not a valid modifier string") {
			return nil, &JQError{Val: err.Error()}
		}
		return nil, newError("Regex failure: %s", err.Error())
	}
	m := &reMatcher{re: re, input: s, caps: make([]int, 2*(re.ncap+1))}
	results := []Value{}
	start := 0
	var merr error
	func() {
		defer func() {
			if r := recover(); r != nil {
				if e, ok := r.(*regexError); ok {
					merr = newError("Regex failure: %s", e.msg)
					return
				}
				panic(r)
			}
		}()
		for start <= len(s) {
			found := false
			var mstart int
			for mstart = start; mstart <= len(s); mstart++ {
				if m.matchAt(mstart) {
					found = true
					break
				}
			}
			if !found {
				break
			}
			if test {
				results = append(results, true)
				return
			}
			mb, me := m.caps[0], m.caps[1]
			results = append(results, buildMatch(s, m, re))
			if me == mb {
				start = me + 1
			} else {
				start = me
			}
			if !global {
				break
			}
		}
	}()
	if merr != nil {
		return nil, merr
	}
	if test {
		return len(results) > 0, nil
	}
	return results, nil
}

func buildMatch(s string, m *reMatcher, re *Regex) Value {
	mb, me := m.caps[0], m.caps[1]
	obj := NewObject()
	off := cpOffset(s, mb)
	matched := ""
	if mb <= me && me <= len(s) {
		matched = s[mb:me]
	}
	obj.SetInPlace("offset", float64(off))
	obj.SetInPlace("length", float64(utf8.RuneCountInString(matched)))
	obj.SetInPlace("string", matched)
	caps := []Value{}
	for i := 1; i <= re.ncap; i++ {
		c := NewObject()
		cs, ce := m.caps[2*i], m.caps[2*i+1]
		var name Value
		if re.names[i] != "" {
			name = re.names[i]
		}
		if cs < 0 || ce < 0 {
			c.SetInPlace("offset", float64(-1))
			c.SetInPlace("string", nil)
			c.SetInPlace("length", float64(0))
			c.SetInPlace("name", name)
		} else {
			sub := s[cs:ce]
			c.SetInPlace("offset", float64(cpOffset(s, cs)))
			c.SetInPlace("length", float64(utf8.RuneCountInString(sub)))
			c.SetInPlace("string", sub)
			c.SetInPlace("name", name)
		}
		caps = append(caps, c)
	}
	obj.SetInPlace("captures", caps)
	return obj
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > regex.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// ---- regex AST ----

type reNode interface{}

type (
	reLit      struct{ r rune; fold bool }
	reAny      struct{ dotall bool }
	reClass    struct{ set *charSet; fold bool }
	reStart    struct{ multiline bool } // ^
	reEnd      struct{ multiline bool } // $
	reBufStart struct{}                 // \A
	reBufEnd   struct{}                 // \z
	reBufEndNL struct{}                 // \Z
	reWordB    struct{ neg bool }
	reGroup    struct {
		idx  int // capture index (1-based), 0 = non-capturing
		body reNode
	}
	reConcat struct{ items []reNode }
	reAlt    struct{ alts []reNode }
	reRepeat struct {
		body               reNode
		min, max           int // max -1 = inf
		greedy, possessive bool
	}
	reBackref struct {
		idx  int
		name string
		fold bool
	}
	reLook struct {
		body   reNode
		neg    bool
		behind bool
	}
	reAtomic struct{ body reNode }
	reEmpty  struct{}
	reKeep   struct{}
	reLineBreak struct{}
)

type charSet struct {
	neg    bool
	ranges []rune // pairs
	fns    []func(rune) bool
	negFns []func(rune) bool
}

func (cs *charSet) matches(r rune, fold bool) bool {
	m := cs.matchRaw(r)
	if !m && fold {
		for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
			if cs.matchRaw(f) {
				m = true
				break
			}
		}
	}
	if cs.neg {
		return !m
	}
	return m
}

func (cs *charSet) matchRaw(r rune) bool {
	for i := 0; i+1 < len(cs.ranges); i += 2 {
		if r >= cs.ranges[i] && r <= cs.ranges[i+1] {
			return true
		}
	}
	for _, f := range cs.fns {
		if f(r) {
			return true
		}
	}
	for _, f := range cs.negFns {
		if !f(r) {
			return true
		}
	}
	return false
}

// ---- compiled regex ----

type Regex struct {
	root       reNode
	ncap       int
	names      []string // index -> name ("" if unnamed), 1-based (names[0] unused)
	nameToIdx  map[string][]int
	ignoreCase bool
	findLongest bool
	notEmpty   bool
}

type regexError struct{ msg string }

func (e *regexError) Error() string { return e.msg }

type reParser struct {
	src      []rune
	pos      int
	ncap     int
	names    []string
	nameIdx  map[string][]int
	flagI    bool
	flagX    bool
	flagS    bool // dotall
	flagM    bool // multiline anchors
	backrefs []*reBackref
}

func (p *reParser) fail(msg string) {
	panic(&regexError{msg})
}

func compileRegex(pattern string, flags string) (re *Regex, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*regexError); ok {
				re = nil
				err = e
				return
			}
			panic(r)
		}
	}()
	p := &reParser{src: []rune(pattern), nameIdx: map[string][]int{}}
	p.names = []string{""}
	re = &Regex{}
	for _, f := range flags {
		switch f {
		case 'g':
		case 'i':
			p.flagI = true
			re.ignoreCase = true
		case 'x':
			p.flagX = true
		case 'n':
			re.notEmpty = true
		case 'p':
			p.flagS = true
		case 's':
		case 'l':
			re.findLongest = true
		default:
			return nil, &regexError{fmt.Sprintf("%s is not a valid modifier string", flags)}
		}
	}
	root := p.parseAlt()
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			p.fail("unmatched close parenthesis")
		}
		p.fail("invalid pattern")
	}
	// resolve named backrefs
	for _, b := range p.backrefs {
		if b.name != "" {
			idxs, ok := p.nameIdx[b.name]
			if !ok {
				p.fail(fmt.Sprintf("undefined name <%s> reference", b.name))
			}
			b.idx = idxs[len(idxs)-1]
		} else if b.idx > p.ncap {
			p.fail("invalid backref number/name")
		}
	}
	re.root = root
	re.ncap = p.ncap
	re.names = p.names
	re.nameToIdx = p.nameIdx
	return re, nil
}

func (p *reParser) more() bool { return p.pos < len(p.src) }
func (p *reParser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}
func (p *reParser) next() rune {
	r := p.src[p.pos]
	p.pos++
	return r
}

func (p *reParser) skipExtended() {
	if !p.flagX {
		return
	}
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
		} else if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
		} else {
			break
		}
	}
}

func (p *reParser) parseAlt() reNode {
	var alts []reNode
	alts = append(alts, p.parseConcat())
	for p.more() && p.peek() == '|' {
		p.pos++
		alts = append(alts, p.parseConcat())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reAlt{alts: alts}
}

func (p *reParser) parseConcat() reNode {
	var items []reNode
	for {
		p.skipExtended()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuantifiers(atom)
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0]
	}
	return &reConcat{items: items}
}

func (p *reParser) parseQuantifiers(atom reNode) reNode {
	for {
		p.skipExtended()
		if !p.more() {
			return atom
		}
		c := p.peek()
		var min, max int
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			save := p.pos
			p.pos++
			n1, ok1 := p.parseInt()
			if !ok1 {
				p.pos = save
				return atom
			}
			if p.peek() == '}' {
				p.pos++
				min, max = n1, n1
			} else if p.peek() == ',' {
				p.pos++
				n2, ok2 := p.parseInt()
				if p.peek() != '}' {
					p.pos = save
					return atom
				}
				p.pos++
				if ok2 {
					min, max = n1, n2
					if max < min {
						p.fail("upper is smaller than lower in repeat range")
					}
				} else {
					min, max = n1, -1
				}
			} else {
				p.pos = save
				return atom
			}
		default:
			return atom
		}
		greedy, possessive := true, false
		if p.more() && p.peek() == '?' {
			greedy = false
			p.pos++
		} else if p.more() && p.peek() == '+' && c != '{' {
			possessive = true
			p.pos++
		}
		if _, isAnchor := atom.(*reStart); isAnchor {
			p.fail("target of repeat operator is invalid")
		}
		atom = &reRepeat{body: atom, min: min, max: max, greedy: greedy, possessive: possessive}
	}
}

func (p *reParser) parseInt() (int, bool) {
	start := p.pos
	v := 0
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		v = v*10 + int(p.next()-'0')
		if v > 100000 {
			p.fail("too big number for repeat range")
		}
	}
	if p.pos == start {
		return 0, false
	}
	return v, true
}

func (p *reParser) parseAtom() reNode {
	c := p.next()
	switch c {
	case '(':
		return p.parseGroup()
	case ')':
		p.fail("unmatched close parenthesis")
	case '[':
		return &reClass{set: p.parseClass(), fold: p.flagI}
	case '.':
		return &reAny{dotall: p.flagS}
	case '^':
		return &reStart{multiline: p.flagM}
	case '$':
		return &reEnd{multiline: p.flagM}
	case '*', '+', '?':
		p.fail("target of repeat operator is not specified")
	case '{':
		// literal unless valid quantifier (which would have been consumed)
		return &reLit{r: c, fold: p.flagI}
	case '\\':
		return p.parseEscape(false)
	}
	return &reLit{r: c, fold: p.flagI}
}

func (p *reParser) parseGroup() reNode {
	if !p.more() {
		p.fail("end pattern with unmatched parenthesis")
	}
	if p.peek() == '?' {
		p.pos++
		if !p.more() {
			p.fail("end pattern in group")
		}
		c := p.next()
		switch c {
		case ':':
			body := p.parseAltUntilClose()
			return &reGroup{idx: 0, body: body}
		case '=', '!':
			body := p.parseAltUntilClose()
			return &reLook{body: body, neg: c == '!'}
		case '>':
			body := p.parseAltUntilClose()
			return &reAtomic{body: body}
		case '#':
			for p.more() && p.peek() != ')' {
				p.pos++
			}
			if !p.more() {
				p.fail("end pattern in group")
			}
			p.pos++
			return nil
		case '<':
			if !p.more() {
				p.fail("end pattern with unmatched parenthesis")
			}
			if p.peek() == '=' || p.peek() == '!' {
				neg := p.next() == '!'
				body := p.parseAltUntilClose()
				return &reLook{body: body, neg: neg, behind: true}
			}
			name := p.parseName('>')
			return p.captureGroup(name)
		case '\'':
			name := p.parseName('\'')
			return p.captureGroup(name)
		case 'P':
			if p.more() && p.peek() == '<' {
				p.pos++
				name := p.parseName('>')
				return p.captureGroup(name)
			}
			p.fail("undefined group option")
		default:
			// option flags (?imsx-imsx) or (?imsx-imsx:...)
			p.pos--
			saveI, saveX, saveS, saveM := p.flagI, p.flagX, p.flagS, p.flagM
			neg := false
			for p.more() {
				o := p.next()
				switch o {
				case 'i':
					p.flagI = !neg
				case 'x':
					p.flagX = !neg
				case 's':
					p.flagS = !neg
				case 'm':
					p.flagM = !neg
				case '-':
					neg = true
				case ')':
					// applies to the rest of the enclosing group
					return nil
				case ':':
					body := p.parseAltUntilClose()
					p.flagI, p.flagX, p.flagS, p.flagM = saveI, saveX, saveS, saveM
					return &reGroup{idx: 0, body: body}
				default:
					p.fail("undefined group option")
				}
			}
			p.fail("end pattern in group")
		}
	}
	return p.captureGroup("")
}

func (p *reParser) captureGroup(name string) reNode {
	p.ncap++
	idx := p.ncap
	p.names = append(p.names, name)
	if name != "" {
		p.nameIdx[name] = append(p.nameIdx[name], idx)
	}
	body := p.parseAltUntilClose()
	return &reGroup{idx: idx, body: body}
}

func (p *reParser) parseName(end rune) string {
	var sb strings.Builder
	for {
		if !p.more() {
			p.fail("invalid group name <>")
		}
		c := p.next()
		if c == end {
			break
		}
		sb.WriteRune(c)
	}
	name := sb.String()
	if name == "" {
		p.fail("group name is empty")
	}
	return name
}

func (p *reParser) parseAltUntilClose() reNode {
	saveI, saveX, saveS, saveM := p.flagI, p.flagX, p.flagS, p.flagM
	body := p.parseAlt()
	if !p.more() || p.peek() != ')' {
		p.fail("end pattern with unmatched parenthesis")
	}
	p.pos++
	p.flagI, p.flagX, p.flagS, p.flagM = saveI, saveX, saveS, saveM
	return body
}

func (p *reParser) parseHex(maxDigits int) (rune, bool) {
	v := 0
	n := 0
	for n < maxDigits && p.more() {
		c := p.peek()
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			goto done
		}
		v = v*16 + d
		p.pos++
		n++
	}
done:
	if n == 0 {
		return 0, false
	}
	return rune(v), true
}

// parseEscape parses after a backslash. inClass indicates inside [...].
func (p *reParser) parseEscape(inClass bool) reNode {
	if !p.more() {
		p.fail("end pattern at escape")
	}
	c := p.next()
	switch c {
	case 't':
		return &reLit{r: '\t', fold: p.flagI}
	case 'n':
		return &reLit{r: '\n', fold: p.flagI}
	case 'r':
		return &reLit{r: '\r', fold: p.flagI}
	case 'f':
		return &reLit{r: '\f', fold: p.flagI}
	case 'v':
		return &reLit{r: '\v', fold: p.flagI}
	case 'a':
		return &reLit{r: 7, fold: p.flagI}
	case 'e':
		return &reLit{r: 27, fold: p.flagI}
	case 'x':
		if p.more() && p.peek() == '{' {
			p.pos++
			v, ok := p.parseHex(8)
			if !ok || !p.more() || p.peek() != '}' {
				p.fail("invalid code point value")
			}
			p.pos++
			return &reLit{r: v, fold: p.flagI}
		}
		v, ok := p.parseHex(2)
		if !ok {
			return &reLit{r: 0, fold: p.flagI}
		}
		return &reLit{r: v, fold: p.flagI}
	case '0':
		v := 0
		n := 0
		for n < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.next()-'0')
			n++
		}
		return &reLit{r: rune(v), fold: p.flagI}
	case 'd':
		return &reClass{set: &charSet{fns: []func(rune) bool{unicode.IsDigit}}}
	case 'D':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{unicode.IsDigit}}}
	case 'w':
		return &reClass{set: &charSet{fns: []func(rune) bool{isWordRune}}}
	case 'W':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{isWordRune}}}
	case 's':
		return &reClass{set: &charSet{fns: []func(rune) bool{unicode.IsSpace}}}
	case 'S':
		return &reClass{set: &charSet{neg: true, fns: []func(rune) bool{unicode.IsSpace}}}
	case 'p', 'P':
		neg := c == 'P'
		if !p.more() || p.peek() != '{' {
			p.fail("invalid character property name {}")
		}
		p.pos++
		var sb strings.Builder
		for p.more() && p.peek() != '}' {
			sb.WriteRune(p.next())
		}
		if !p.more() {
			p.fail("invalid character property name {" + sb.String() + "}")
		}
		p.pos++
		name := sb.String()
		if strings.HasPrefix(name, "^") {
			neg = !neg
			name = name[1:]
		}
		fn := propertyFunc(name)
		if fn == nil {
			p.fail("invalid character property name {" + sb.String() + "}")
		}
		return &reClass{set: &charSet{neg: neg, fns: []func(rune) bool{fn}}}
	}
	if inClass {
		if c == 'b' {
			return &reLit{r: '\b'}
		}
		return &reLit{r: c}
	}
	switch c {
	case 'b':
		return &reWordB{}
	case 'B':
		return &reWordB{neg: true}
	case 'A':
		return &reBufStart{}
	case 'z':
		return &reBufEnd{}
	case 'Z':
		return &reBufEndNL{}
	case 'G':
		return &reBufStart{}
	case 'K':
		return &reKeep{}
	case 'R':
		return &reLineBreak{}
	case 'X':
		return &reAny{dotall: true}
	case 'O':
		return &reAny{dotall: true}
	case 'N':
		return &reAny{dotall: false}
	case 'Q':
		var items []reNode
		for p.more() {
			if p.peek() == '\\' && p.pos+1 < len(p.src) && p.src[p.pos+1] == 'E' {
				p.pos += 2
				break
			}
			items = append(items, &reLit{r: p.next(), fold: p.flagI})
		}
		return &reConcat{items: items}
	case 'k':
		if p.more() && p.peek() == '<' {
			p.pos++
			name := p.parseName('>')
			b := &reBackref{name: name, fold: p.flagI}
			if n, err := strconv.Atoi(name); err == nil {
				b.name = ""
				b.idx = n
			}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		p.fail("invalid backref number/name")
	case 'g':
		if p.more() && p.peek() == '<' {
			p.pos++
			name := p.parseName('>')
			b := &reBackref{name: name, fold: p.flagI}
			if n, err := strconv.Atoi(name); err == nil {
				b.name = ""
				b.idx = n
			}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		p.fail("invalid group name <>")
	}
	if c >= '1' && c <= '9' {
		v := int(c - '0')
		for p.more() && p.peek() >= '0' && p.peek() <= '9' && v*10+int(p.peek()-'0') <= p.ncap {
			v = v*10 + int(p.next()-'0')
		}
		if v <= 9 || v <= p.ncap {
			b := &reBackref{idx: v, fold: p.flagI}
			p.backrefs = append(p.backrefs, b)
			return b
		}
		// octal
		p.pos--
		ov := 0
		n := 0
		for n < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			ov = ov*8 + int(p.next()-'0')
			n++
		}
		return &reLit{r: rune(ov), fold: p.flagI}
	}
	return &reLit{r: c, fold: p.flagI}
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsNumber(r) || unicode.IsMark(r) || r == '_' || unicode.Is(unicode.Pc, r)
}

func (p *reParser) parseClass() *charSet {
	cs := &charSet{}
	if p.more() && p.peek() == '^' {
		cs.neg = true
		p.pos++
	}
	first := true
	addRange := func(lo, hi rune) {
		cs.ranges = append(cs.ranges, lo, hi)
	}
	for {
		if !p.more() {
			p.fail("premature end of char-class")
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		if c == ']' && first {
			if cs.neg || true {
				// "[]" or "[^]" -> empty class error unless ] is literal; Oniguruma treats ']' first as literal
				// but "[^]" errors: empty char-class
				if p.pos+1 < len(p.src) {
					// treat as literal ']'
					p.pos++
					addRange(']', ']')
					first = false
					if p.more() && p.peek() == ']' && len(p.src) > p.pos {
						// e.g. "[]]": close
						continue
					}
					continue
				}
				p.fail("empty char-class")
			}
		}
		first = false
		p.pos++
		var lo rune
		var single reNode
		if c == '[' && p.more() && p.peek() == ':' {
			// POSIX bracket
			end := -1
			for j := p.pos + 1; j+1 < len(p.src); j++ {
				if p.src[j] == ':' && p.src[j+1] == ']' {
					end = j
					break
				}
				if p.src[j] == ']' {
					break
				}
			}
			if end >= 0 {
				name := string(p.src[p.pos+1 : end])
				neg := false
				if strings.HasPrefix(name, "^") {
					neg = true
					name = name[1:]
				}
				fn := posixClass(name)
				if fn == nil {
					p.fail("invalid POSIX bracket type")
				}
				p.pos = end + 2
				if neg {
					cs.negFns = append(cs.negFns, fn)
				} else {
					cs.fns = append(cs.fns, fn)
				}
				continue
			}
			lo = '['
		} else if c == '\\' {
			single = p.parseEscape(true)
			switch n := single.(type) {
			case *reLit:
				lo = n.r
			case *reClass:
				if n.set.neg {
					if len(n.set.fns) == 1 {
						cs.negFns = append(cs.negFns, n.set.fns[0])
					} else {
						inner := n.set
						cs.fns = append(cs.fns, func(r rune) bool { return !inner.matchRaw(r) })
					}
				} else {
					cs.fns = append(cs.fns, n.set.fns...)
					cs.ranges = append(cs.ranges, n.set.ranges...)
				}
				continue
			default:
				continue
			}
		} else {
			lo = c
		}
		// range?
		if p.more() && p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hc := p.next()
			var hi rune
			if hc == '\\' {
				n := p.parseEscape(true)
				if lit, ok := n.(*reLit); ok {
					hi = lit.r
				} else {
					p.fail("char-class value at end of range")
				}
			} else if hc == '[' && p.more() && p.peek() == ':' {
				p.fail("char-class value at end of range")
			} else {
				hi = hc
			}
			if hi < lo {
				p.fail("empty range in char class")
			}
			addRange(lo, hi)
		} else {
			addRange(lo, lo)
		}
	}
	if len(cs.ranges) == 0 && len(cs.fns) == 0 && len(cs.negFns) == 0 {
		p.fail("empty char-class")
	}
	return cs
}

func posixClass(name string) func(rune) bool {
	switch name {
	case "alpha":
		return unicode.IsLetter
	case "digit":
		return unicode.IsDigit
	case "alnum":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) }
	case "upper":
		return unicode.IsUpper
	case "lower":
		return unicode.IsLower
	case "space":
		return unicode.IsSpace
	case "punct":
		return func(r rune) bool { return unicode.IsPunct(r) || (r < 128 && unicode.IsSymbol(r)) }
	case "cntrl":
		return unicode.IsControl
	case "xdigit":
		return func(r rune) bool { return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') }
	case "blank":
		return func(r rune) bool { return r == '\t' || unicode.Is(unicode.Zs, r) }
	case "graph":
		return func(r rune) bool { return !unicode.IsSpace(r) && !unicode.IsControl(r) && unicode.IsPrint(r) }
	case "print":
		return func(r rune) bool { return (unicode.IsPrint(r) || unicode.Is(unicode.Zs, r)) && !unicode.IsControl(r) }
	case "word":
		return isWordRune
	case "ascii":
		return func(r rune) bool { return r < 128 }
	}
	return nil
}

var longCategoryNames = map[string]string{
	"letter": "L", "uppercaseletter": "Lu", "lowercaseletter": "Ll", "titlecaseletter": "Lt", "casedletter": "LC", "lc": "LC",
	"modifierletter": "Lm", "otherletter": "Lo", "mark": "M", "nonspacingmark": "Mn", "spacingmark": "Mc", "enclosingmark": "Me",
	"number": "N", "decimalnumber": "Nd", "letternumber": "Nl", "othernumber": "No", "punctuation": "P", "connectorpunctuation": "Pc",
	"dashpunctuation": "Pd", "openpunctuation": "Ps", "closepunctuation": "Pe", "initialpunctuation": "Pi", "finalpunctuation": "Pf",
	"otherpunctuation": "Po", "symbol": "S", "mathsymbol": "Sm", "currencysymbol": "Sc", "modifiersymbol": "Sk", "othersymbol": "So",
	"separator": "Z", "spaceseparator": "Zs", "lineseparator": "Zl", "paragraphseparator": "Zp", "other": "C", "control": "Cc",
	"format": "Cf", "surrogate": "Cs", "privateuse": "Co", "unassigned": "Cn",
}

func normPropName(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if r == ' ' || r == '_' || r == '-' {
			continue
		}
		sb.WriteRune(unicode.ToLower(r))
	}
	return sb.String()
}

func propertyFunc(name string) func(rune) bool {
	n := normPropName(name)
	if n == "" {
		return nil
	}
	// general categories by short name
	for k, tab := range unicode.Categories {
		if strings.ToLower(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	if n == "lc" || n == "l&" {
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
	}
	if long, ok := longCategoryNames[n]; ok {
		if long == "LC" {
			return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
		}
		t := unicode.Categories[long]
		return func(r rune) bool { return unicode.Is(t, r) }
	}
	switch n {
	case "any":
		return func(r rune) bool { return true }
	case "assigned":
		return func(r rune) bool { return !unicode.Is(unicode.Cn, r) && (unicode.IsGraphic(r) || unicode.IsControl(r) || unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Co, r) || unicode.Is(unicode.Mn, r)) }
	case "ascii":
		return func(r rune) bool { return r < 128 }
	case "alpha", "alphabetic":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_Alphabetic, r) }
	case "digit":
		return unicode.IsDigit
	case "alnum":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_Alphabetic, r) }
	case "upper", "uppercase":
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.Is(unicode.Other_Uppercase, r) }
	case "lower", "lowercase":
		return func(r rune) bool { return unicode.IsLower(r) || unicode.Is(unicode.Other_Lowercase, r) }
	case "space", "whitespace":
		return unicode.IsSpace
	case "punct":
		return unicode.IsPunct
	case "cntrl":
		return unicode.IsControl
	case "xdigit":
		return func(r rune) bool { return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') }
	case "hexdigit":
		return func(r rune) bool { return unicode.Is(unicode.Hex_Digit, r) }
	case "blank":
		return func(r rune) bool { return r == '\t' || unicode.Is(unicode.Zs, r) }
	case "graph":
		return func(r rune) bool { return !unicode.IsSpace(r) && !unicode.IsControl(r) && unicode.IsPrint(r) }
	case "print":
		return func(r rune) bool { return (unicode.IsPrint(r) || unicode.Is(unicode.Zs, r)) && !unicode.IsControl(r) }
	case "word":
		return isWordRune
	case "cased":
		return func(r rune) bool { return unicode.IsUpper(r) || unicode.IsLower(r) || unicode.Is(unicode.Lt, r) }
	case "emoji":
		return func(r rune) bool { return (r >= 0x1F300 && r <= 0x1FAFF) || (r >= 0x2600 && r <= 0x27BF) || r == '#' || r == '*' || (r >= '0' && r <= '9') || r == 0xA9 || r == 0xAE }
	}
	// scripts
	for k, tab := range unicode.Scripts {
		if strings.ToLower(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	if alias, ok := scriptAliases[n]; ok {
		t := unicode.Scripts[alias]
		return func(r rune) bool { return unicode.Is(t, r) }
	}
	// properties
	for k, tab := range unicode.Properties {
		if normPropName(k) == n {
			t := tab
			return func(r rune) bool { return unicode.Is(t, r) }
		}
	}
	switch n {
	case "idstart":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r) }
	case "idcontinue":
		return func(r rune) bool { return isWordRune(r) || unicode.Is(unicode.Other_ID_Continue, r) }
	}
	// blocks (subset)
	if strings.HasPrefix(n, "in") {
		if b, ok := unicodeBlocks[n[2:]]; ok {
			lo, hi := b[0], b[1]
			return func(r rune) bool { return r >= lo && r <= hi }
		}
	}
	return nil
}

var scriptAliases = map[string]string{
