	"greekandcoptic": {0x0370, 0x03FF}, "greek": {0x0370, 0x03FF}, "cyrillic": {0x0400, 0x04FF}, "hebrew": {0x0590, 0x05FF}, "arabic": {0x0600, 0x06FF},
	"cjkunifiedideographs": {0x4E00, 0x9FFF}, "hiragana": {0x3040, 0x309F}, "katakana": {0x30A0, 0x30FF}, "hangulsyllables": {0xAC00, 0xD7AF},
	"generalpunctuation": {0x2000, 0x206F}, "emoticons": {0x1F600, 0x1F64F}, "thai": {0x0E00, 0x0E7F}, "devanagari": {0x0900, 0x097F},
}

// ---- matcher ----

type reMatcher struct {
	re    *Regex
	input string
	caps  []int // 2*(ncap+1)
	steps int
	keepStart int
}

const maxRegexSteps = 50000000

func (m *reMatcher) matchAt(start int) bool {
	for i := range m.caps {
		m.caps[i] = -1
	}
	m.caps[0] = start
	m.keepStart = -1
	if m.re.findLongest {
		bestEnd := -1
		var bestCaps []int
		m.match(m.re.root, start, func(pos int) bool {
			if m.re.notEmpty && pos == start {
				return false
			}
			if pos > bestEnd {
				bestEnd = pos
				bestCaps = make([]int, len(m.caps))
				copy(bestCaps, m.caps)
				bestCaps[1] = pos
			}
			return false
		})
		if bestEnd < 0 {
			return false
		}
		copy(m.caps, bestCaps)
		return true
	}
	return m.match(m.re.root, start, func(pos int) bool {
		if m.re.notEmpty && pos == start {
			return false
		}
		m.caps[1] = pos
		if m.keepStart >= 0 {
			m.caps[0] = m.keepStart
		}
		return true
	})
}

func (m *reMatcher) runeAt(pos int) (rune, int) {
	if pos >= len(m.input) {
		return -1, 0
	}
	r, size := utf8.DecodeRuneInString(m.input[pos:])
	return r, size
}

func (m *reMatcher) runeBefore(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	r, size := utf8.DecodeLastRuneInString(m.input[:pos])
	return r, size
}

func foldEq(a, b rune) bool {
	if a == b {
		return true
	}
	for f := unicode.SimpleFold(a); f != a; f = unicode.SimpleFold(f) {
		if f == b {
			return true
		}
	}
	return false
}

func (m *reMatcher) isWordAt(pos int) bool {
	r, _ := m.runeAt(pos)
	return r >= 0 && isWordRune(r)
}
func (m *reMatcher) isWordBefore(pos int) bool {
	r, _ := m.runeBefore(pos)
	return r >= 0 && isWordRune(r)
}

func (m *reMatcher) match(n reNode, pos int, k func(int) bool) bool {
	m.steps++
	if m.steps > maxRegexSteps {
		panic(&regexError{"match-stack limit over"})
	}
	switch x := n.(type) {
	case nil, *reEmpty:
		return k(pos)
	case *reLit:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if r == x.r || (x.fold && foldEq(r, x.r)) {
			return k(pos + size)
		}
		return false
	case *reAny:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if !x.dotall && r == '\n' {
			return false
		}
		return k(pos + size)
	case *reLineBreak:
		if strings.HasPrefix(m.input[pos:], "\r\n") {
			if k(pos + 2) {
				return true
			}
		}
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if r == '\n' || r == '\v' || r == '\f' || r == '\r' || r == 0x85 || r == 0x2028 || r == 0x2029 {
			return k(pos + size)
		}
		return false
	case *reClass:
		r, size := m.runeAt(pos)
		if r < 0 {
			return false
		}
		if x.set.matches(r, x.fold) {
			return k(pos + size)
		}
		return false
	case *reStart:
		if pos == 0 || (x.multiline && m.input[pos-1] == '\n') {
			return k(pos)
		}
		return false
	case *reEnd:
		if pos == len(m.input) || (pos == len(m.input)-1 && m.input[pos] == '\n') || (x.multiline && m.input[pos] == '\n') {
			return k(pos)
		}
		return false
	case *reBufStart:
		if pos == 0 {
			return k(pos)
		}
		return false
	case *reBufEnd:
		if pos == len(m.input) {
			return k(pos)
		}
		return false
	case *reBufEndNL:
		if pos == len(m.input) || (pos == len(m.input)-1 && m.input[pos] == '\n') {
			return k(pos)
		}
		return false
	case *reWordB:
		a := m.isWordBefore(pos)
		b := m.isWordAt(pos)
		if (a != b) != x.neg {
			return k(pos)
		}
		return false
	case *reKeep:
		old := m.keepStart
		m.keepStart = pos
		if k(pos) {
			return true
		}
		m.keepStart = old
		return false
	case *reGroup:
		if x.idx == 0 {
			return m.match(x.body, pos, k)
		}
		oldS, oldE := m.caps[2*x.idx], m.caps[2*x.idx+1]
		if m.match(x.body, pos, func(e int) bool {
			ps, pe := m.caps[2*x.idx], m.caps[2*x.idx+1]
			m.caps[2*x.idx] = pos
			m.caps[2*x.idx+1] = e
			if k(e) {
				return true
			}
			m.caps[2*x.idx] = ps
			m.caps[2*x.idx+1] = pe
			return false
		}) {
			return true
		}
		m.caps[2*x.idx] = oldS
		m.caps[2*x.idx+1] = oldE
		return false
	case *reConcat:
		return m.matchSeq(x.items, 0, pos, k)
	case *reAlt:
		for _, a := range x.alts {
			if m.match(a, pos, k) {
				return true
			}
		}
		return false
	case *reRepeat:
		if x.possessive {
			// match greedily without backtracking into the repeat
			end := -1
			count := 0
			cur := pos
			for x.max < 0 || count < x.max {
				np := -1
				m.match(x.body, cur, func(e int) bool { np = e; return true })
				if np < 0 || np == cur {
					if np == cur {
						count++
					}
					break
				}
				cur = np
				count++
			}
			if count < x.min {
				return false
			}
			end = cur
			return k(end)
		}
		return m.matchRepeat(x, pos, 0, k)
	case *reBackref:
		s, e := m.caps[2*x.idx], m.caps[2*x.idx+1]
		if s < 0 || e < 0 {
			return false
		}
		sub := m.input[s:e]
		if x.fold {
			// compare rune by rune with folding
			p := pos
			for _, r := range sub {
				r2, size := m.runeAt(p)
				if r2 < 0 || !foldEq(r, r2) {
					return false
				}
				p += size
			}
			return k(p)
		}
		if strings.HasPrefix(m.input[pos:], sub) {
			return k(pos + len(sub))
		}
		return false
	case *reLook:
		if !x.behind {
			saved := make([]int, len(m.caps))
			copy(saved, m.caps)
			ok := m.match(x.body, pos, func(int) bool { return true })
			if x.neg {
				copy(m.caps, saved)
				if ok {
					return false
				}
				return k(pos)
			}
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		// lookbehind: find a start s <= pos such that body matches exactly [s, pos)
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		found := false
		for s := pos; s >= 0; s-- {
			if s < len(m.input) && s > 0 && !utf8.RuneStart(m.input[s]) {
				continue
			}
			if m.match(x.body, s, func(e int) bool { return e == pos }) {
				found = true
				break
			}
		}
		if x.neg {
			copy(m.caps, saved)
			if found {
				return false
			}
			return k(pos)
		}
		if !found {
			copy(m.caps, saved)
			return false
		}
		if k(pos) {
			return true
		}
		copy(m.caps, saved)
		return false
	case *reAtomic:
		end := -1
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		if !m.match(x.body, pos, func(e int) bool { end = e; return true }) {
			copy(m.caps, saved)
			return false
		}
		if k(end) {
			return true
		}
		copy(m.caps, saved)
		return false
	}
	panic(fmt.Sprintf("regex: unknown node %T", n))
}

func (m *reMatcher) matchSeq(items []reNode, i int, pos int, k func(int) bool) bool {
	if i >= len(items) {
		return k(pos)
	}
	return m.match(items[i], pos, func(np int) bool {
		return m.matchSeq(items, i+1, np, k)
	})
}

func (m *reMatcher) matchRepeat(x *reRepeat, pos int, count int, k func(int) bool) bool {
	canStop := count >= x.min
	canMore := x.max < 0 || count < x.max
	tryMore := func() bool {
		if !canMore {
			return false
		}
		return m.match(x.body, pos, func(np int) bool {
			if np == pos && count >= x.min {
				// empty iteration: don't loop forever
				return false
			}
			return m.matchRepeat(x, np, count+1, k)
		})
	}
	if x.greedy {
		if tryMore() {
			return true
		}
		if canStop {
			return k(pos)
		}
		return false
	}
	if canStop && k(pos) {
		return true
	}
	return tryMore()
}

// ---- jq interface ----

func cpOffset(s string, bytePos int) int {
	// count characters starting before bytePos (jq counts decode lengths until >= bytePos)
	n := 0
	i := 0
	for i < bytePos && i < len(s) {
		_, size := utf8.DecodeRuneInString(s[i:])
		i += size
		n++
	}
	return n
}

func matchImpl(input Value, reV Value, flagsV Value, testV Value) (Value, error) {
	s, ok := input.(string)
	if !ok {
		return nil, typeErr(input, "cannot be matched, as it is not a string")
	}
	pattern, ok := reV.(string)
	if !ok {
		return nil, typeErr(reV, "is not a string")
	}
	flags := ""
	if flagsV != nil {
		fs, ok := flagsV.(string)
		if !ok {
			return nil, typeErr(flagsV, "is not a string")
		}
		flags = fs
	}
	global := strings.Contains(flags, "g")
	test := truthy(testV)
	re, err := compileRegex(pattern, flags)
	if err != nil {
		if strings.HasSuffix(err.Error(), "is not a valid modifier string") {
			return nil, &JQError{Val: err.Error()}
		}
		return nil, newError("Regex failure: %s", err.Error())
	}
	m := &reMatcher{re: re, input: s, caps: make([]int, 2*(re.ncap+1))}
	results := []Value{}
	start := 0
	var merr error
	func() {
		defer func() {
			if r := recover(); r != nil {
				if e, ok := r.(*regexError); ok {
					merr = newError("Regex failure: %s", e.msg)
					return
				}
				panic(r)
			}
		}()
		for start <= len(s) {
			found := false
			var mstart int
			for mstart = start; mstart <= len(s); mstart++ {
				if m.matchAt(mstart) {
					found = true
					break
				}
			}
			if !found {
				break
			}
			if test {
				results = append(results, true)
				return
			}
			mb, me := m.caps[0], m.caps[1]
			results = append(results, buildMatch(s, m, re))
			if me == mb {
				start = me + 1
			} else {
				start = me
			}
			if !global {
				break
			}
		}
	}()
	if merr != nil {
		return nil, merr
	}
	if test {
		return len(results) > 0, nil
	}
	return results, nil
}

func buildMatch(s string, m *reMatcher, re *Regex) Value {
	mb, me := m.caps[0], m.caps[1]
	obj := NewObject()
	off := cpOffset(s, mb)
	matched := ""
	if mb <= me && me <= len(s) {
		matched = s[mb:me]
	}
	obj.SetInPlace("offset", float64(off))
	obj.SetInPlace("length", float64(utf8.RuneCountInString(matched)))
	obj.SetInPlace("string", matched)
	caps := []Value{}
	for i := 1; i <= re.ncap; i++ {
		c := NewObject()
		cs, ce := m.caps[2*i], m.caps[2*i+1]
		var name Value
		if re.names[i] != "" {
			name = re.names[i]
		}
		if cs < 0 || ce < 0 {
			c.SetInPlace("offset", float64(-1))
			c.SetInPlace("string", nil)
			c.SetInPlace("length", float64(0))
			c.SetInPlace("name", name)
		} else {
			sub := s[cs:ce]
			c.SetInPlace("offset", float64(cpOffset(s, cs)))
			c.SetInPlace("length", float64(utf8.RuneCountInString(sub)))
			c.SetInPlace("string", sub)
			c.SetInPlace("name", name)
		}
		caps = append(caps, c)
	}
	obj.SetInPlace("captures", caps)
	return obj
}
