)

const jqVersion = "build-f77602d"

const usageText = `Usage:	jq [options] <jq filter> [file...]
	jq [options] --args <jq filter> [strings...]
	jq [options] --jsonargs <jq filter> [JSON_TEXTS...]

jq is a tool for processing JSON inputs, applying the given filter to
its JSON text inputs and producing the filter's results as JSON on
standard output.

The simplest filter is ., which copies jq's input to its output
unmodified except for formatting. For more advanced filters see
the jq(1) manpage ("man jq") and/or https://jqlang.org/.

Example:

	$ echo '{"foo": 0}' | jq .
	{
	  "foo": 0
	}
`

const usageOptions = `
Command options:
  -n, --null-input          use ` + "`null`" + ` as the single input value;
  -R, --raw-input           read each line as string instead of JSON;
  -s, --slurp               read all inputs into an array and use it as
                            the single input value;
  -c, --compact-output      compact instead of pretty-printed output;
  -r, --raw-output          output strings without escapes and quotes;
      --raw-output0         implies -r and output NUL after each output;
  -j, --join-output         implies -r and output without newline after
                            each output;
  -a, --ascii-output        output strings by only ASCII characters
                            using escape sequences;
  -S, --sort-keys           sort keys of each object on output;
  -C, --color-output        colorize JSON output;
  -M, --monochrome-output   disable colored output;
      --tab                 use tabs for indentation;
      --indent n            use n spaces for indentation (max 7 spaces);
      --unbuffered          flush output stream after each output;
      --stream              parse the input value in streaming fashion;
      --stream-errors       implies --stream and report parse error as
                            an array;
      --seq                 parse input/output as application/json-seq;
  -f, --from-file           load the filter from a file;
  -L, --library-path dir    search modules from the directory;
      --arg name value      set $name to the string value;
      --argjson name value  set $name to the JSON value;
      --slurpfile name file set $name to an array of JSON values read
                            from the file;
      --rawfile name file   set $name to string contents of file;
      --args                consume remaining arguments as positional
                            string values;
      --jsonargs            consume remaining arguments as positional
                            JSON values;
  -e, --exit-status         set exit status code based on the output;
  -V, --version             show the version;
  --build-configuration     show jq's build configuration;
  -h, --help                show the help;
  --                        terminates argument processing;

Named arguments are also available as $ARGS.named[], while
positional arguments are available as $ARGS.positional[].
`

var stdoutW *bufio.Writer

func usage(code int, keepItShort bool) {
	w := os.Stdout
	if code != 0 {
		w = os.Stderr
	}
	fmt.Fprintf(w, "jq - commandline JSON processor [version %s]\n\n%s", jqVersion, usageText)
	if keepItShort {
		fmt.Fprintf(w, "\nFor listing the command options, use jq --help.\n")
	} else {
		fmt.Fprint(w, usageOptions)
	}
	os.Exit(code)
}

func die() {
	fmt.Fprintf(os.Stderr, "Use %s --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", "jq")
	os.Exit(2)
}

type options struct {
	nullInput    bool
	rawInput     bool
	slurp        bool
	rawOutput    bool
	rawOutput0   bool
	joinOutput   bool
	ascii        bool
	sortKeys     bool
	color        bool
	colorSet     bool
	mono         bool
	tab          bool
	indent       int
	pretty       bool
	unbuffered   bool
	stream       bool
	streamErrors bool
	seq          bool
	fromFile     bool
	exitStatus   bool
	libPaths     []string
}

func main() {
	debug.SetMaxStack(2 << 30)
	debug.SetGCPercent(400)
	os.Exit(realMain())
}

func realMain() int {
	args := os.Args[1:]
	opts := options{indent: 2, pretty: true}
	var program string
	haveProgram := false
	var inputFiles []string
	namedArgs := NewObject()
	posArgs := []Value{}
	argsMode := 0 // 0 none, 1 --args, 2 --jsonargs
	argsDone := false
	stdoutW = bufio.NewWriterSize(os.Stdout, 65536)
	defer stdoutW.Flush()

	isOptArg := func(s string) bool { return len(s) >= 2 && s[0] == '-' }

	for i := 0; i < len(args); i++ {
		text := args[i]
		if argsDone || !isOptArg(text) {
			if !haveProgram {
				program = text
				haveProgram = true
			} else if argsMode == 1 {
				posArgs = append(posArgs, text)
			} else if argsMode == 2 {
				v, err := parseJSONOne(text)
				if err != nil {
					fmt.Fprintf(os.Stderr, "jq: invalid JSON text passed to --jsonargs\n")
					die()
				}
				posArgs = append(posArgs, v)
			} else {
				inputFiles = append(inputFiles, text)
			}
			continue
		}
		if text == "--" {
			argsDone = true
			continue
		}
		if text[1] != '-' {
			// short options cluster
			shortOpts := 0
			matched := func(c byte) bool {
				if strings.IndexByte(text, c) >= 0 {
					shortOpts++
					return true
				}
				return false
			}
			// -L with attached value
			if text[1] == 'L' {
				if len(text) > 2 {
					opts.libPaths = append(opts.libPaths, text[2:])
				} else {
					if i >= len(args)-1 {
						fmt.Fprintf(os.Stderr, "-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n")
						die()
					}
					opts.libPaths = append(opts.libPaths, args[i+1])
					i++
				}
				continue
			}
			if matched('s') {
				opts.slurp = true
			}
			if matched('r') {
				opts.rawOutput = true
			}
			if matched('j') {
				opts.rawOutput = true
				opts.joinOutput = true
			}
			if matched('c') {
				opts.pretty = false
				opts.tab = false
			}
			if matched('n') {
				opts.nullInput = true
			}
			if matched('f') {
				opts.fromFile = true
			}
			if matched('a') {
				opts.ascii = true
			}
			if matched('S') {
				opts.sortKeys = true
			}
			if matched('C') {
				opts.color = true
				opts.colorSet = true
			}
			if matched('M') {
				opts.color = false
				opts.colorSet = true
			}
			if matched('R') {
				opts.rawInput = true
			}
			if matched('e') {
				opts.exitStatus = true
			}
			if matched('h') {
				usage(0, false)
			}
			if matched('V') {
				fmt.Fprintf(stdoutW, "jq-%s\n", jqVersion)
				stdoutW.Flush()
				return 0
			}
			if matched('b') {
				// binary: no-op on unix
			}
			if shortOpts != len(text)-1 {
				fmt.Fprintf(os.Stderr, "jq: Unknown option %s\n", text)
				die()
			}
			continue
		}
		switch text {
		case "--slurp":
			opts.slurp = true
		case "--raw-output":
			opts.rawOutput = true
		case "--raw-output0":
			opts.rawOutput = true
			opts.joinOutput = true
			opts.rawOutput0 = true
		case "--join-output":
			opts.rawOutput = true
			opts.joinOutput = true
		case "--compact-output":
			opts.pretty = false
			opts.tab = false
		case "--null-input":
			opts.nullInput = true
		case "--from-file":
			opts.fromFile = true
		case "--library-path":
			if i >= len(args)-1 {
				fmt.Fprintf(os.Stderr, "-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n")
				die()
			}
			opts.libPaths = append(opts.libPaths, args[i+1])
			i++
		case "--ascii-output":
			opts.ascii = true
		case "--sort-keys":
			opts.sortKeys = true
		case "--color-output":
			opts.color = true
			opts.colorSet = true
		case "--monochrome-output":
			opts.color = false
			opts.colorSet = true
		case "--raw-input":
			opts.rawInput = true
		case "--exit-status":
			opts.exitStatus = true
		case "--tab":
			opts.tab = true
			opts.pretty = true
		case "--indent":
			if i >= len(args)-1 {
				fmt.Fprintf(os.Stderr, "jq: --indent takes one parameter\n")
				die()
			}
			n, err := strconv.Atoi(args[i+1])
			if err != nil {
				// atoi semantics: leading number
				n = atoi(args[i+1])
			}
			if n < -1 || n > 7 {
				fmt.Fprintf(os.Stderr, "jq: --indent takes a number between -1 and 7\n")
				die()
			}
			opts.pretty = true
			if n == -1 {
				opts.tab = true
			} else {
				opts.tab = false
				opts.indent = n
			}
			i++
		case "--unbuffered":
			opts.unbuffered = true
		case "--stream":
			opts.stream = true
		case "--stream-errors":
			opts.stream = true
			opts.streamErrors = true
		case "--seq":
			opts.seq = true
		case "--args":
			argsMode = 1
		case "--jsonargs":
			argsMode = 2
		case "--arg":
			if i >= len(args)-2 {
				fmt.Fprintf(os.Stderr, "jq: --arg takes two parameters (e.g. --arg varname value)\n")
				die()
			}
			if !namedArgs.Has(args[i+1]) {
				namedArgs.SetInPlace(args[i+1], sanitizeUTF8(args[i+2]))
			}
			i += 2
		case "--argjson":
			if i >= len(args)-2 {
				fmt.Fprintf(os.Stderr, "jq: --argjson takes two parameters (e.g. --argjson varname text)\n")
				die()
			}
			v, err := parseJSONOne(args[i+2])
			if err != nil {
				fmt.Fprintf(os.Stderr, "jq: invalid JSON text passed to --argjson\n")
				die()
			}
			if !namedArgs.Has(args[i+1]) {
				namedArgs.SetInPlace(args[i+1], v)
			}
			i += 2
		case "--slurpfile", "--rawfile":
			which := text[2:]
			if i >= len(args)-2 {
				fmt.Fprintf(os.Stderr, "jq: --%s takes two parameters (e.g. --%s varname filename)\n", which, which)
				die()
			}
			raw := which == "rawfile"
			data, err := loadFile(args[i+2], raw)
			if err != nil {
				fmt.Fprintf(os.Stderr, "jq: Bad JSON in --%s %s %s: %s\n", which, args[i+1], args[i+2], err.Error())
				return 2
			}
			if !namedArgs.Has(args[i+1]) {
				namedArgs.SetInPlace(args[i+1], data)
			}
			i += 2
		case "--debug-dump-disasm", "--debug-trace", "--debug-trace=all":
		case "--help":
			usage(0, false)
		case "--version":
			fmt.Fprintf(stdoutW, "jq-%s\n", jqVersion)
			stdoutW.Flush()
			return 0
		case "--build-configuration":
			fmt.Fprintf(stdoutW, "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local\n")
			stdoutW.Flush()
			return 0
		default:
			fmt.Fprintf(os.Stderr, "jq: Unknown option %s\n", text)
			die()
		}
	}

	if !haveProgram {
		if !isTerminal(os.Stdout) || !isTerminal(os.Stdin) {
			program = "."
			haveProgram = true
		} else {
			usage(2, true)
		}
	}

	if !opts.colorSet {
		opts.color = isTerminal(os.Stdout)
	}
	colors := defaultColors
	if opts.color {
		if spec, ok := os.LookupEnv("JQ_COLORS"); ok {
			cs, ok := parseColors(spec)
			if !ok {
				fmt.Fprintf(os.Stderr, "Failed to set $JQ_COLORS\n")
			} else {
				colors = cs
			}
		}
	}

	progOrigin := ""
	if opts.fromFile {
		data, err := os.ReadFile(program)
		if err != nil {
			fmt.Fprintf(os.Stderr, "jq: Could not open %s: %s\n", program, errnoString(err))
			return 2
		}
		absDir, _ := filepath.Abs(filepath.Dir(program))
		progOrigin = absDir
		program = string(data)
	} else {
		cwd, _ := os.Getwd()
		progOrigin = cwd
	}
	program = sanitizeUTF8(program)

	// environment
	envObj := NewObject()
	for _, e := range os.Environ() {
		if k, v, ok := strings.Cut(e, "="); ok {
			envObj.SetInPlace(sanitizeUTF8(k), sanitizeUTF8(v))
		}
	}
	argsObj := NewObject()
	argsObj.SetInPlace("positional", posArgs)
	argsObj.SetInPlace("named", namedArgs)

	jqOrigin := "."
	if exe, err := os.Executable(); err == nil {
		jqOrigin = filepath.Dir(exe)
	}
	if d := filepath.Dir(os.Args[0]); d != "" {
		jqOrigin = d
	}

	interp := &Interp{envObj: envObj, namedArgs: namedArgs, posArgs: posArgs, progOrigin: progOrigin, jqOrigin: jqOrigin}
	interp.stderr = func(s string) {
		stdoutW.Flush()
		os.Stderr.WriteString(s)
	}
	var searchList []Value
	if len(opts.libPaths) > 0 {
		for _, p := range opts.libPaths {
			searchList = append(searchList, p)
		}
	} else {
		searchList = []Value{"~/.jq", "$ORIGIN/../lib/jq", "$ORIGIN/../lib"}
	}
	interp.searchList = searchList
	loader := newModuleLoader(interp, opts.libPaths, progOrigin)
	interp.loader = loader

	// globals
	globals := map[string]Value{"ENV": envObj, "ARGS": argsObj}
	for i, k := range namedArgs.keys {
		if _, exists := globals[k]; !exists || true {
			globals[k] = namedArgs.vals[i]
		}
	}

	prog, cerrs := compileMain(interp, program, globals)
	if len(cerrs) > 0 {
		for _, e := range cerrs {
			fmt.Fprintln(os.Stderr, formatCompileError(program, "<top-level>", e))
		}
		if len(cerrs) == 1 {
			fmt.Fprintf(os.Stderr, "jq: 1 compile error\n")
		} else {
			fmt.Fprintf(os.Stderr, "jq: %d compile errors\n", len(cerrs))
		}
		return 3
	}

	popts := &PrintOpts{Pretty: opts.pretty, Indent: opts.indent, Tab: opts.tab, SortKeys: opts.sortKeys, ASCII: opts.ascii, Color: opts.color, Colors: &colors}

	// input
	inputs := newInputState(inputFiles, opts, interp)
	interp.inputs = inputs
	interp.nullInput = opts.nullInput

	ret := 0
	lastResult := -1
	exitNow := false
	exitCode := 0

	process := func(v Value) int {
		pret := -4 // no output
		err := interp.run(prog, v, func(result Value) error {
			if opts.rawOutput {
				if s, ok := result.(string); ok {
					if opts.ascii {
						var sb strings.Builder
						writeJSONString(&sb, s, true)
						stdoutW.WriteString(sb.String())
					} else if opts.rawOutput0 && strings.IndexByte(s, 0) >= 0 {
						return &JQError{Val: "Cannot dump a string containing NUL with --raw-output0 option"}
					} else {
						stdoutW.WriteString(s)
					}
					pret = 0
					goto tail
				}
			}
			if result == nil || result == false {
				pret = -1
			} else {
				pret = 0
			}
			if opts.seq {
				stdoutW.WriteByte(0x1e)
			}
			stdoutW.WriteString(popts.Dump(result))
		tail:
			if !opts.joinOutput {
				stdoutW.WriteByte('\n')
			}
			if opts.rawOutput0 {
				stdoutW.WriteByte(0)
			}
			if opts.unbuffered {
				stdoutW.Flush()
			}
			return nil
		})
		if err != nil {
			switch e := err.(type) {
			case *HaltError:
				exitNow = true
				if e.Has {
					if s, ok := e.Val.(string); ok {
						stdoutW.Flush()
						os.Stderr.WriteString(s)
					} else if e.Val == nil {
					} else {
						stdoutW.Flush()
						fmt.Fprintf(os.Stderr, "%s\n", toJSON(e.Val))
					}
				}
				return e.Code
			case *JQError:
				stdoutW.Flush()
				pos := inputs.position()
				if s, ok := e.Val.(string); ok {
					fmt.Fprintf(os.Stderr, "jq: error (at %s): %s\n", pos, s)
				} else {
					fmt.Fprintf(os.Stderr, "jq: error (at %s) (not a string): %s\n", pos, toJSON(e.Val))
				}
				return 5
			case *BreakError:
				stdoutW.Flush()
				fmt.Fprintf(os.Stderr, "jq: error (at %s): break\n", inputs.position())
				return 5
			default:
				stdoutW.Flush()
				fmt.Fprintf(os.Stderr, "jq: error (at %s): %s\n", inputs.position(), err.Error())
				return 5
			}
		}
		return pret
	}

	if opts.nullInput {
		ret = process(nil)
		if exitNow {
			exitCode = ret
		}
	} else {
		for !exitNow {
			if inputs.hadError() {
				break
			}
			v, ok, err := inputs.Next()
			if err != nil {
				msg := err.Error()
				if !opts.seq {
					ret = 5
					stdoutW.Flush()
					fmt.Fprintf(os.Stderr, "jq: parse error: %s\n", msg)
					break
				}
				stdoutW.Flush()
				fmt.Fprintf(os.Stderr, "jq: ignoring parse error: %s\n", msg)
				continue
			}
			if !ok {
				break
			}
			ret = process(v)
			if exitNow {
				exitCode = ret
				break
			}
			if ret <= 0 && ret != -4 {
				if ret == -1 {
					lastResult = 0
				} else {
					lastResult = 1
				}
			}
		}
	}
	if exitNow {
		stdoutW.Flush()
		if exitCode < 0 {
			return 0
		}
		return exitCode & 0xff
	}
	if inputs.hadError() {
		ret = 2
	}
	stdoutW.Flush()
	if opts.exitStatus {
		if ret != -4 {
			if ret < 0 {
				return -ret
			}
			return ret
		}
		switch lastResult {
		case -1:
			return 4
		case 0:
			return 1
		default:
			return 0
		}
	}
	if ret < 0 {
		return 0
	}
	return ret
}

func atoi(s string) int {
	n := 0
	i := 0
	neg := false
	for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
		i++
	}
	if i < len(s) && (s[i] == '-' || s[i] == '+') {
		neg = s[i] == '-'
		i++
	}
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		n = n*10 + int(s[i]-'0')
		i++
	}
	if neg {
		return -n
	}
	return n
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func errnoString(err error) string {
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	s := err.Error()
	// capitalize like strerror
	switch s {
	case "no such file or directory":
		return "No such file or directory"
	case "is a directory":
		return "Is a directory"
	case "permission denied":
		return "Permission denied"
	}
	if len(s) > 0 {
		return strings.ToUpper(s[:1]) + s[1:]
	}
	return s
}

// loadFile implements jv_load_file: raw -> string; else array of parsed values.
func loadFile(name string, raw bool) (Value, error) {
	fi, err := os.Stat(name)
	if err == nil && fi.IsDir() {
		return nil, fmt.Errorf("Could not open %s: It's a directory", name)
	}
	data, err := os.ReadFile(name)
	if err != nil {
		return nil, fmt.Errorf("Could not open %s: %s", name, errnoString(err))
	}
	if raw {
		return sanitizeUTF8(string(data)), nil
	}
	vals, err := parseJSONAll(string(data))
	if err != nil {
		return nil, err
	}
	if vals == nil {
		vals = []Value{}
	}
	return vals, nil
}

// ---- compile & run ----

type compiledProgram struct {
	body Node
	env  *Frame
}

func compileMain(in *Interp, src string, globals map[string]Value) (*compiledProgram, []CompileError) {
	prog, errs := ParseProgram(src, "<top-level>")
	if len(errs) > 0 {
		return nil, errs
	}
	c := &Compiler{natives: natives, src: src, fname: "<top-level>"}
	// root scope with globals
	root := &scope{}
	rootFrame := &Frame{}
	for k, v := range globals {
		root.vars = append(root.vars, k)
		rootFrame.vars = append(rootFrame.vars, v)
	}
	// prelude
	preludeScope, preludeFrame := in.loader.preludeEnv(c, root, rootFrame)
	if len(c.errors) > 0 {
		return nil, c.errors
	}
	// imports / includes
	progScope, progFrame, ierrs := in.loader.resolveImports(c, prog, preludeScope, preludeFrame, progOriginDir(in), true)
	if len(ierrs) > 0 {
		return nil, ierrs
	}
	if prog.Body == nil {
		prog.Body = IdentityNode{}
	}
	c.resolve(prog.Body, progScope)
	if len(c.errors) > 0 {
		return nil, c.errors
	}
	return &compiledProgram{body: prog.Body, env: progFrame}, nil
}

func progOriginDir(in *Interp) string { return in.progOrigin }

func (in *Interp) run(p *compiledProgram, input Value, out func(Value) error) error {
	return in.eval(p.body, p.env, input, nil, func(v Value, _ *pathT) error {
		return out(v)
	})
}

// ---- input handling ----

type inputState struct {
	files     []string
	idx       int
	cur       *bufio.Reader
	curFile   *os.File
	curName   string
	curLine   int
	opened    bool
	parser    *JSONParser
	opts      options
	errors    int
	done      bool
	rawBuf    []byte
	slurped   []Value
	slurpDone bool
	rawSlurp  strings.Builder
	in        *Interp
	eofAll    bool
}

func newInputState(files []string, opts options, in *Interp) *inputState {
	s := &inputState{files: files, opts: opts, in: in}
	if !opts.rawInput {
		s.parser = NewJSONParser(opts.stream, opts.seq, opts.streamErrors)
	}
	return s
}

func (s *inputState) hadError() bool { return s.errors > 0 }

func (s *inputState) position() string {
	if !s.opened {
		return "<unknown>"
	}
	return fmt.Sprintf("%s:%d", s.curName, s.curLine)
}

func (s *inputState) CurrentFilename() Value {
	if !s.opened || s.curName == "<stdin>" && len(s.files) == 0 {
		if s.opened && s.curName == "<stdin>" {
			return nil
		}
		return nil
	}
	return s.curName
}

func (s *inputState) CurrentLine() int { return s.curLine }

// openNext opens the next input file. Returns false when none left.
func (s *inputState) openNext() bool {
	if s.curFile != nil {
		if s.curFile != os.Stdin {
			s.curFile.Close()
		}
		s.curFile = nil
		s.cur = nil
	}
	for {
		if len(s.files) == 0 {
			if s.opened {
				return false
			}
			s.opened = true
			s.curName = "<stdin>"
			s.curFile = os.Stdin
			s.cur = bufio.NewReaderSize(os.Stdin, 65536)
			s.curLine = 0
			return true
		}
		if s.idx >= len(s.files) {
			return false
		}
		name := s.files[s.idx]
		s.idx++
		if name == "-" {
			s.opened = true
			s.curName = "<stdin>"
			s.curFile = os.Stdin
			s.cur = bufio.NewReaderSize(os.Stdin, 65536)
			s.curLine = 0
			return true
		}
		f, err := os.Open(name)
		if err != nil {
			stdoutW.Flush()
			fmt.Fprintf(os.Stderr, "jq: error: Could not open file %s: %s\n", name, errnoString(err))
			s.errors++
			continue
		}
		if fi, err := f.Stat(); err == nil && fi.IsDir() {
			stdoutW.Flush()
			fmt.Fprintf(os.Stderr, "jq: error: Is a directory\n")
			s.errors++
			f.Close()
			continue
		}
		s.opened = true
		s.curName = name
		s.curFile = f
		s.cur = bufio.NewReaderSize(f, 65536)
		s.curLine = 0
		return true
	}
}

// readChunk reads a chunk like fgets(buf, 4096): up to 4095 bytes or through newline.
// Returns chunk, isLast (no more data in any file).
func (s *inputState) readChunk() ([]byte, bool, bool) {
	for {
		if s.cur == nil {
			if !s.openNext() {
				return nil, true, false
			}
		}
		chunk := make([]byte, 0, 256)
		for len(chunk) < 4095 {
			b, err := s.cur.ReadByte()
			if err != nil {
				break
			}
			chunk = append(chunk, b)
			if b == '\n' {
				break
			}
		}
		if len(chunk) == 0 {
			// EOF on this file
			if !s.openNext() {
				return nil, true, false
			}
			continue
		}
		hasNL := chunk[len(chunk)-1] == '\n'
		if hasNL {
			s.curLine++
		}
		// determine if more data exists
		more := true
		if _, err := s.cur.Peek(1); err != nil {
			// this file exhausted; check for further files
			more = s.idx < len(s.files)
			if more {
				// there might be unopenable files; we can't know, assume more
			}
		}
		return chunk, !more, hasNL
	}
}

// Next returns the next input value.
func (s *inputState) Next() (Value, bool, error) {
	if s.done {
		return nil, false, nil
	}
	if s.opts.rawInput {
		return s.nextRaw()
	}
	if s.opts.slurp {
		if s.slurpDone {
			s.done = true
			return nil, false, nil
		}
		arr := []Value{}
		for {
			v, ok, err := s.nextJSON()
			if err != nil {
				return nil, false, err
			}
			if !ok {
				break
			}
			arr = append(arr, v)
		}
		s.slurpDone = true
		return arr, true, nil
	}
	return s.nextJSON()
}

func (s *inputState) nextJSON() (Value, bool, error) {
	for {
		v, ok, err := s.parser.Next()
		if err != nil {
			return nil, false, err
		}
		if ok {
			return v, true, nil
		}
		if s.parser.eof {
			s.done = true
			return nil, false, nil
		}
		if s.parser.RemainingBuffer() {
			continue
		}
		chunk, isLast, hasNL := s.readChunk()
		if chunk == nil {
			// no more data: signal EOF to parser
			s.parser.SetBuf([]byte{}, false)
			continue
		}
		if !hasNL {
			// fgets/strlen quirk: truncate at NUL when no newline in chunk
			if k := indexByte(chunk, 0); k >= 0 {
				chunk = chunk[:k]
			}
		}
		s.parser.SetBuf(chunk, !isLast)
	}
}

func indexByte(b []byte, c byte) int {
	for i, x := range b {
		if x == c {
			return i
		}
	}
	return -1
}

func (s *inputState) nextRaw() (Value, bool, error) {
	if s.opts.slurp {
		if s.slurpDone {
			s.done = true
			return nil, false, nil
		}
		var sb strings.Builder
		for {
			chunk, _, _ := s.readChunk()
			if chunk == nil {
				break
			}
			sb.Write(chunk)
		}
		s.slurpDone = true
		return sanitizeUTF8(sb.String()), true, nil
	}
	var line []byte
	for {
		chunk, _, hasNL := s.readChunk()
		if chunk == nil {
			if len(line) == 0 {
				s.done = true
				return nil, false, nil
			}
			return sanitizeUTF8(string(line)), true, nil
		}
		line = append(line, chunk...)
		if hasNL {
			return sanitizeUTF8(string(line[:len(line)-1])), true, nil
		}
	}
}

