func (ml *ModuleLoader) loadModule(c *Compiler, path string, parentScope *scope, parentFrame *Frame) (*loadedModule, []CompileError) {
	if m, ok := ml.cache[path]; ok {
		return m, nil
	}
	if ml.loading[path] {
		return nil, []CompileError{{Msg: "circular import: " + path, Pos: -1}}
