	if prog.Body != nil {
		// must be only defs
		var rest Node = prog.Body
		for {
			fd, ok := rest.(*FuncDefNode)
			if !ok {
				break
			}
			rest = fd.Rest
		}
		if rest != nil {
			return nil, []CompileError{{Msg: fmt.Sprintf("jq: error: library should only have function definitions, not a main expression"), Pos: -1}}
		}
	}
	ms, mf, ierrs := ml.resolveImports(c, prog, parentScope, parentFrame, filepath.Dir(path), false)
	if len(ierrs) > 0 {
		return nil, ierrs
	}
	m := &loadedModule{path: path, prog: prog, scope: ms, frame: mf, meta: prog.ModuleMeta}
	if prog.Body != nil {
		addDefs(prog.Body, ms, mf, "")
	}
	ml.cache[path] = m
	return m, nil
}

// resolveImports processes the imports of prog, returning the scope/frame in which the body should be compiled.
func (ml *ModuleLoader) resolveImports(c *Compiler, prog *Program, parentScope *scope, parentFrame *Frame, originDir string, isMain bool) (*scope, *Frame, []CompileError) {
	ms := newScope(parentScope)
	mf := &Frame{parent: parentFrame}
	var errs []CompileError
	imports := prog.Imports
	if isMain {
		// auto-include ~/.jq if it is a file
		if home, err := os.UserHomeDir(); err == nil {
			p := filepath.Join(home, ".jq")
			if fileExists(p) {
				imports = append([]*ImportDecl{{Path: p, Include: true}}, imports...)
			}
		}
	}
	for _, imp := range imports {
		if imp.IsData {
			path, ok := ml.findModule(imp.Path, ".json", imp.Meta, originDir)
			if !ok {
				errs = append(errs, CompileError{Msg: fmt.Sprintf("module not found: %s\n", imp.Path), Pos: -1})
				continue
			}
			vals, err := loadFile(path, false)
			if err != nil {
				errs = append(errs, CompileError{Msg: fmt.Sprintf("jq: error loading data file %s: %s", imp.Path, err.Error()), Pos: -1})
				continue
			}
			ms.vars = append(ms.vars, imp.Alias)
			mf.vars = append(mf.vars, vals)
			ms.vars = append(ms.vars, imp.Alias+"::"+imp.Alias)
			mf.vars = append(mf.vars, vals)
			continue
		}
		var path string
		var ok bool
		if filepath.IsAbs(imp.Path) && fileExists(imp.Path) {
			path, ok = imp.Path, true
		} else {
			path, ok = ml.findModule(imp.Path, ".jq", imp.Meta, originDir)
		}
		if !ok {
			errs = append(errs, CompileError{Msg: fmt.Sprintf("module not found: %s\n", imp.Path), Pos: -1})
			continue
		}
		var mod *loadedModule
		var merrs []CompileError
		if imp.Include {
			// compile the included module in the current scope chain so it sees earlier includes
			mod, merrs = ml.loadModuleUncached(c, path, ms, mf)
		} else {
			mod, merrs = ml.loadModule(c, path, ml.preludeScope, ml.preludeFrame)
		}
		if len(merrs) > 0 {
			errs = append(errs, merrs...)
			continue
		}
		prefix := ""
		if !imp.Include {
			prefix = imp.Alias + "::"
		}
		// copy the module's own defs (not its imports) into our scope
		for i, fe := range mod.scope.funcs {
			if fe.def == nil {
				continue
			}
			if strings.Contains(fe.name, "::") {
				continue
			}
			ms.funcs = append(ms.funcs, funcEntry{name: prefix + fe.name, arity: fe.arity, def: fe.def})
			mf.funcs = append(mf.funcs, mod.frame.funcs[i])
		}
	}
	return ms, mf, errs
}

func (ml *ModuleLoader) loadModuleUncached(c *Compiler, path string, parentScope *scope, parentFrame *Frame) (*loadedModule, []CompileError) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, []CompileError{{Msg: fmt.Sprintf("Could not open %s: %s", path, errnoString(err)), Pos: -1}}
	}
	src := sanitizeUTF8(string(data))
	prog, errs := ParseProgram(src, path)
	if len(errs) > 0 {
		var out []CompileError
		for _, e := range errs {
			out = append(out, CompileError{Msg: formatCompileError(src, path, e)[len("jq: error: "):], Pos: -1})
		}
		return nil, out
	}
	ms, mf, ierrs := ml.resolveImports(c, prog, parentScope, parentFrame, filepath.Dir(path), false)
	if len(ierrs) > 0 {
		return nil, ierrs
	}
	m := &loadedModule{path: path, prog: prog, scope: ms, frame: mf, meta: prog.ModuleMeta}
	if prog.Body != nil {
		addDefs(prog.Body, ms, mf, "")
	}
	return m, nil
}

// moduleMeta implements the modulemeta builtin.
func (ml *ModuleLoader) moduleMeta(name string) (Value, error) {
	path, ok := ml.findModule(name, ".jq", nil, ml.progOrigin)
	if !ok {
		return nil, newError("module not found: %s", name)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, newError("module not found: %s", name)
	}
	src := sanitizeUTF8(string(data))
	prog, errs := ParseProgram(src, path)
	if len(errs) > 0 {
		return nil, newError("%s", errs[0].Msg)
	}
	out := NewObject()
	if prog.ModuleMeta != nil {
		for i, k := range prog.ModuleMeta.keys {
			out.SetInPlace(k, prog.ModuleMeta.vals[i])
		}
	}
	deps := []Value{}
	for _, imp := range prog.Imports {
		d := NewObject()
		if imp.Meta != nil {
			for i, k := range imp.Meta.keys {
				d.SetInPlace(k, imp.Meta.vals[i])
			}
		}
		if !imp.Include {
			d.SetInPlace("as", imp.Alias)
		}
		d.SetInPlace("is_data", imp.IsData)
		d.SetInPlace("relpath", imp.Path)
		deps = append(deps, d)
	}
	out.SetInPlace("deps", deps)
	defs := []Value{}
	var rest Node = prog.Body
	for {
		fd, ok := rest.(*FuncDefNode)
		if !ok {
			break
		}
		defs = append(defs, fmt.Sprintf("%s/%d", fd.Def.Name, len(fd.Def.Params)))
		rest = fd.Rest
	}
	out.SetInPlace("defs", defs)
	return out, nil
}
