{"command":"cd /workspace && python3 - <<'EOF'
s=open('/workspace/value.go').read()
start=s.index("type Object struct {")
end=s.index("// ---- kinds ----")
new='''// Object is an insertion-ordered map with persistent (copy-on-write) semantics.
// Multiple Object versions may share one store as prefixes; appending a new key to the
// latest version is O(1) amortized.
type objStore struct {
	keys []string
	vals []Value
	idx  map[string]int // built lazily when large
}

type Object struct {
	st *objStore
	n  int
}

const objIdxThreshold = 8

func NewObject() *Object { return &Object{st: &objStore{}} }

func (o *Object) Len() int { return o.n }

func (o *Object) Keys() []string { return o.st.keys[:o.n] }
func (o *Object) Vals() []Value  { return o.st.vals[:o.n] }

func (st *objStore) ensureIdx() {
	if st.idx == nil && len(st.keys) > objIdxThreshold {
		st.idx = make(map[string]int, len(st.keys)*2)
		for i, k := range st.keys {
			st.idx[k] = i
		}
	}
}

func (o *Object) find(k string) int {
	st := o.st
	if st.idx != nil {
		if i, ok := st.idx[k]; ok && i < o.n {
			return i
		}
		return -1
	}
	if o.n > objIdxThreshold {
		st.ensureIdx()
		if i, ok := st.idx[k]; ok && i < o.n {
			return i
		}
		return -1
	}
	keys := st.keys[:o.n]
	for i, kk := range keys {
		if kk == k {
			return i
		}
	}
	return -1
}

func (o *Object) Get(k string) (Value, bool) {
	i := o.find(k)
	if i < 0 {
		return nil, false
	}
	return o.st.vals[i], true
}

func (o *Object) Has(k string) bool { return o.find(k) >= 0 }

// copyStore makes a fresh store containing this object's entries with room for extra.
func (o *Object) copyStore(extra int) *objStore {
	n := &objStore{
		keys: make([]string, o.n, o.n+extra),
		vals: make([]Value, o.n, o.n+extra),
	}
	copy(n.keys, o.st.keys[:o.n])
	copy(n.vals, o.st.vals[:o.n])
	return n
}

