// ---- append-friendly arrays ----
//
// Arrays are plain []Value slices. To make repeated appends (e.g. in reduce) amortized O(1)
// without breaking value semantics, arrays created by arrAppend carry a hidden *arrBox in the
// last slot of their backing array (beyond any valid length). The box records the committed
// length of the backing, so only the latest version may append in place.

type arrBox struct {
	committed int
	base      unsafe.Pointer
}

const valueSize = unsafe.Sizeof(Value(nil))

func boxOf(a []Value) (*arrBox, int) {
	c := cap(a)
	if c == 0 || len(a) >= c {
		return nil, 0
	}
	full := a[:c]
	b, ok := full[c-1].(*arrBox)
	if !ok {
		return nil, 0
	}
	data := unsafe.Pointer(unsafe.SliceData(full))
	if uintptr(data) < uintptr(b.base) {
		return nil, 0
	}
	off := int((uintptr(data) - uintptr(b.base)) / valueSize)
	return b, off
}

func newBoxed(elems []Value, extraCap int) []Value {
	n := len(elems)
	total := n + extraCap + 1
	if total < 8 {
		total = 8
	}
	backing := make([]Value, total)
	copy(backing, elems)
	b := &arrBox{committed: n, base: unsafe.Pointer(unsafe.SliceData(backing))}
	backing[total-1] = b
	return backing[:n:total]
}

// arrAppend returns a new array value consisting of a followed by elems.
func arrAppend(a []Value, elems ...Value) []Value {
	if len(elems) == 0 {
		return a
	}
	if b, off := boxOf(a); b != nil {
		end := off + len(a)
		backingCap := off + cap(a) // total slots including box
		if b.committed == end && end+len(elems) <= backingCap-1 {
			full := a[:cap(a)]
			copy(full[len(a):], elems)
			b.committed = end + len(elems)
			return a[:len(a)+len(elems)]
		}
	}
	grow := len(a) + len(elems)
	if grow < 16 {
		grow = 16
	}
	out := newBoxed(a, grow)
	full := out[:cap(out)]
	copy(full[len(a):], elems)
	n := len(a) + len(elems)
	bx, _ := boxOf(out)
	bx.committed = n
	return out[:n]
}

// arrCollector helps build arrays element by element.
type arrCollector struct {
	a []Value
}

func (c *arrCollector) add(v Value) {
	if c.a == nil {
		c.a = newBoxed(nil, 8)
	}
	c.a = arrAppend(c.a, v)
}

func (c *arrCollector) result() []Value {
	if c.a == nil {
		return []Value{}
	}
	return c.a
}
