// ---- boxed small integer cache ----

const smallIntCacheSize = 16384

var smallIntCache = func() []Value {
	c := make([]Value, smallIntCacheSize)
	for i := range c {
		c[i] = float64(i)
	}
	return c
}()

// boxNum converts a float64 to a Value, avoiding allocation for small non-negative integers.
func boxNum(f float64) Value {
	if f >= 0 && f < smallIntCacheSize {
		i := int(f)
		if float64(i) == f {
			if i == 0 && math.Signbit(f) {
				return f
			}
			return smallIntCache[i]
		}
	}
	return f
}
EOF
