// ---- amortized string concatenation ----
//
// Repeated concatenation (e.g. in reduce) would be quadratic with immutable Go strings.
// For large results we allocate the backing buffer with spare capacity and remember the
// committed length; a later concat onto the latest version appends in place (the bytes
// beyond a string's length are invisible to it, so value semantics are preserved).

type strBuf struct {
	buf       []byte
	committed int
}

var strBufs = map[uintptr]*strBuf{}

const strConcatMin = 128
const strBufsMax = 2048

func concatStrings(a, b string) string {
	if len(b) == 0 {
		return a
	}
	if len(a) == 0 {
		return b
	}
	total := len(a) + len(b)
	if total < strConcatMin {
		return a + b
	}
	if len(a) > 0 {
		ptr := uintptr(unsafe.Pointer(unsafe.StringData(a)))
		if sb, ok := strBufs[ptr]; ok && sb.committed == len(a) && total <= cap(sb.buf) {
			copy(sb.buf[len(a):total], b)
			sb.committed = total
			return unsafe.String(unsafe.SliceData(sb.buf), total)
		}
	}
	newCap := total * 2
	buf := make([]byte, total, newCap)
	copy(buf, a)
	copy(buf[len(a):], b)
	if len(strBufs) >= strBufsMax {
		strBufs = map[uintptr]*strBuf{}
	}
	strBufs[uintptr(unsafe.Pointer(unsafe.SliceData(buf)))] = &strBuf{buf: buf, committed: total}
	return unsafe.String(unsafe.SliceData(buf), total)
}
EOF
