func mergeObjects(a, b *Object) *Object {
	if b.Len() == 0 {
		return a
	}
	if a.Len() == 0 {
		return b
	}
	anyExisting := false
	for _, k := range b.Keys() {
		if a.Has(k) {
			anyExisting = true
			break
		}
	}
	if !anyExisting {
		res := a
		for i, k := range b.Keys() {
			res = res.Set(k, b.Vals()[i])
		}
		return res
	}
	n := a.Copy()
	for i, k := range b.Keys() {
