// ---- ownership-aware updates (used by assignment operators) ----

type ownedSet map[uintptr]bool

func arrKey(a []Value) uintptr {
	if cap(a) == 0 {
		return 0
	}
	return uintptr(unsafe.Pointer(unsafe.SliceData(a[:cap(a)])))
}

func objKey(o *Object) uintptr { return uintptr(unsafe.Pointer(o)) }

// setpathOwned is like setpath but mutates containers created during this update sequence.
func setpathOwned(t Value, path []Value, v Value, owned ownedSet) (Value, error) {
	if len(path) == 0 {
		return v, nil
	}
	k := path[0]
	rest := path[1:]
	switch kv := k.(type) {
	case string:
		switch tv := t.(type) {
		case *Object:
			cur, _ := tv.Get(kv)
			nv, err := setpathOwned(cur, rest, v, owned)
			if err != nil {
				return nil, err
			}
			if owned[objKey(tv)] {
				tv.SetInPlace(kv, nv)
				return tv, nil
			}
			c := tv.Copy()
			c.SetInPlace(kv, nv)
			owned[objKey(c)] = true
			return c, nil
		case nil:
			nv, err := setpathOwned(nil, rest, v, owned)
			if err != nil {
				return nil, err
			}
			c := NewObject()
			c.SetInPlace(kv, nv)
			owned[objKey(c)] = true
			return c, nil
		}
	case float64, *LitNum:
		switch tv := t.(type) {
		case []Value:
			d := numVal(kv)
			if !math.IsNaN(d) {
				idx := jvArrayIndex(d)
				if idx < 0 {
					idx += len(tv)
				}
				if idx >= 0 && idx < len(tv) {
					nv, err := setpathOwned(tv[idx], rest, v, owned)
					if err != nil {
						return nil, err
					}
					if owned[arrKey(tv)] {
						tv[idx] = nv
						return tv, nil
					}
					c := make([]Value, len(tv))
					copy(c, tv)
					c[idx] = nv
					owned[arrKey(c)] = true
					return c, nil
				}
			}
			// growth or errors: generic path, result is fresh
			nv, err := setpath(nil, rest, v)
			if err != nil {
				return nil, err
			}
			res, err := arraySet(tv, d, nv)
			if err != nil {
				return nil, err
			}
			if ra, ok := res.([]Value); ok {
				owned[arrKey(ra)] = true
			}
			return res, nil
		case nil:
			nv, err := setpathOwned(nil, rest, v, owned)
			if err != nil {
				return nil, err
			}
			res, err := arraySet(nil, numVal(kv), nv)
			if err != nil {
				return nil, err
			}
			if ra, ok := res.([]Value); ok {
				owned[arrKey(ra)] = true
			}
			return res, nil
		}
	}
	return setpath(t, path, v)
}
