// fdlibm-style log10 (as used by glibc/musl): log10(x) = y*log10_2lo + ivln10*log(x) + y*log10_2hi
func fdLog10(x float64) float64 {
	const (
		two54     = 1.80143985094819840000e+16
		ivln10    = 4.34294481903251816668e-01
		log10_2hi = 3.01029995663611771306e-01
		log10_2lo = 3.69423907715893078616e-13
	)
	if math.IsNaN(x) || math.IsInf(x, 0) || x <= 0 {
		return math.Log10(x)
	}
	bits := math.Float64bits(x)
	hx := int32(bits >> 32)
	k := int32(0)
	if hx < 0x00100000 {
		k -= 54
		x *= two54
		bits = math.Float64bits(x)
		hx = int32(bits >> 32)
	}
	k += (hx >> 20) - 1023
	i := int32((uint32(k) & 0x80000000) >> 31)
	hx = (hx & 0x000fffff) | ((0x3ff - i) << 20)
	y := float64(k + i)
	bits = (uint64(uint32(hx)) << 32) | (bits & 0xffffffff)
	x = math.Float64frombits(bits)
	z := y*log10_2lo + ivln10*crLog(x)
	return z + y*log10_2hi
}
